# -*- coding: utf-8 -*-
"""hoang hiep — CaravanRoutes 1.61 + SROMix 0.39, one phBot plugin.
Install ONLY this file in Plugins; disable the two original plugins.
Existing per-character configuration and TXT route locations are preserved.
The embedded sources run in isolated namespaces to prevent global/callback collisions.
Chat, return and ferry authorization use the saved main Leader(s) list.
"""
import QtBind as _qt
import phBot as _bot
import sys as _sys
import types as _types
import time as _time

pName = 'hoang hiep'
pVersion = '2.30'
gui = _qt.init(__name__, pName + ' v' + pVersion)
_hh_active_page = 'caravan'
_hh_modules = {}
_hh_panels = {}
_hh_hook_errors = {}


class _Panel:
    """Share one QtBind GUI, preserving each engine's widget coordinates/state."""
    _positions = {
        'createLabel': (2, 3), 'createLineEdit': (2, 3),
        'createButton': (3, 4), 'createCheckBox': (3, 4),
        'createList': (1, 2), 'createCombobox': (1, 2),
    }
    _obsolete_callbacks = {
        'shared_mode_changed', 'shared_save', 'come_save_clicked',
        'ferry_save_leader_only', 'ferry_use_current_leader',
        'save_member_ferry_leaders', 'show_chat_view', 'show_ferry_view',
        'show_caravan_view', 'show_route_view',
    }
    _obsolete_text = (
        'Leader rieng:', 'Leaders rieng (cach nhau dau ,):',
        'Leader chung (1 ten):', 'Tat Leader chung = dung 2 o Leader rieng.',
        'Leader phà riêng:',
        'Cấu hình Party', 'Tuyến buôn', 'Cấu hình bảo tiêu', 'Cấu hình buôn phụ',
    )

    def __init__(self, page):
        self.page = page
        self.widgets = {}
        self.hidden = set()

    def init(self, *args):
        return gui

    def _coordinates(self, x, y):
        if self.page == 'guard':
            return x, y
        # phBot's plugin canvas is only about 300px tall. Do not stack
        # another navigation row above the original forms.
        if self.page == 'caravan':
            return x, y-18 if y>=48 else y
        if y < 0:
            return x, y
        if x >= 500:
            if y == 291:
                return x, 280
            if y in (5, 22):
                return x, (31 if y == 5 else 45)
            if y in (147, 164):
                return x, (156 if y == 147 else 170)
            for top, target in ((39, 60), (181, 185)):
                for index in range(6):
                    if y == top + index * 18:
                        return x, target + index * 15
                    if y == top + index * 18 + 1:
                        return x, target + index * 15 + 1
            return x, y
        if y == 316:
            return 310, 5  # Short status in the free space beside the main tabs.
        if y in (8, 10, 7):
            return x, {8: 30, 10: 32, 7: 29}[y]
        if y == 36:
            return x, 55
        if y in (63, 67):
            return x, (79 if y == 63 else 83)
        if 86 <= y <= 220:
            return x, 99 + round((y - 86) * 19 / 22)
        if y in (244, 266, 269, 291):
            return x, {244: 238, 266: 258, 269: 261, 291: 278}[y]
        return x, y

    def _place(self, widget):
        module = _hh_modules.get(self.page)
        if self.page == 'caravan' and module and widget in (getattr(module,'setup_heading',None), getattr(module,'party_heading',None)):
            self.hidden.add(widget)
        x, y = self._coordinates(*self.widgets[widget])
        visible = self.page == _hh_active_page and widget not in self.hidden
        _qt.move(gui, widget, x if visible else -5000, y)

    def setText(self, panel, widget, text):
        module = _hh_modules.get(self.page)
        if self.page == 'mix' and module and widget == getattr(module, 'status', None):
            message = str(text)
            text = message if len(message) <= 40 else message[:37] + '...'
        return _qt.setText(gui, widget, text)

    def refresh(self):
        for widget in self.widgets:
            self._place(widget)

    def move(self, panel, widget, x, y):
        self.widgets[widget] = (x, y)
        self._place(widget)

    def __getattr__(self, name):
        if name not in self._positions:
            return getattr(_qt, name)
        def create(*args):
            values = list(args)
            xi, yi = self._positions[name]
            x, y = values[xi], values[yi]
            blocked = False
            if name in ('createButton', 'createCheckBox'):
                callback = values[1]
                blocked = self.page == 'caravan' and callback in self._obsolete_callbacks
                exported = '_hh_' + self.page + '_' + callback
                if exported not in globals():
                    def dispatch(*a, **kw):
                        if self.page == 'caravan' and callback in (
                                'show_caravan_view', 'show_route_view', 'show_ferry_view', 'show_chat_view'):
                            _hh_select('caravan')
                        return _hh_modules[self.page].__dict__[callback](*a, **kw)
                    globals()[exported] = dispatch
                values[1] = exported
            if name == 'createLabel' and self.page == 'caravan':
                blocked = blocked or any(text in str(values[1]) for text in self._obsolete_text)
            if self.page == 'mix' and name == 'createLineEdit' and x >= 500:
                values[5] = 15  # 12 shopping rows fit without overlapping their fields.
            if self.page == 'mix' and name == 'createLineEdit' and x < 500 and 110 <= y <= 220:
                values[5] = 18
            if self.page == 'mix' and name == 'createLabel' and y == 316:
                values[1] = str(values[1])[:40]
            values[xi] = -5000  # Hide until recorded, avoiding flashes from other pages.
            widget = getattr(_qt, name)(*values)
            self.widgets[widget] = (x, y)
            if blocked:
                self.hidden.add(widget)
            self._place(widget)
            return widget
        return create


def _hh_select(page):
    global _hh_active_page
    _hh_active_page = page
    for panel in _hh_panels.values():
        panel.refresh()
    for name, widget in _hh_top_buttons.items():
        for method in ('setStyleSheet', 'setStylesheet', 'setStyle'):
            setter = getattr(_qt, method, None)
            if callable(setter):
                try:
                    setter(gui, widget, 'QPushButton { color: %s; font-weight: bold; }' %
                           ('#68ADFF' if name == page else '#DDDDDD'))
                    break
                except Exception:
                    pass


def hh_show_caravan():
    _hh_select('caravan')


def hh_show_mix():
    _hh_select('mix')


def hh_show_guard():
    _hh_select('guard')


_hh_top_buttons = {
    'caravan': _qt.createButton(gui, 'hh_show_caravan', '  Chạy buôn  ', 12, 0),
    'mix': _qt.createButton(gui, 'hh_show_mix', '  Mua đá / Ép đồ  ', 134, 0),
    'guard': _qt.createButton(gui, 'hh_show_guard', 'Bảo kê Trade', 278, 0),
}
_qt.createLabel(gui, '<span style="color:#8be9ed;font-size:14px;"><b>hoang hiep v2.17</b></span>', 590, 3)


def _hh_load(page, source):
    panel = _Panel(page)
    _hh_panels[page] = panel
    module = _types.ModuleType(__name__ + '_' + page)
    module.__file__ = __file__
    module.__dict__['_hh_qt'] = panel
    if page == 'guard':
        module.__dict__['caravan'] = _hh_modules['caravan']
    _hh_modules[page] = module
    _sys.modules[module.__name__] = module
    # Only replace this explicit module import; phBot imports keep their original behavior.
    source = source.replace('import QtBind\n', 'QtBind = _hh_qt\n')
    exec(compile(source, __file__ + ':' + page, 'exec'), module.__dict__)
    return module


_HH_CARAVAN_SOURCE = '"""Multi-account phBot caravan controller. Explicit GO resumes checkpointed routes; no automatic reconnect resume.\nInstall this file and scripts/ together under Plugins/.\nMerchant script retains server-specific oldtrade commands from the supplied route.\n"""\nimport phBot as bot\nimport phBotChat\nimport QtBind\nimport os\nimport json\nimport hashlib\nimport tempfile\nimport time\nimport uuid\nimport math\nimport base64\nimport threading\nimport sys\nimport struct\n\n# QtBind labels support rich text. Native buttons, checkboxes and edit fields\n# retain phBot\'s own font; never pass HTML into editable values or button captions.\nimport html\nreadable_labels=set()\n\ndef readable_markup(value):\n    text=str(value)\n    if text.startswith(\'<span\'):\n        return text  # Preserve existing colored navigation markers.\n    return \'<span style="font-size:12px;">\'+html.escape(text)+\'</span>\'\n\n\ndef readable_label(panel,text,x,y):\n    widget=QtBind.createLabel(panel,readable_markup(text),x,y)\n    readable_labels.add(widget)\n    return widget\n\n\ndef readable_set_text(panel,widget,text):\n    QtBind.setText(panel,widget,readable_markup(text) if widget in readable_labels else text)\n\n\nVERSION = \'1.61\'\nNPC_PACKET_CLOSE_ENABLED = False  # Native phBot owns NPC close; no forced 704B by caravan.\nBASE = os.path.dirname(os.path.abspath(__file__))\ngui = QtBind.init(__name__, \'CaravanRoutes \' + VERSION)\n\n# One compact 740x300 canvas: Party | Routes | Party management.\n# Engine variable names remain unchanged to preserve existing settings/hooks.\nui_registry = {}\n\n\n\ndef hh_control(name, kind, x, y, *args):\n    handle = readable_label(gui, args[0], x, y) if kind == \'createLabel\' else getattr(QtBind, kind)(gui, *args, x, y)\n    ui_registry[name] = (handle, x, y)\n    return handle\n\n\ndef hh_field(name, x, y, width, initial=\'\'):\n    handle = QtBind.createLineEdit(gui, initial, x, y, width, 18)\n    ui_registry[name] = (handle, x, y)\n    return handle\n\n\ndef panel_heading(text, x, y):\n    return readable_label(gui, \'<span style="color:#8be9ed;font-size:13px;"><b>\'+html.escape(text)+\'</b></span>\', x, y)\n\n\nhh_frames = []  # Native widgets and headings do not depend on HTML table sizing.\nsetup_heading = panel_heading(\'Cấu hình Party\', 8, 27)\nparty_heading = panel_heading(\'Quản lý Party\', 548, 27)\ntransport_heading = panel_heading(\'Khi thú chết\', 548, 137)\nhh_controls_heading = panel_heading(\'Điều khiển chung\', 8, 212)\n\nleaders_label = hh_control(\'leaders_label\', \'createLabel\', 8, 51, \'Leader(s):\')\nleaders_box = hh_field(\'leaders_box\', 76, 48, 110)\nbtn_use_me = hh_control(\'btn_use_me\', \'createButton\', 189, 47, \'use_me\', \'Lấy tên\')\nhunter_check = hh_control(\'hunter_check\', \'createCheckBox\', 8, 72, \'role_changed\', \'Bảo tiêu\')\nfollower_check = hh_control(\'follower_check\', \'createCheckBox\', 112, 72, \'follower_changed\', \'Buôn phụ\')\nfollow_label = hh_control(\'follow_label\', \'createLabel\', 8, 99, \'Tên nhận lệnh:\')\nfollow_box = hh_field(\'follow_box\', 92, 96, 151)\nsell_team_check = hh_control(\'sell_team_check\', \'createCheckBox\', 8, 119, \'sell_team_changed\', \'Bán cả đội\')\nscript_check = hh_control(\'script_check\', \'createCheckBox\', 126, 119, \'select_main_script\', \'Script TXT\')\nscript_box = hh_field(\'script_box\', 8, 142, 230, \'trade_trip\')\nbtn_choose_script = hh_control(\'btn_choose_script\', \'createButton\', 179, 141, \'choose_script\', \'Chọn TXT\')\npurchase_label = hh_control(\'purchase_label\', \'createLabel\', 8, 167, \'Mua đủ:\')\nbuy_goods_box = hh_field(\'buy_goods_box\', 63, 164, 36, \'280\')\nescort_20_check = hh_control(\'escort_20_check\', \'createCheckBox\', 107, 164, \'escort_20_changed\', \'20m\')\nescort_30_check = hh_control(\'escort_30_check\', \'createCheckBox\', 153, 164, \'escort_30_changed\', \'30m\')\nescort_50_check = hh_control(\'escort_50_check\', \'createCheckBox\', 199, 164, \'escort_50_changed\', \'50m\')\nbtn_save_settings = hh_control(\'btn_save_settings\', \'createButton\', 8, 185, \'save_settings\', \'Lưu cấu hình\')\n\nparty_list = QtBind.createCombobox(gui, 548, 48, 100, 20)\nui_registry[\'party_list\'] = (party_list, 548, 48)\nbtn_invite_selected = hh_control(\'btn_invite_selected\', \'createButton\', 636, 47, \'invite_selected\', \'Mời nhóm\')\nbtn_kick_selected = hh_control(\'btn_kick_selected\', \'createButton\', 636, 72, \'kick_selected\', \'Kích nhóm\')\nbtn_refresh_party_list = hh_control(\'btn_refresh_party_list\', \'createButton\', 548, 108, \'refresh_party_list\', \'Cập nhật\')\nbtn_diagnose_follow = hh_control(\'btn_diagnose_follow\', \'createButton\', 628, 108, \'diagnose_follow\', \'Kiểm tra\')\ntransport_stop_check = hh_control(\'transport_stop_check\', \'createCheckBox\', 548, 158, \'transport_stop_changed\', \'Dừng im\')\ntransport_return_check = hh_control(\'transport_return_check\', \'createCheckBox\', 548, 176, \'transport_return_changed\', \'Về thành\')\ntransport_recover_check = hh_control(\'transport_recover_check\', \'createCheckBox\', 548, 194, \'transport_recover_changed\', \'Về > Ngược > Nhặt > Đi\')\n\n# One shared set of actions, never recreated in the routes panel.\nbtn_local_go = hh_control(\'btn_local_go\', \'createButton\', 8, 233, \'local_go\', \'Tiếp tục\')\nbtn_local_stop = hh_control(\'btn_local_stop\', \'createButton\', 88, 233, \'local_stop\', \'Tạm dừng\')\nnew_start_check = hh_control(\'new_start_check\', \'createButton\', 181, 233, \'route_new_start\', \'Bắt đầu mới\')\nstep_label = hh_control(\'step_label\', \'createLabel\', 291, 237, \'Bước:\')\nstep_box = hh_field(\'step_box\', 329, 233, 34, \'0\')\nloop_on_check = hh_control(\'loop_on_check\', \'createCheckBox\', 378, 235, \'loop_on_changed\', \'Lặp: GO\')\nloop_off_check = hh_control(\'loop_off_check\', \'createCheckBox\', 464, 235, \'loop_off_changed\', \'Lặp: STOP\')\nbtn_sell_team = hh_control(\'btn_sell_team\', \'createButton\', 568, 233, \'sell_team\', \'Bán ngay\')\nloop_label = hh_control(\'loop_label\', \'createLabel\', 651, 237, \'Lặp: TẮT\')\ntracking_heading = hh_control(\'tracking_heading\', \'createLabel\', 8, 260, \'Theo dõi:\')\nbtn_activate_follow = hh_control(\'btn_activate_follow\', \'createButton\', 76, 257, \'activate_follow\', \'Bắt đầu theo dõi\')\nbtn_stop_following = hh_control(\'btn_stop_following\', \'createButton\', 199, 257, \'stop_following\', \'Dừng theo dõi\')\nbtn_team_follow = hh_control(\'btn_team_follow\', \'createButton\', 310, 257, \'team_follow\', \'Gọi đội theo\')\nbtn_team_unfollow = hh_control(\'btn_team_unfollow\', \'createButton\', 411, 257, \'team_unfollow\', \'Dừng đội theo\')\nstatus_label = hh_control(\'status_label\', \'createLabel\', 8, 281, \'Trạng thái: Chờ đăng nhập\')\n\nrole_label = hh_control(\'role_label\', \'createLabel\', -2000, 79, \'Vai trò:\')\nradius_label = hh_control(\'radius_label\', \'createLabel\', -2000, 137, \'Phạm vi:\')\n\nauto_party_check = hh_control(\'auto_party_check\', \'createCheckBox\', 125, 185, \'auto_party_changed\', \'Tự lập PT 40m\')\n\nauto_follow_party_check = hh_control(\'auto_follow_party_check\',\'createCheckBox\',260,185,\'auto_follow_party_changed\',\'Tự theo khi vào PT\')\n\nparty_rows = {}\nidentity = None\nconfig = None\nactive = False\nstate = \'Dung\'\nseen = {}\nlast_go = float(\'-inf\')\nlast_return = float(\'-inf\')\nPREFIX = \'!CR1 \'\nfollow_mode = None\nstandalone_follow = False\ntrade_followers = {}\nparty_hunters = set()\nfollower_wait = None\nfollower_bypass = set()\nfollower_monitor = {}\nnotice_times = {}\nfollow_blocked = False\nfollow_intent = None\nfollow_stop_guard = None\nfollow_stop_sent = {}\ncontrol_incoming = \'party\'\nfollower_mount_guard = {}\nfollower_probe = None\nlast_follower_probe = float(\'-inf\')\nlast_follow_move = float(\'-inf\')\nfollow_missing_since = None\nfollow_party_missing_since = None\ntrip = None\ntrip_lines = []\nmerchant_step = None\ntransport_cache = {}\nrecovery = None\nfinish_context = None\nloop_enabled = False\nloop_pending = None\nloop_return = None\nfollow_override = None\nfollow_request = None\ntransport_ui_updating = False\nloop_ui_updating = False\nroute_loop_checks = []\nescort_state = None\ncombat_area_backup = None\nlast_combat_anchor = float(\'-inf\')\nescort_ui_updating = False\nescort_monitor = {}\npickup_key_runtime = None\npickup_user32 = None\npickup_input_type = None\nfollower_state = None\nconvoy_controller = None\nlocal_sale = None\ncompleted_sale = None\nreturn_request = None\nselected_npc = None\nlast_trade_shop = None\ntrade_npc_close = None\nnative_trade_context = None\ntrade_fault = None\nnpc_session = {\'owner\': None, \'generation\': 0, \'uid\': None, \'state\': \'unknown\', \'closed_at\': None}\n\n\ndef refresh_optional_controls():\n    # Move widgets only: hidden controls retain their values and saved route selection.\n    global control_view\n    control_view = \'caravan\'\n    hunter = bool(QtBind.isChecked(gui, hunter_check))\n    follower = bool(QtBind.isChecked(gui, follower_check)) and not hunter\n    if hunter or follower:\n        positions = {\n            \'leaders_label\': (8, 51), \'leaders_box\': (100, 48),\n            \'role_label\': (8, 79), \'hunter_check\': (100, 76), \'follower_check\': (210, 76),\n            \'follow_label\': (8, 107), \'follow_box\': (100, 104),\n            \'btn_save_settings\': (100, 168), \'status_label\': (8, 224),\n            \'auto_party_check\': (100, 192),\n            \'btn_activate_follow\': (390, 57), \'btn_stop_following\': (520, 57),\n            \'btn_diagnose_follow\': (390, 95),\n            \'party_list\': (390, 150), \'btn_invite_selected\': (484, 149),\n            \'btn_kick_selected\': (484, 174), \'btn_refresh_party_list\': (484, 199),\n        }\n        if hunter:\n            positions.update(radius_label=(8, 137), escort_20_check=(100, 134),\n                             escort_30_check=(164, 134), escort_50_check=(228, 134))\n        else:\n            positions.update(purchase_label=(8, 135), buy_goods_box=(100, 132),\n                script_check=(8, 158), script_box=(8, 182), btn_choose_script=(179, 181),\n                btn_save_settings=(8, 220), auto_party_check=(125, 220), status_label=(8, 260),\n                transport_stop_check=(390, 50), transport_return_check=(390, 72),\n                transport_recover_check=(390, 94),\n                btn_local_go=(390, 150), btn_local_stop=(470, 150),\n                btn_activate_follow=(390, 177), btn_stop_following=(390, 201),\n                btn_diagnose_follow=(390, 226),\n                party_list=(548, 150), btn_invite_selected=(636, 149),\n                btn_kick_selected=(636, 174), btn_refresh_party_list=(636, 199))\n        for name, (widget, x, y) in ui_registry.items():\n            px, py = positions.get(name, (-2000, y))\n            QtBind.move(gui, widget, px, py)\n    else:\n        for widget, x, y in ui_registry.values():\n            QtBind.move(gui, widget, x, y)\n    readable_set_text(gui, setup_heading,\n        \'<span style="color:#8be9ed;font-size:13px;"><b>\' +\n        (\'Cấu hình bảo tiêu\' if hunter else \'Cấu hình buôn phụ\' if follower else \'Cấu hình Party\') + \'</b></span>\')\n    readable_set_text(gui, hh_controls_heading,\n        \'<span style="color:#8be9ed;font-size:13px;"><b>\' +\n        (\'Theo dõi\' if hunter else \'Điều khiển\' if follower else \'Điều khiển chung\') + \'</b></span>\')\n    QtBind.move(gui, setup_heading, 8, 27)\n    QtBind.move(gui, party_heading, 390 if hunter else 548, 128 if hunter or follower else 27)\n    QtBind.move(gui, transport_heading, 390 if follower else -2000 if hunter else 548, 27 if follower else 137)\n    QtBind.move(gui, hh_controls_heading, 390 if hunter or follower else 8,\n                27 if hunter else 127 if follower else 212)\n    for widget, x, y in globals().get(\'route_widgets\', []):\n        QtBind.move(gui, widget, -2000 if hunter or follower else x, y)\n    for widget, x, y, view in globals().get(\'ferry_widgets\', []):\n        QtBind.move(gui, widget, -2000, y)\n    for view, button, x in globals().get(\'navigation_tabs\', []):\n        QtBind.move(gui, button, -2000, 0)\n    for name in (\'member_ferry_label\', \'member_ferry_leaders\', \'member_ferry_save\'):\n        widget = globals().get(name)\n        if widget is not None:\n            QtBind.move(gui, widget, -2000, 0)\n\n\n\n\ndef sell_team_changed(checked):\n    say(\'Ban ca doi: \' + (\'BAT - cuoi tuyen ban hang, huy thu, Party VE.\' if checked else \'TAT - thuc hien lenh cuoi tuyen trong TXT.\') + \' Luu cau hinh de ap dung.\')\n\n\ndef sync_loop_checks():\n    global loop_ui_updating\n    loop_ui_updating = True\n    try:\n        allowed = loop_controls_allowed()\n        QtBind.setChecked(gui, loop_on_check, allowed and loop_enabled)\n        QtBind.setChecked(gui, loop_off_check, allowed and not loop_enabled)\n        for checkbox, enabled in route_loop_checks:\n            QtBind.setChecked(gui, checkbox, allowed and loop_enabled == enabled)\n    finally:\n        loop_ui_updating = False\n\n\ndef loop_on_changed(checked):\n    if loop_ui_updating:\n        return\n    if checked:\n        team_loop_on()\n    elif loop_enabled:\n        set_loop(False)\n    sync_loop_checks()\n\n\ndef loop_off_changed(checked):\n    if loop_ui_updating:\n        return\n    if checked:\n        team_loop_off()\n    sync_loop_checks()\n\n\ndef selected_transport_mode():\n    for mode, widget in ((1, transport_stop_check), (2, transport_return_check), (3, transport_recover_check)):\n        if QtBind.isChecked(gui, widget):\n            return mode\n    return 0\n\n\ndef select_transport_option(mode, checked):\n    global transport_ui_updating\n    if transport_ui_updating:\n        return\n    transport_ui_updating = True\n    try:\n        if checked:\n            for value, widget in ((1, transport_stop_check), (2, transport_return_check), (3, transport_recover_check)):\n                QtBind.setChecked(gui, widget, value == mode)\n        if recovery and (not checked or recovery.get(\'mode\') != mode):\n            cancel_recovery(restore=True)\n            set_state(\'Da dung thu hoi tu dong do doi lua chon\')\n        if config:\n            config[\'transport_enabled\'] = bool(selected_transport_mode())\n            config[\'transport_mode\'] = selected_transport_mode() or 1\n    finally:\n        transport_ui_updating = False\n    say(\'Thu chet: \' + (str(selected_transport_mode()) if selected_transport_mode() else \'TAT - khong xu ly\'))\n\n\ndef transport_stop_changed(checked):\n    select_transport_option(1, checked)\n\n\ndef transport_return_changed(checked):\n    select_transport_option(2, checked)\n\n\ndef transport_recover_changed(checked):\n    select_transport_option(3, checked)\n\n\ndef loop_controls_allowed():\n    return True\n\n\ndef transport_feature_allowed():\n    return bool(selected_transport_mode())\n\n\ndef say(text):\n    bot.log(\'[CaravanRoutes] \' + text)\n\n\n\ndef say_throttled(key, message, interval=30):\n    scope=(identity,key)\n    now=time.monotonic()\n    if now-notice_times.get(scope,float(\'-inf\'))>=interval:\n        notice_times[scope]=now\n        say(message)\n\n\ndef norm(name):\n    return str(name or \'\').strip().lstrip(\'*\').casefold()\n\n\ndef names(text):\n    return {norm(n) for n in text.replace(\';\', \',\').split(\',\') if norm(n)}\n\n\ndef current_identity():\n    c = bot.get_character_data() or {}\n    return (c.get(\'server\', \'\'), c[\'name\']) if c.get(\'name\') else None\n\n\ndef own_names():\n    c = bot.get_character_data() or {}\n    return {norm(c.get(k)) for k in (\'name\', \'job_name\') if c.get(k)}\n\n\ndef path_for(key):\n    digest = hashlib.sha256(json.dumps(key).encode(\'utf-8\')).hexdigest()\n    return os.path.join(bot.get_config_dir(), \'CaravanRoutes\', digest + \'.json\')\n\n\ndef set_state(text):\n    global state\n    state = text\n    value = str(text)\n    readable_set_text(gui, status_label, \'Trạng thái: \' + (value if len(value) <= 105 else value[:102] + \'...\'))\n\n\n\ndef read_form():\n    leader = QtBind.text(gui, leaders_box).strip()\n    if not names(leader):\n        raise ValueError(\'Nhap it nhat mot Leader\')\n    mode = selected_transport_mode() or 1\n    hunter = bool(QtBind.isChecked(gui, hunter_check))\n    follower = bool(QtBind.isChecked(gui, follower_check)) and not hunter\n    text = QtBind.text(gui, follow_box).strip()\n    try:\n        buy_goods=int(QtBind.text(gui,buy_goods_box).strip() or \'280\')\n        if not 1<=buy_goods<=65535:\n            raise ValueError()\n    except ValueError:\n        if follower:\n            raise ValueError(\'Mua du: nhap so hang tu 1 den 65535\')\n        buy_goods=int((config or {}).get(\'buy_goods\',280))\n    sell_team = bool(QtBind.isChecked(gui, sell_team_check))\n    return {\'hide_internal_chat\': bool(QtBind.isChecked(gui, hide_internal_chat_check)) if \'hide_internal_chat_check\' in globals() else True, \'auto_follow_party\':bool(QtBind.isChecked(gui,auto_follow_party_check)), \'auto_party\':False, \'buy_goods\':buy_goods,\'escort_radius\': selected_escort_radius(), \'loop_controls\': True, \'sell_team\': sell_team, \'transport_enabled\': bool(selected_transport_mode()), \'follower\': follower, \'guards\': text if not (hunter or follower) else (config or {}).get(\'guards\', \'\'), \'finish_come\': sell_team, \'transport_mode\': int(mode), \'leaders\': leader,\n            \'hunter\': bool(QtBind.isChecked(gui, hunter_check)),\n            \'follow\': text if (hunter or follower) else (config or {}).get(\'follow\', \'\'),\n            \'script\': QtBind.text(gui, script_box).strip()}\n\n\ndef apply_form(data):\n    global transport_ui_updating, escort_ui_updating\n    if \'hide_internal_chat_check\' in globals():\n        QtBind.setChecked(gui,hide_internal_chat_check,data.get(\'hide_internal_chat\',True) is True)\n    QtBind.setChecked(gui,auto_follow_party_check,data.get(\'auto_follow_party\',True) is True)\n    QtBind.setChecked(gui, auto_party_check, False)  # Party invitations are manual.\n    escort_ui_updating = True\n    try:\n        radius = data.get(\'escort_radius\', 30 if data.get(\'escort_30m\') else 0)\n        for value, widget in ((20, escort_20_check), (30, escort_30_check), (50, escort_50_check)):\n            QtBind.setChecked(gui, widget, radius == value)\n    finally:\n        escort_ui_updating = False\n    QtBind.setChecked(gui, sell_team_check, bool(data.get(\'sell_team\', False) and data.get(\'finish_come\', True)))\n    sync_loop_checks()\n    transport_ui_updating = True\n    try:\n        for value, widget in ((1, transport_stop_check), (2, transport_return_check), (3, transport_recover_check)):\n            QtBind.setChecked(gui, widget, data.get(\'transport_enabled\', False) and data.get(\'transport_mode\', 1) == value)\n    finally:\n        transport_ui_updating = False\n    readable_set_text(gui,buy_goods_box,str(data.get(\'buy_goods\',280)))\n    readable_set_text(gui, leaders_box, data[\'leaders\'])\n    QtBind.setChecked(gui, hunter_check, data[\'hunter\'])\n    QtBind.setChecked(gui, follower_check, data.get(\'follower\', False) and not data[\'hunter\'])\n    readable_set_text(gui, follow_label, \'Leader đi theo:\' if data.get(\'follower\') else (\'Theo acc buôn:\' if data[\'hunter\'] else \'Tên nhận lệnh:\'))\n    readable_set_text(gui, follow_box, data[\'follow\'] if (data[\'hunter\'] or data.get(\'follower\')) else data.get(\'guards\', data.get(\'follow\', \'\')))\n    readable_set_text(gui, script_box, short_script_name(data[\'script\']))\n    refresh_optional_controls()\n\n\ndef load_identity():\n    global identity, config, active, seen, last_go, last_return, follow_mode, trip, trip_lines, merchant_step, recovery, transport_cache, finish_context, follow_override, follow_request, escort_state\n    key = current_identity()\n    if key is None and identity is not None and follow_intent is not None:\n        return  # Character data can be briefly empty during a manual teleport.\n    if key == identity:\n        return\n    clear_convoy()\n    enable_following()\n    follow_stop_sent.clear()\n    globals()[\'return_request\'] = None\n    globals()[\'trade_fault\'] = None\n    globals()[\'selected_npc\'] = None\n    globals()[\'last_trade_shop\'] = None\n    globals()[\'trade_npc_close\'] = None\n    globals()[\'native_trade_context\'] = None\n    npc_session.update(owner=identity, generation=npc_session[\'generation\']+1, uid=None, state=\'unknown\', closed_at=None)\n    follower_mount_guard.clear()\n    globals()[\'follow_party_missing_since\']=None\n    globals()[\'standalone_follow\'] = False\n    globals()[\'follower_probe\'] = None\n    globals()[\'last_follower_probe\'] = float(\'-inf\')\n    trade_followers.clear()\n    party_hunters.clear()\n    follower_bypass.clear()\n    follower_monitor.clear()\n    globals()[\'follower_wait\'] = None\n    globals()[\'buy_departure\']=None\n    globals()[\'completed_sale\'] = None\n    globals()[\'follow_intent\']=None\n    enable_following()\n    follow_stop_sent.clear()\n    party_rows.clear()\n    QtBind.clear(gui, party_list)\n    restore_escort_combat()\n    escort_state = None\n    escort_monitor.clear()\n    set_loop(False)\n    # Restore any temporary pickup settings before changing identity.\n    cancel_recovery(restore=True)\n    transport_cache = {}\n    finish_context = None\n    follow_override, follow_request = None, None\n    # Never stop another character\'s bot when the account changes.\n    identity, config, active, seen = key, None, False, {}\n    follow_mode = None\n    readable_set_text(gui, step_box, \'0\')\n    trip, trip_lines, merchant_step = None, [], None\n    last_go = last_return = float(\'-inf\')\n    apply_form({\'leaders\': \'\', \'hunter\': False, \'follow\': \'\',\n                \'script\': \'trade_trip.txt\'})\n    set_state(\'Dung - can luu cau hinh\' if key else \'Cho dang nhap\')\n    if not key:\n        return\n    try:\n        with open(path_for(key), encoding=\'utf-8\') as stream:\n            data = json.load(stream)\n        if not isinstance(data, dict) or not all(isinstance(data.get(k), str) for k in (\'leaders\', \'follow\', \'script\')) or not isinstance(data.get(\'hunter\'), bool):\n            raise ValueError(\'Cau hinh khong hop le\')\n        apply_form(data)\n        config = read_form()\n        set_state(\'San sang - \' + (\'Bao tieu\' if config[\'hunter\'] else \'Buon\'))\n    except FileNotFoundError:\n        pass\n    except Exception as error:\n        config = None\n        say(\'Khong nap duoc cau hinh: \' + str(error))\n\n\ndef save_settings():\n    global config, follow_override\n    load_identity()\n    if not identity:\n        say(\'Dang nhap truoc khi luu.\')\n        return\n    if active or recovery or loop_pending or loop_return or convoy_controller or local_sale or return_request:\n        say(\'Tat lap / Dung acc nay truoc khi doi cau hinh.\')\n        return\n    temp = None\n    try:\n        data = read_form()\n        path = path_for(identity)\n        os.makedirs(os.path.dirname(path), exist_ok=True)\n        with tempfile.NamedTemporaryFile(mode=\'w\', encoding=\'utf-8\', dir=os.path.dirname(path), delete=False) as stream:\n            temp = stream.name\n            json.dump(data, stream, ensure_ascii=False, indent=2)\n        os.replace(temp, path)\n        temp = None\n        config = data\n        follow_override = None\n        set_state(\'San sang - \' + (\'Bao tieu\' if data[\'hunter\'] else \'Buon\'))\n        say(\'Da luu. Lenh chi nhan tu Leader duoc cho phep trong cung Party; khong can ma doi.\')\n    except Exception as error:\n        say(\'Luu that bai: \' + str(error))\n    finally:\n        if temp and os.path.exists(temp):\n            os.remove(temp)\n\n\ndef use_me():\n    load_identity()\n    c = bot.get_character_data() or {}\n    if c.get(\'name\'):\n        readable_set_text(gui, leaders_box, c[\'name\'])\n\n\ndef follower_changed(checked):\n    if checked:\n        QtBind.setChecked(gui, hunter_check, False)\n    role_changed(False)\n\n\ndef role_changed(checked):\n    if checked:\n        QtBind.setChecked(gui, follower_check, False)\n    # Stop using the old saved role before changing authorization to run scripts.\n    if active or follow_request or convoy_controller or local_sale:\n        stop_owned()\n    following = checked or QtBind.isChecked(gui, follower_check)\n    readable_set_text(gui, follow_label, \'Leader đi theo:\' if QtBind.isChecked(gui, follower_check) else (\'Theo acc buôn:\' if checked else \'Tên nhận lệnh:\'))\n    if config:\n        readable_set_text(gui, follow_box, config.get(\'follow\', \'\') if following else config.get(\'guards\', \'\'))\n    refresh_optional_controls()\n    say(\'Bao tieu: KHONG mua hang. Co the cho lenh tu acc Buon.\' if checked else \'Acc Buon: nhap ten Bao tieu roi bam LEADER: Bat theo. Luu vai tro neu vua doi.\')\n\n\ndef party_member(player):\n    return norm(player) in own_names() or any(norm(player) in {norm(m.get(\'name\')), norm(m.get(\'job_name\'))} for m in (bot.get_party() or {}).values())\n\n\ndef stop_owned():\n    global active, follow_mode, merchant_step, finish_context, follow_request, escort_state\n    globals()[\'trade_npc_close\'] = None\n    globals()[\'native_trade_context\'] = None\n    clear_convoy()\n    if globals().get(\'ferry_pending\') and ferry_pending[-1]:\n        globals()[\'ferry_pending\'] = None\n    globals()[\'follow_intent\']=None\n    globals()[\'buy_departure\']=None\n    follower_mount_guard.clear()\n    globals()[\'follow_party_missing_since\']=None\n    globals()[\'standalone_follow\'] = False\n    globals()[\'follower_wait\'] = None\n    follower_bypass.clear()\n    follower_monitor.clear()\n    globals()[\'return_request\'] = None\n    escort_state = None\n    escort_monitor.clear()\n    restore_escort_combat()\n    follow_request = None\n    finish_context = None\n    cancel_recovery(restore=True)\n    if active:\n        # Merchant owns its script; hunter owns Trace. Do not stop unrelated botting.\n        try:\n            if follow_mode or (config and config[\'hunter\']):\n                bot.stop_trace()\n                c=bot.get_character_data() or {}\n                if \'x\' in c and \'y\' in c:\n                    bot.move_to(c[\'x\'],c[\'y\'],c.get(\'z\',0))\n            else:\n                # Reconcile an arrival before stopping, without dispatching the next step.\n                try:\n                    merchant_tick(advance=False)\n                finally:\n                    bot.stop_script()\n                c = bot.get_character_data() or {}\n                if \'x\' in c and \'y\' in c:\n                    bot.move_to(c[\'x\'], c[\'y\'], c.get(\'z\', 0))\n                merchant_step = None\n                if trip:\n                    persist_trip()\n        finally:\n            active = False\n            follow_mode = None\n    set_state(\'Tam dung - GO tiep tuc\' if trip and config and not config[\'hunter\'] else \'Da dung\')\n\n\ndef local_stop():\n    load_identity()\n    set_loop(False)\n    stop_owned()\n\n\ndef resolve_follow_target(target):\n    matches = [m for m in (bot.get_party() or {}).values()\n               if norm(target) in {norm(m.get(\'name\')), norm(m.get(\'job_name\'))}]\n    return matches[0] if len(matches) == 1 else None\n\n\ndef trusted_leader(player):\n    if not config:\n        return False\n    aliases = {norm(player)}\n    member = resolve_follow_target(player)\n    if member:\n        aliases.update({norm(member.get(\'name\')), norm(member.get(\'job_name\'))})\n    if norm(player) in own_names():\n        aliases.update(own_names())\n    return bool(aliases & names(config[\'leaders\']))\n\n\ndef position_usable(member, character):\n    try:\n        # player_id=0 means the member has not spawned nearby in phBot.\n        if not member.get(\'player_id\') or member.get(\'dead\'):\n            return False\n        if member.get(\'region\') is not None and member[\'region\'] != character.get(\'region\'):\n            return False\n        values = [float(member[\'x\']), float(member[\'y\']), float(character[\'x\']), float(character[\'y\'])]\n        if not all(math.isfinite(v) for v in values):\n            return False\n        return math.hypot(values[0]-values[2], values[1]-values[3]) <= 120\n    except (KeyError, ValueError, TypeError):\n        return False\n\n\ndef follower_position_usable(member,character):\n    # Party coordinates can remain usable even when the Leader is not spawned nearby (UID=0).\n    if not member or member.get(\'dead\') or member.get(\'hp_percent\')==0:\n        return False\n    try:\n        if member.get(\'region\') is not None and member[\'region\']!=character.get(\'region\'):\n            return False\n        x,y,cx,cy=[float(value) for value in (member[\'x\'],member[\'y\'],character[\'x\'],character[\'y\'])]\n        if not all(math.isfinite(value) for value in (x,y,cx,cy)):\n            return False\n        if not member.get(\'player_id\') and x==0 and y==0:\n            return False  # phBot\'s empty-position placeholder is not a real destination.\n        return math.hypot(x-cx,y-cy)<=500\n    except (KeyError,TypeError,ValueError):\n        return False\n\n\ndef diagnose_follow():\n    c = bot.get_character_data() or {}\n    say(\'Acc hien tai: name={} | job_name={} | region={} | x={} y={}\'.format(\n        c.get(\'name\'), c.get(\'job_name\'), c.get(\'region\'), c.get(\'x\'), c.get(\'y\')))\n    for m in (bot.get_party() or {}).values():\n        say(\'Party: name={} | job_name={} | UID={} | x={} y={}\'.format(\n            m.get(\'name\'), m.get(\'job_name\'), m.get(\'player_id\'), m.get(\'x\'), m.get(\'y\')))\n\n\ndef update_position_follow():\n    global last_follow_move, follow_missing_since, follow_party_missing_since\n    if follow_blocked or not active or follow_mode != \'position\' or not config or not (standalone_follow or config[\'hunter\'] or config.get(\'follower\')):\n        return\n    now = time.monotonic()\n    interval=0.45 if config.get(\'follower\') else 1.0\n    if now - last_follow_move < interval:\n        return\n    last_follow_move = now\n    if config.get(\'follower\'):\n        uid,pet=follower_transport_entry()\n        if pet and not pet.get(\'mounted\'):\n            if now>=follower_mount_guard.get(\'next\',float(\'-inf\')):\n                if follower_mount_guard.get(\'tries\',0)>=3:\n                    stop_owned()\n                    say(\'Buon phu: khong len lai duoc thu sau 3 lan; dung, khong tu di bo theo.\')\n                    return\n                follower_mount_guard[\'tries\']=follower_mount_guard.get(\'tries\',0)+1\n                follower_mount_guard[\'next\']=now+5\n                bot.inject_joymax(0x70CB,b\'\\x01\'+struct.pack(\'<I\',uid),False)\n                say(\'Buon phu: phat hien da xuong thu; yeu cau len lai UID=\'+str(uid))\n            set_state(\'Buon phu: doi len lai thu, chua di bo\')\n            return\n        if pet:\n            follower_mount_guard.clear()\n        elif not standalone_follow:\n            stop_owned()\n            say(\'Buon phu: mat thu van tai; dung theo, khong tu di bo.\')\n            return\n    character = bot.get_character_data() or {}\n    member = resolve_follow_target(current_follow_target())\n    usable=follower_position_usable(member,character) if config.get(\'follower\') else bool(member and position_usable(member,character))\n    if not usable:\n        if member is None:\n            if follow_party_missing_since is None:\n                follow_party_missing_since=now\n        else:\n            follow_party_missing_since=None\n        if follow_missing_since is None:\n            follow_missing_since=now\n            if \'x\' in character and \'y\' in character:\n                bot.move_to(character[\'x\'],character[\'y\'],character.get(\'z\',0))\n        if config.get(\'follower\'):\n            if follow_party_missing_since is not None and now-follow_party_missing_since>=15:\n                stop_owned()\n                say(\'Dung theo: khong tim thay Leader trong Party lien tuc 15s. Bat lai khi da vao cung Party.\')\n                return\n            set_state(\'Cho toa do Leader hop le; se tu bam lai\')\n            if now-follow_missing_since>=15:\n                say_throttled(\'follow_wait_data\',\'Buon phu dang cho toa do Leader/cung khu; giu che do theo va tu bam lai khi du lieu tro lai.\',30)\n        elif now-follow_missing_since>=15:\n            stop_owned()\n            say(\'Dung di theo: mat toa do muc tieu 15 giay. Can bat lai.\')\n        return\n    if follow_missing_since is not None and config.get(\'follower\'):\n        say_throttled(\'follow_reacquired\',\'Da co toa do Leader; Buon phu tu dong bam lai tren thu.\',15)\n    follow_missing_since=None\n    follow_party_missing_since=None\n    dx, dy = float(member[\'x\']) - character[\'x\'], float(member[\'y\']) - character[\'y\']\n    distance = math.hypot(dx, dy)\n    gap=3 if config.get(\'follower\') else 5\n    if distance <= gap:\n        set_state(\'Theo toa do: da gan muc tieu (<={}m)\'.format(gap))\n        return\n    # Longer movement targets while catching up avoid repeated short-segment stops.\n    step = min(distance-gap,45 if config.get(\'follower\') else 20)\n    bot.move_to(character[\'x\'] + dx / distance * step,\n                character[\'y\'] + dy / distance * step, 0)\n    set_state(\'Theo toa do: {} | {:.0f}m\'.format(current_follow_target(), distance))\n\n\ndef trip_path(script_path=None):\n    script_path = script_path or (trip or {}).get(\'path\') or selected_script_path()\n    key = hashlib.sha256(os.path.normcase(script_path).encode(\'utf-8\')).hexdigest()[:20]\n    return path_for(identity)[:-5] + \'.\' + key + \'.progress.json\'\n\n\ndef pick_script_file(initial_directory):\n    """Native Windows file picker; no tkinter/PyQt dependency inside phBot."""\n    if os.name != \'nt\':\n        raise OSError(\'Cua so chon file nay can Windows\')\n    import ctypes\n    from ctypes import wintypes\n\n    class OPENFILENAMEW(ctypes.Structure):\n        _fields_ = [\n            (\'lStructSize\', wintypes.DWORD), (\'hwndOwner\', wintypes.HWND),\n            (\'hInstance\', wintypes.HINSTANCE), (\'lpstrFilter\', wintypes.LPCWSTR),\n            (\'lpstrCustomFilter\', wintypes.LPWSTR), (\'nMaxCustFilter\', wintypes.DWORD),\n            (\'nFilterIndex\', wintypes.DWORD), (\'lpstrFile\', wintypes.LPWSTR),\n            (\'nMaxFile\', wintypes.DWORD), (\'lpstrFileTitle\', wintypes.LPWSTR),\n            (\'nMaxFileTitle\', wintypes.DWORD), (\'lpstrInitialDir\', wintypes.LPCWSTR),\n            (\'lpstrTitle\', wintypes.LPCWSTR), (\'Flags\', wintypes.DWORD),\n            (\'nFileOffset\', wintypes.WORD), (\'nFileExtension\', wintypes.WORD),\n            (\'lpstrDefExt\', wintypes.LPCWSTR), (\'lCustData\', ctypes.c_ssize_t),\n            (\'lpfnHook\', ctypes.c_void_p), (\'lpTemplateName\', wintypes.LPCWSTR),\n            (\'pvReserved\', ctypes.c_void_p), (\'dwReserved\', wintypes.DWORD),\n            (\'FlagsEx\', wintypes.DWORD)]\n\n    dialog_dll = ctypes.WinDLL(\'comdlg32\', use_last_error=True)\n    user_dll = ctypes.WinDLL(\'user32\', use_last_error=True)\n    user_dll.GetForegroundWindow.argtypes = []\n    user_dll.GetForegroundWindow.restype = wintypes.HWND\n    dialog_dll.GetOpenFileNameW.argtypes = [ctypes.POINTER(OPENFILENAMEW)]\n    dialog_dll.GetOpenFileNameW.restype = wintypes.BOOL\n    dialog_dll.CommDlgExtendedError.argtypes = []\n    dialog_dll.CommDlgExtendedError.restype = wintypes.DWORD\n    buffer = ctypes.create_unicode_buffer(32768)\n    options = OPENFILENAMEW()\n    options.lStructSize = ctypes.sizeof(options)\n    options.hwndOwner = user_dll.GetForegroundWindow()\n    options.lpstrFilter = \'Script TXT (*.txt)\\0*.txt\\0All files (*.*)\\0*.*\\0\\0\'\n    options.nFilterIndex = 1\n    options.lpstrFile = ctypes.cast(buffer, wintypes.LPWSTR)\n    options.nMaxFile = len(buffer)\n    options.lpstrInitialDir = initial_directory\n    options.lpstrTitle = \'CaravanRoutes - Chon script TXT\'\n    options.lpstrDefExt = \'txt\'\n    # Explorer, existing file/path, hide read-only, never change phBot\'s working directory.\n    options.Flags = 0x00080000 | 0x00001000 | 0x00000800 | 0x00000004 | 0x00000008\n    if dialog_dll.GetOpenFileNameW(ctypes.byref(options)):\n        return buffer.value\n    error = dialog_dll.CommDlgExtendedError()\n    if error:\n        raise OSError(\'Windows file dialog error 0x{:X}\'.format(error))\n    return None  # Cancel leaves the existing selection untouched.\n\n\ndef choose_script():\n    load_identity()\n    if active or recovery or loop_pending or loop_return:\n        say(\'Tat lap / Dung acc nay truoc khi chon script khac.\')\n        return\n    try:\n        try:\n            initial = os.path.dirname(selected_script_path())\n        except (ValueError, OSError):\n            initial = next((d for d in script_directories() if os.path.isdir(d)), BASE)\n        selected = pick_script_file(initial)\n        if not selected:\n            return\n        selected = os.path.abspath(selected)\n        if not os.path.isfile(selected):\n            raise ValueError(\'File da chon khong ton tai\')\n        readable_set_text(gui, script_box, short_script_name(selected))\n        readable_set_text(gui, step_box, \'0\')\n        set_state(\'Da chon: \' + os.path.basename(selected))\n        say(\'Da chon script: \' + selected + \'. Bam Luu cau hinh de giu cho lan sau; GO de dinh vi va chay.\')\n    except Exception as error:\n        say(\'Khong mo/chon duoc TXT: \' + str(error))\n\n\ndef script_directories():\n    # BASE is Plugins after installation; parent is the phBot folder.\n    parent = os.path.dirname(BASE)\n    return [os.path.join(BASE, \'scripts\'), os.path.join(parent, \'buon\'),\n            os.path.join(BASE, \'buon\'), os.path.join(parent, \'scripts\'), BASE, parent]\n\n\ndef resolve_script_text(text):\n    text = str(text or \'\').strip().strip(chr(34))\n    if not text:\n        raise ValueError(\'Nhap ten file TXT, vi du dichi__22222.txt\')\n    text = os.path.expandvars(os.path.expanduser(text))\n    if not text.casefold().endswith(\'.txt\'):\n        text += \'.txt\'\n    if os.path.basename(text) != text or os.path.isabs(text):\n        # Continue accepting previously saved full paths.\n        path = os.path.abspath(text)\n        if os.path.isfile(path):\n            return path\n        raise ValueError(\'Khong tim thay file: \' + path)\n    for directory in script_directories():\n        path = os.path.abspath(os.path.join(directory, text))\n        if os.path.isfile(path):\n            return path\n    raise ValueError(\'Khong tim thay \' + text + \'. Chep TXT vao Plugins/scripts hoac thu muc buon cua phBot\')\n\n\ndef script_display_name(text):\n    text = str(text or \'\')\n    return text[:-4] if text.casefold().endswith(\'.txt\') else text\n\n\ndef short_script_name(text):\n    # Shorten old saved paths only if the name resolves to exactly the same file.\n    text = str(text or \'\')\n    name = os.path.basename(text)\n    if name != text:\n        try:\n            if os.path.normcase(resolve_script_text(name)) == os.path.normcase(os.path.abspath(text)):\n                return script_display_name(name)\n        except (OSError, ValueError):\n            pass\n    return script_display_name(text)\n\n\ndef selected_script_path():\n    if \'route_slots\' in globals():\n        load_route_profiles()\n        if route_selected is None:\n            raise ValueError(\'Tich Script TXT hoac mot huong trong Tuyen buon truoc khi chay.\')\n        if route_selected != \'main\':\n            return resolve_route_script(route_selected)\n    return resolve_script_text(QtBind.text(gui, script_box))\n\n\ndef persist_trip():\n    path = trip_path()\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    temporary = None\n    try:\n        with tempfile.NamedTemporaryFile(mode=\'w\', encoding=\'utf-8\', dir=os.path.dirname(path), delete=False) as stream:\n            temporary = stream.name\n            json.dump(trip, stream, ensure_ascii=False, indent=2)\n        os.replace(temporary, path)\n        temporary = None\n    finally:\n        if temporary and os.path.exists(temporary):\n            os.remove(temporary)\n\n\ndef walk_point(line):\n    parts = line.split(\',\')\n    if len(parts) != 4 or parts[0].strip().casefold() != \'walk\':\n        return None\n    point = tuple(float(v.strip()) for v in parts[1:])\n    if not all(math.isfinite(v) for v in point):\n        raise ValueError(\'Toa do walk khong hop le\')\n    return point\n\n\ndef prepare_trip():\n    global trip, trip_lines, merchant_step\n    path = selected_script_path()\n    with open(path, encoding=\'utf-8-sig\') as stream:\n        lines = [line.strip() for line in stream.read().splitlines() if line.strip() and not line.lstrip().startswith((\'//\', \'#\'))]\n    if not lines:\n        raise ValueError(\'Script rong\')\n    validate_route_ferry_steps(lines)\n    # Preserve arbitrary native commands apart from synchronized ferry steps.\n    if not any(walk_point(line) is not None for line in lines):\n        raise ValueError(\'Script khong co walk,x,y,z de dinh vi. Can chon script co tuyen di\')\n    digest = hashlib.sha256((\'\\n\'.join(lines)).encode(\'utf-8\')).hexdigest()\n    if trip and trip.get(\'path\') == path and trip.get(\'digest\') == digest:\n        trip_lines = lines\n        return\n    try:\n        with open(trip_path(path), encoding=\'utf-8\') as stream:\n            saved = json.load(stream)\n    except FileNotFoundError:\n        # Migrate the single-route checkpoint written by version 1.4.\n        try:\n            with open(path_for(identity)[:-5] + \'.progress.json\', encoding=\'utf-8\') as stream:\n                saved = json.load(stream)\n        except FileNotFoundError:\n            saved = None\n    if saved and (saved.get(\'path\') != path or saved.get(\'digest\') != digest):\n        say(\'Noi dung script da doi; se dinh vi lai theo toa do hien tai.\')\n        saved = None\n    if saved:\n        cursor, uncertain = saved.get(\'cursor\'), saved.get(\'uncertain\')\n        if type(cursor) is not int or not 0 <= cursor <= len(lines):\n            raise ValueError(\'Moc tien do khong hop le\')\n        if uncertain is not None and (type(uncertain) is not int or not cursor < uncertain <= len(lines)):\n            raise ValueError(\'Moc giao dich khong hop le\')\n        trip = saved\n    else:\n        trip = {\'path\': path, \'digest\': digest, \'cursor\': 0, \'uncertain\': None}\n    trip_lines, merchant_step = lines, None\n    say(\'Script da chon: \' + path)\n    persist_trip()\n    say(\'Moc hien tai: buoc {}/{}. GO se tiep tuc tai day.\'.format(trip[\'cursor\'] + 1, len(lines)))\n\n\ndef locate_route(allow_far=False):\n    # An old completed cursor is not evidence that THIS trip is at its destination.\n    manual = (QtBind.text(gui, step_box).strip() or \'0\') != \'0\'\n    completed = trip[\'cursor\'] >= len(trip_lines) or trip.get(\'finish_stage\') == \'done\'\n    points = [walk_point(line) for line in trip_lines]\n    points = [point for point in points if point is not None]\n    if not manual and completed and trip.get(\'uncertain\') is None:\n        if not points:\n            raise ValueError(\'Khong co walk de kiem tra moc ket thuc\')\n        if reached(points[-1]) and config.get(\'finish_come\') and trip.get(\'finish_stage\') == \'done\':\n            pet = finish_transport()\n            if pet and transport_goods(pet) > 0:\n                trip.pop(\'finish_stage\', None)\n                persist_trip()\n                say(\'Moc hoan tat cu nhung thu van con hang tai dich; se ban hang, khong coi da xong.\')\n        if not reached(points[-1]):\n            saved = dict(trip)\n            trip[\'cursor\'] = 0\n            trip.pop(\'finish_stage\', None)\n            trip.pop(\'return_origin\', None)\n            try:\n                locate_route_impl(allow_far=allow_far)\n            except Exception:\n                trip.clear()\n                trip.update(saved)\n                raise\n            say(\'Moc het tuyen cu khong khop toa do hien tai; da dinh vi lai buoc {}. Khong ep ve dau tuyen.\'.format(trip[\'cursor\']+1))\n            return\n    locate_route_impl(allow_far=allow_far)\n\n\ndef route_wait_ms(line):\n    command, separator, argument = line.partition(\',\')\n    if command.strip().casefold() != \'wait\' or not separator:\n        return None\n    try:\n        duration = int(argument.strip())\n    except ValueError:\n        return None\n    return duration if duration >= 0 else None\n\n\ndef locate_route_impl(allow_far=False, switching_loaded=False):\n    # Coordinates alone do not identify a unique script step at crossings.\n    # Resuming after a manual detour may retrace walks before the saved cursor.\n    # Completed native actions on that stretch must never run a second time.\n    requested = QtBind.text(gui, step_box).strip() or \'0\'\n    try:\n        manual = int(requested)\n    except ValueError:\n        raise ValueError(\'Buoc phai la so: 0=tu dong, 1..N=chon thu cong\')\n    if manual < 0 or manual > len(trip_lines)+1:\n        raise ValueError(\'Buoc ngoai pham vi 1..\' + str(len(trip_lines)+1))\n    uncertain = trip.get(\'uncertain\')\n    cursor = trip[\'cursor\']\n    if (not manual and uncertain is not None and 0 <= cursor < uncertain <= len(trip_lines)\n            and all(route_wait_ms(line) is not None for line in trip_lines[cursor:uncertain])):\n        trip[\'uncertain\'] = None\n        persist_trip()\n        say(\'Moc cu chi co lenh wait; se tu cho lai va tiep tuc.\')\n        return\n    if trip.get(\'uncertain\') is not None:\n        if manual and manual-1 >= trip[\'uncertain\']:\n            trip[\'uncertain\'] = None\n            trip.pop(\'route_ferry_pending\', None)\n            trip.pop(\'turnaround_pending\', None)\n            globals()[\'route_crossing\'] = None\n            say(\'Da xac nhan bo qua khoi lenh cu bang Buoc thu cong; khong tu lap lenh.\')\n        else:\n            raise ValueError(\'Khoi lenh dang do. Kiem tra xong, nhap Buoc >= {} roi GO de tiep tuc\'.format(trip[\'uncertain\']+1))\n    if manual:\n        trip.pop(\'resume_walk_until\', None)\n        trip.pop(\'finish_stage\', None)\n        trip.pop(\'return_origin\', None)\n        trip[\'cursor\'] = manual - 1\n        readable_set_text(gui, step_box, \'0\')\n        persist_trip()\n        say(\'Da chon thu cong buoc \' + str(manual) + \'. Cac lenh tu buoc nay se duoc chay.\')\n        return\n    lower = trip[\'cursor\']\n    search_lower = 0 if lower>0 and not trip.get(\'finish_stage\') else lower\n    if switching_loaded:\n        buy = next((i for i, line in enumerate(trip_lines) if line.casefold().replace(\' \', \'\').startswith(\'oldtrade,buy\')), -1)\n        search_lower = buy+1\n    if not switching_loaded and lower >= len(trip_lines):\n        return\n    c = bot.get_character_data() or {}\n    try:\n        x, y = float(c[\'x\']), float(c[\'y\'])\n        if not math.isfinite(x) or not math.isfinite(y):\n            raise ValueError()\n    except (KeyError, TypeError, ValueError):\n        raise ValueError(\'Chua co toa do nhan vat hop le\')\n    points = [(i, walk_point(line)) for i, line in enumerate(trip_lines)]\n    points = [(i, point) for i, point in points if point is not None]\n    candidates = []\n    for i, point in points:\n        if i >= search_lower:\n            candidates.append((math.hypot(x-point[0], y-point[1]), i))\n    for (ia, a), (ib, b) in zip(points, points[1:]):\n        # Never draw an artificial segment across arbitrary script commands/teleports.\n        if ib != ia + 1 or ib < search_lower:\n            continue\n        dx, dy = b[0]-a[0], b[1]-a[1]\n        length2 = dx*dx + dy*dy\n        if length2 == 0:\n            continue\n        t = max(0.0, min(1.0, ((x-a[0])*dx+(y-a[1])*dy)/length2))\n        target = ia if t <= 0.000001 and ia >= search_lower else ib\n        candidates.append((math.hypot(x-(a[0]+t*dx), y-(a[1]+t*dy)), target))\n    if not candidates:\n        if switching_loaded:\n            raise ValueError(\'Khong co moc walk sau diem mua tren tuyen moi.\')\n        # Trailing native commands remain pending; coordinates cannot place them.\n        return\n    candidates.sort()\n    distance, target = candidates[0]\n    if switching_loaded and distance > 60:\n        raise ValueError(\'Tuyen moi cach {:.1f}m. Den gan tuyen trong 60m roi bam Tiep Tuc.\'.format(distance))\n    if distance > 60 and not allow_far:\n        say(\'Cach tuyen {:.0f}m: bo gioi han 60m, se di den moc duoc dinh vi roi tiep tuc. Dinh vi theo cho dang dung, giu cac giao dich da hoan tat.\'.format(distance))\n    ties = sorted({index for dist, index in candidates if dist <= distance + 0.75})\n    # Consecutive nearby waypoints are one local stretch; distant script indices imply a crossing.\n    if ties and max(ties)-min(ties) > 4:\n        say(\'Vi tri trung nhieu doan: buoc \' + \', \'.join(str(i+1) for i in ties))\n        raise ValueError(\'Tuyen giao nhau/lap. Nhap Buoc muon tiep tuc, roi GO\')\n    target = min(ties) if ties else target\n    if switching_loaded:\n        for key in (\'resume_walk_until\', \'finish_stage\', \'return_origin\', \'buy_wait_pending\'):\n            trip.pop(key, None)\n        trip[\'cursor\'] = target\n        persist_trip()\n        say(\'Doi tuyen khi dang cho hang: vao buoc {}/{} (cach {:.1f}m).\'.format(target+1, len(trip_lines), distance))\n        return\n    # At the beginning of the first route, retain setup commands preceding its first walk.\n    if lower == 0 and target == points[0][0] and distance <= 2:\n        target = 0\n    if target > lower:\n        # If still at the last completed waypoint, retain intervening commands.\n        previous = [(i, point) for i, point in points if i < lower]\n        if previous and math.hypot(x-previous[-1][1][0], y-previous[-1][1][1]) <= 2:\n            target = lower\n    if target > lower:\n        pending_ferry = next((i for i in range(lower, target) if ferry_step(trip_lines[i])), None)\n        if pending_ferry is not None:\n            before = [i for i, _ in points if lower <= i < pending_ferry]\n            source = walk_point(trip_lines[pending_ferry - 1]) if pending_ferry else None\n            landing = walk_point(trip_lines[pending_ferry + 1])\n            source_gap = math.hypot(x-source[0], y-source[1]) if source else 0\n            crossed = (source and landing and source_gap > 120 and distance <= 2\n                       and math.hypot(source[0]-landing[0], source[1]-landing[1]) > 120\n                       and all(i == pending_ferry or walk_point(trip_lines[i]) is not None\n                               for i in range(lower, target)))\n            if crossed:\n                own = own_names()\n                members = [member for member in (bot.get_party() or {}).values()\n                           if not own.intersection({norm(member.get(\'name\')), norm(member.get(\'job_name\'))})]\n                if not all(position_usable(member, c) for member in members):\n                    raise ValueError(\'Leader o chang sau pha {} gan buoc {}. Kiem tra ca doi da qua, roi nhap Buoc {} va GO.\'\n                                     .format(ferry_step(trip_lines[pending_ferry]), target+1, target+1))\n                trip.pop(\'resume_walk_until\', None)\n                say(\'Moc pha {} cu: da dinh vi sau pha, tiep tuc tu buoc {}.\'\n                    .format(ferry_step(trip_lines[pending_ferry]), target+1))\n            else:\n                target = before[-1] if before else pending_ferry\n                say(\'Giu moc pha tai buoc {} vi chua xac nhan duoc chang sau pha.\'.format(target+1))\n    if target<lower:\n        trip[\'resume_walk_until\']=max(lower,trip.get(\'resume_walk_until\',lower))\n        trip[\'cursor\']=target\n        say(\'Tiep tuc sau di chuyen thu cong: quay lai moc walk {} roi di den moc dang do {}. Chi di lai toa do, khong mua/ban/lap giao dich da qua.\'.format(target+1,trip[\'resume_walk_until\']+1))\n    else:\n        trip[\'cursor\']=max(lower,target)\n    persist_trip()\n    say(\'Dinh vi: x={:.1f} y={:.1f} -> buoc {}/{} (cach tuyen {:.1f}m).\'.format(\n        x, y, trip[\'cursor\']+1, len(trip_lines), distance))\n\n\ndef reached(point):\n    c = bot.get_character_data() or {}\n    try:\n        # 2m tolerance avoids skipping neighboring waypoints in this route.\n        return math.hypot(float(c[\'x\'])-point[0], float(c[\'y\'])-point[1]) <= 2.0\n    except (KeyError, TypeError, ValueError):\n        return False\n\n\n# Departure barrier is separate from the 10s road-distance wait.\nbuy_departure=None\nauto_buy_request=None\n\ndef begin_buy_departure():\n    global buy_departure\n    if buy_departure and buy_departure[\'owner\']==identity:\n        return\n    named=names((config or {}).get(\'follow\',\'\'))\n    # Use the saved CSV field (also works when this build uses a different config key).\n    named|=names(QtBind.text(gui,follow_box))\n    expected={convoy_name(m.get(\'name\') or m.get(\'job_name\')) for m in (bot.get_party() or {}).values()\n              if {norm(m.get(\'name\')),norm(m.get(\'job_name\'))}&named and not {norm(m.get(\'name\')),norm(m.get(\'job_name\'))}&own_names()}\n    buy_departure={\'owner\':identity,\'token\':uuid.uuid4().hex[:16],\'expected\':expected,\n                   \'roles\':{},\'ready\':{},\'next\':float(\'-inf\'),\'started\':time.monotonic(),\n                   \'goods\':None,\'stable\':time.monotonic()}\n\n\ndef handle_buy_departure_chat(player,msg):\n    global auto_buy_request\n    parts=party_command_parts(msg,\'!CRB\')\n    if not parts or parts[0]!=\'!CRB\':\n        return False\n    if len(parts)!=4 or not config or not party_member(player) or norm(player) in own_names():\n        return True\n    token,action=parts[2:]\n    if len(token)!=16 or any(c not in \'0123456789abcdef\' for c in token):\n        return True\n    if action in (\'QUERY\',\'BUY_QUERY\'):\n        if not trusted_leader(player):\n            return True\n        if config[\'hunter\']:\n            answer=\'HUNTER\'\n        elif config.get(\'follower\'):\n            target=current_follow_target()\n            if target and convoy_name(target)!=convoy_name(player):\n                return True\n            pet=alive_transport()\n            ready=bool(pet and pet.get(\'mounted\') and transport_goods(pet)>=int(config.get(\'buy_goods\',280))\n                       and active and follow_mode==\'trace\' and not follower_state and not follow_blocked)\n            request=(identity,convoy_name(player),token)\n            busy_buy = follower_state and (follower_state[\'phase\'] != \'approach\' or follower_state.get(\'native_sent\'))\n            if (action==\'BUY_QUERY\' and not ready and request!=auto_buy_request\n                    and not follow_blocked and not trade_fault and not (busy_buy or finish_context or recovery\n                    or return_request or route_crossing or local_sale or convoy_controller)):\n                try:\n                    start_party_trade(\'MUA\',player)\n                    auto_buy_request=request\n                except (ValueError,OSError,KeyError,TypeError) as error:\n                    say_throttled(\'auto_departure_buy\',\'Buon phu chua the tu mua: \'+str(error),5)\n            answer=\'READY\' if ready else \'WAIT\'\n        else:\n            answer=\'OTHER\'\n        control_party(\'!CRB {} {}\'.format(token,answer))\n        return True\n    context=buy_departure\n    if not context or context[\'owner\']!=identity or token!=context[\'token\'] or action not in (\'HUNTER\',\'OTHER\',\'READY\',\'WAIT\'):\n        return True\n    key=convoy_name(player)\n    context[\'roles\'][key]=\'follower\' if action in (\'READY\',\'WAIT\') else action\n    # Reuse authenticated, matching-token departure role replies during escort checks.\n    # Otherwise clearing buy_departure discards the only confirmed role information.\n    if action == \'HUNTER\':\n        trade_followers.pop(key, None)\n        if key not in party_hunters:\n            say(\'Da xac nhan Bao tieu \'+player+\' qua phan hoi Party.\')\n        party_hunters.add(key)\n    elif action in (\'READY\', \'WAIT\'):\n        party_hunters.discard(key)\n        trade_followers[key] = {\'name\': player, \'seen\': time.monotonic()}\n    else:  # OTHER: this character is neither a guard nor a follower trader.\n        party_hunters.discard(key)\n        trade_followers.pop(key, None)\n    if action in (\'READY\',\'WAIT\'):\n        context[\'expected\'].add(key)\n    if action==\'READY\':\n        context[\'ready\'][key]=time.monotonic()\n    else:\n        context[\'ready\'].pop(key,None)\n    return True\n\n\ndef leader_buy_departure_tick():\n    global buy_departure,merchant_step\n    if not trip or not trip.get(\'buy_wait_pending\'):\n        return True\n    begin_buy_departure()\n    context=buy_departure\n    now=time.monotonic()\n    if context.get(\'turn_batch\') and now-context[\'started\'] >= 180:\n        stop_owned()\n        say(\'Het thoi gian cho mua chieu ve. Kiem tra hang ca doi truoc khi tiep tuc.\')\n        return False\n    if now>=context[\'next\']:\n        context[\'next\']=now+5\n        if context.get(\'turn_batch\'):\n            control_party(\'!CR2 {} BUY_KEEP\'.format(context[\'turn_batch\']))\n        action=\'QUERY\' if context.get(\'turn_batch\') else \'BUY_QUERY\'\n        control_party(\'!CRB {} {}\'.format(context[\'token\'],action))\n    pet=alive_transport()\n    goods=transport_goods(pet) if pet else 0\n    if goods!=context[\'goods\']:\n        context.update(goods=goods,stable=now)\n    waiting=[]\n    for key in context[\'expected\']:\n        role=context[\'roles\'].get(key)\n        if role in (\'HUNTER\',\'OTHER\') or (role is None and key in party_hunters):\n            continue\n        member=next((m for m in (bot.get_party() or {}).values() if convoy_name(m.get(\'name\') or m.get(\'job_name\'))==key),None)\n        if not member or role!=\'follower\' or now-context[\'ready\'].get(key,float(\'-inf\'))>12:\n            waiting.append(key)\n    # Native buy must have produced stable goods; no route walk is in this block.\n    own_ready=bool(pet and pet.get(\'mounted\') and goods>0 and now-context[\'stable\']>=3)\n    elapsed=now-context[\'started\']\n    # Allow the native spawn command time to finish, then pause once.\n    # Missing pets alone cannot distinguish depleted scrolls from a failed summon.\n    if pet:\n        context.pop(\'missing_pet_since\',None)\n    else:\n        context.setdefault(\'missing_pet_since\',now)\n        if now-context[\'missing_pet_since\']>=45:\n            set_loop(False)\n            stop_owned()\n            set_state(\'Tam dung - het thu/khong goi duoc thu\')\n            say(\'Khong co thu van tai sau 45s (co the da het thu). Da tam dung. Bo sung/kiem tra thu roi bam GO.\')\n            return False\n    if not own_ready and elapsed>=180:\n        set_loop(False)\n        stop_owned()\n        set_state(\'Tam dung - chua mua/len thu duoc\')\n        say(\'Qua 180s chua mua/len thu duoc. Da tam dung; kiem tra thu va hang roi bam GO.\')\n        return False\n    # Wait for follower readiness for 20s, then use the existing bypass/rejoin path.\n    # The leader still must have a mounted transport with confirmed stable goods.\n    if elapsed<3 or (waiting and elapsed<30) or not own_ready:\n        detail=\', \'.join(sorted(waiting)) if waiting else (\'Leader dang mua/len thu\' if not own_ready else \'xac nhan vai tro\')\n        if not own_ready and waiting:\n            detail=\'Leader dang mua/len thu; \'+detail\n        set_state(\'Cho mua du/len thu: \'+detail)\n        if own_ready:\n            say_throttled(\'buy_departure_wait\',\'Leader cho tai diem mua: \'+detail+\'.\',30)\n        return False\n    bot.stop_script()\n    trip[\'cursor\']=trip.pop(\'buy_wait_pending\')[\'after\']\n    trip[\'uncertain\']=None\n    merchant_step=None\n    buy_departure=None\n    persist_trip()\n    if waiting:\n        follower_bypass.update(waiting)\n        origin=snapshot_position(bot.get_character_data() or {})\n        entries=follower_monitor.setdefault(\'entries\',{})\n        for key in waiting:\n            entries[key]={\'outside\':True,\'outside_since\':None,\'inside_since\':None,\n                          \'departure_origin\':origin}\n        say(\'Da cho 30s; Leader va Bao tieu tiep tuc. Bo qua Buon phu chua san sang: \'+\', \'.join(sorted(waiting))+\'.\')\n    else:\n        say(\'Buon phu da mua du, len thu va Trace san sang; Leader bat dau di.\')\n    return True\n\n\ndef merchant_tick(advance=True):\n    global merchant_step, active\n    if not active or standalone_follow or follower_state or not config or config[\'hunter\'] or config.get(\'follower\') or not trip:\n        return\n    if finish_context:\n        if advance:\n            finish_tick()\n        return\n    if advance and not trip.get(\'buy_wait_pending\') and merchant_step is None and trip[\'cursor\'] < len(trip_lines):\n        key = ferry_step(trip_lines[trip[\'cursor\']])\n        if key and not trip.get(\'resume_walk_until\'):\n            route_ferry_tick(key)\n            return\n    if advance and trip.get(\'turnaround_pending\'):\n        raise ValueError(\'Dang do ban doi chieu. Kiem tra hang va chon lai buoc thu cong.\')\n    if advance and not finish_context and not leader_buy_departure_tick():\n        return\n    if advance and not finish_context:\n        probe_party_followers()\n        if not escort_gate() or not follower_distance_gate():\n            return\n    if merchant_step:\n        if \'wait_until\' in merchant_step:\n            if time.monotonic() < merchant_step[\'wait_until\']:\n                return\n        else:\n            point = merchant_step[\'point\']\n            if point is None:\n                return\n            if not reached(point):\n                if merchant_step.get(\'direct\') and time.monotonic()-merchant_step.get(\'last_move\', 0) >= 3:\n                    bot.move_to(*point)\n                    merchant_step[\'last_move\'] = time.monotonic()\n                return\n        trip[\'cursor\'] = merchant_step[\'after\']\n        trip[\'uncertain\'] = None\n        merchant_step = None\n        persist_trip()\n    if not advance:\n        return\n    while trip[\'cursor\'] < len(trip_lines):\n        index = trip[\'cursor\']\n        retrace_until=trip.get(\'resume_walk_until\')\n        if retrace_until is not None and index>=retrace_until:\n            trip.pop(\'resume_walk_until\',None)\n            retrace_until=None\n            persist_trip()\n        point = walk_point(trip_lines[index])\n        if retrace_until is not None and index<retrace_until and point is None:\n            # Retrace movement only: buy/sell/teleport/terminate actions here already ran.\n            trip[\'cursor\']+=1\n            persist_trip()\n            continue\n        if point is not None:\n            if reached(point):\n                trip[\'cursor\'] += 1\n                persist_trip()\n                continue\n            # Native move_to supports transports and avoids ending a fresh script at every waypoint.\n            bot.move_to(*point)\n            merchant_step = {\'point\': point, \'after\': index + 1, \'direct\': True, \'last_move\': time.monotonic()}\n            set_state(\'Buon: buoc {}/{} -> {}, {}\'.format(index + 1, len(trip_lines), point[0], point[1]))\n            return\n        key = ferry_step(trip_lines[index])\n        if key:\n            route_ferry_tick(key)\n            return\n        if trip_lines[index].casefold().startswith(\'turnaround,\'):\n            begin_turnaround(trip_lines[index].split(\',\', 1)[1].strip())\n            return\n        wait_ms = route_wait_ms(trip_lines[index])\n        if wait_ms is not None:\n            merchant_step = {\'point\': None, \'after\': index + 1,\n                             \'wait_until\': time.monotonic() + wait_ms / 1000.0}\n            set_state(\'Dang cho tai buoc {}\'.format(index + 1))\n            return\n        # Submit native oldtrade block with the next walk as an observable end marker.\n        end = index\n        while end < len(trip_lines) and walk_point(trip_lines[end]) is None and not ferry_step(trip_lines[end]) and not trip_lines[end].casefold().startswith(\'turnaround,\'):\n            end += 1\n        tail = [line.casefold().replace(\' \', \'\') for line in trip_lines[index:end]]\n        if config.get(\'finish_come\') and end == len(trip_lines) and tail and tail[0] == \'oldtrade,sell\' and all(line in (\'oldtrade,sell\', \'terminate,all\', \'terminate,transport\', \'killhorse\', \'stop\') for line in tail):\n            begin_finish()\n            return\n        # Never embed a departing walk after native buy: it would leave before peers finish.\n        has_buy=any(line.casefold().replace(\' \',\'\').startswith(\'oldtrade,buy\') for line in trip_lines[index:end])\n        if has_buy and bot.get_party() and own_names() & names(config[\'leaders\']):\n            begin_buy_departure()\n            trip[\'buy_wait_pending\']={\'after\':end}\n            trip[\'uncertain\']=end\n            persist_trip()\n            if bot.start_script(\'\\n\'.join(trip_lines[index:end])+\'\\n\') is False:\n                raise ValueError(\'phBot tu choi khoi mua; Leader dung cho, khong tu chay tiep\')\n            merchant_step={\'point\':None,\'after\':end,\'buy_wait\':True}\n            set_state(\'Dang mua - cho buon phu san sang truoc khi di\')\n            return\n        point = walk_point(trip_lines[end]) if end < len(trip_lines) else None\n        after = end + 1 if point is not None else end\n        trip[\'uncertain\'] = end  # Save BEFORE dispatch: never replay on crash/STOP.\n        persist_trip()\n        # If already at the marker, position cannot prove the action block completed.\n        marker = None if point is not None and reached(point) else point\n        merchant_step = {\'point\': marker, \'after\': after,\n                         \'terminates_transport\': any(\n                             line in (\'terminate,all\', \'terminate,transport\', \'killhorse\') for line in tail)}\n        result = bot.start_script(\'\\n\'.join(trip_lines[index:after]) + \'\\n\')\n        if result is False:\n            merchant_step = None\n            raise ValueError(\'phBot tu choi khoi mua/ban; kiem tra truoc khi xac nhan\')\n        if not active:\n            return\n        set_state(\'Dang chay khoi lenh; STOP giu moc, khong tu lap lenh\')\n        if point is None or marker is None:\n            say(\'Khoi lenh khong co moc xac nhan. Kiem tra xong, nhap Buoc {} roi GO.\'.format(end+1))\n        return\n    if config.get(\'finish_come\') and trip.get(\'finish_stage\') != \'done\':\n        begin_finish()\n        return\n    active = False\n    set_state(\'Da het tuyen - chon Buoc 1 + GO neu muon chay lai\')\n\n\ndef confirm_actions():\n    global merchant_step, active\n    load_identity()\n    if not config or config[\'hunter\']:\n        say(\'Nut nay chi danh cho acc buon.\')\n        return\n    try:\n        if not trip:\n            prepare_trip()\n        if trip.get(\'uncertain\') is None:\n            say(\'Khong co khoi lenh dang cho xac nhan.\')\n            return\n        if active:\n            bot.stop_script()\n        active, merchant_step = False, None\n        # Skip only the action block, retaining its following walk as the next step.\n        trip[\'cursor\'] = trip[\'uncertain\']\n        trip[\'uncertain\'] = None\n        persist_trip()\n        set_state(\'Da xac nhan giao dich - GO de tiep tuc\')\n        say(\'Da ghi nhan khoi lenh da xong theo xac nhan cua ban. Bam GO de tiep tuc.\')\n    except Exception as error:\n        say(\'Xac nhan that bai: \' + str(error))\n\n\ndef reset_trip():\n    global trip, trip_lines, merchant_step, escort_state\n    load_identity()\n    if active or recovery or loop_pending or loop_return:\n        say(\'Tat lap / Dung acc nay truoc khi chon Chuyen moi.\')\n        return\n    if not config or config[\'hunter\']:\n        say(\'Chuyen moi chi danh cho acc buon.\')\n        return\n    path = trip_path(selected_script_path())\n    if os.path.exists(path):\n        os.remove(path)\n    trip, trip_lines, merchant_step = None, [], None\n    globals()[\'route_crossing\'] = None\n    escort_state = None\n    escort_monitor.clear()\n    readable_set_text(gui, step_box, \'1\')\n    set_state(\'Chuyen moi - GO se bat dau buoc 1\')\n    say(\'Da bo moc cu cua script dang chon; buoc 1 da duoc chon cho GO tiep theo.\')\n\n\ndef run_go(manual_recovery=False):\n    global active, last_go, follow_mode, last_follow_move, follow_missing_since, route_switch_requested\n    if return_request:\n        say(\'Dang cho dung bua ve thanh; STOP de huy truoc khi GO.\')\n        return\n    if recovery:\n        say(\'Dang xu ly thu chet. STOP de huy; khong GO chen vao.\')\n        return\n    if active:\n        say_throttled(\'go_busy\',\'Dang chay; GO khong khoi dong lai tuyen. Bam Dung de tam dung.\',15)\n        return\n    if time.monotonic() - last_go < 15 and (not config or config[\'hunter\']):\n        say(\'Cho 15 giay giua hai lenh di buon.\')\n        return\n    # A newly checked Hunter box must block merchant scripts even before Save.\n    if bool(QtBind.isChecked(gui, hunter_check)) != config[\'hunter\']:\n        raise ValueError(\'Vai tro tren giao dien chua luu. Bam Luu cau hinh hoac Bat di theo\')\n    c = bot.get_character_data() or {}\n    if not c or c.get(\'dead\'):\n        raise ValueError(\'Nhan vat offline hoac da chet\')\n    if bool(QtBind.isChecked(gui, follower_check)) != bool(config.get(\'follower\')):\n        raise ValueError(\'Luu vai tro Buon phu truoc khi GO\')\n    if not config[\'hunter\'] and hasattr(bot, \'stop_bot\'):\n        bot.stop_bot()\n    if config.get(\'follower\') and not follower_ready():\n        return\n    if config[\'hunter\'] or config.get(\'follower\'):\n        if config.get(\'follower\') and hasattr(bot, \'stop_bot\'):\n            bot.stop_bot()\n        target = current_follow_target()\n        if not target or norm(target) in own_names() or not party_member(target):\n            raise ValueError(\'Nhap ten acc buon can bam theo; acc do phai o trong Party\')\n        start_follow_target(target)\n    else:\n        prepare_trip()\n        if trip.get(\'recovery_pending\'):\n            manual = (QtBind.text(gui, step_box).strip() or \'0\') != \'0\'\n            if manual:\n                complete_recovery(manual=True)\n                return\n            context = trip[\'recovery_pending\']\n            pet = alive_transport()\n            if context.get(\'goods\', 0) > 0 and pet and transport_goods(pet) >= context[\'goods\']:\n                complete_recovery()\n                return\n            raise ValueError(\'Hang chua thu hoi du. Kiem tra hang, nhap Buoc can tiep tuc roi GO de xac nhan thu cong\')\n        if interrupted_turnaround():\n            resume_turnaround()\n            route_switch_requested = False\n            return\n        pet = finish_transport() if route_switch_requested else None\n        switching_loaded = bool(pet and transport_goods(pet) > 0)\n        if switching_loaded:\n            if not pet.get(\'mounted\'):\n                raise ValueError(\'Len thu dang cho hang truoc khi doi tuyen.\')\n            locate_route_impl(switching_loaded=True)\n            route_switch_requested = False\n        if config.get(\'finish_come\') and trip.get(\'uncertain\') == len(trip_lines):\n            tail = [line.casefold().replace(\' \', \'\') for line in trip_lines[trip[\'cursor\']:]]\n            if tail and tail[0] == \'oldtrade,sell\' and all(line in (\'oldtrade,sell\', \'terminate,all\', \'terminate,transport\', \'killhorse\', \'stop\') for line in tail):\n                trip[\'uncertain\'] = None\n                trip[\'finish_stage\'] = \'sell\'\n                persist_trip()\n        if trip.get(\'finish_stage\') in (\'return_pending\', \'return_wait\'):\n            say(\'Da ban/huy/VE; thu lai Return Scroll theo lenh GO, khong chay lai tuyen.\')\n            execute(\'RETURN\')\n            return\n        if config.get(\'finish_come\') and trip.get(\'finish_stage\') not in (None, \'done\'):\n            active = True\n            begin_finish()\n            return\n        if trip.get(\'route_ferry_pending\') and trip[\'cursor\'] < len(trip_lines):\n            key = ferry_step(trip_lines[trip[\'cursor\']])\n            if key:\n                active = True\n                if route_crossing_matches():\n                    route_crossing[\'deadline\'] = time.monotonic()+45\n                else:\n                    route_ferry_tick(key)\n                return\n        if not switching_loaded:\n            locate_route(allow_far=manual_recovery)\n        route_switch_requested = False\n        if trip.get(\'uncertain\') is not None:\n            raise ValueError(\'Khoi lenh dang do; dung Buoc thu cong sau khi kiem tra\')\n        if trip[\'cursor\'] >= len(trip_lines) and config.get(\'finish_come\') and trip.get(\'finish_stage\') != \'done\':\n            active = True\n            begin_finish()\n            return\n        if trip[\'cursor\'] >= len(trip_lines):\n            say(\'Da o diem cuoi va moc da hoan tat ({}/{}). Neu chon script khac, kiem tra dung file/buoc.\'.format(trip[\'cursor\'], len(trip_lines)))\n            return\n        if switching_loaded and bot.get_party() and own_names() & names(config[\'leaders\']):\n            trip[\'buy_wait_pending\'] = {\'after\': trip[\'cursor\']}\n            begin_buy_departure()\n            persist_trip()\n            say(\'Doi huong: Leader da co hang. Goi Buon phu mua truoc khi di.\')\n        active = True\n        try:\n            remember_transports()\n            merchant_tick()\n        except Exception:\n            active = False\n            raise\n    last_go = time.monotonic()\n\n\ndef new_start_changed(checked):\n    if checked:\n        send_team(\'NEWGO\')\n\n\n\ndef start_new_trip_now():\n    global loop_pending, loop_return, last_go\n    if not config:\n        raise ValueError(\'Luu cau hinh truoc khi Bat dau moi\')\n    if bool(QtBind.isChecked(gui, hunter_check)) != config[\'hunter\']:\n        raise ValueError(\'Luu vai tro da chon truoc khi Bat dau moi\')\n    if bool(QtBind.isChecked(gui, follower_check)) != bool(config.get(\'follower\')):\n        raise ValueError(\'Luu vai tro Buon phu truoc khi Bat dau moi\')\n    if not config[\'hunter\']:\n        pet = alive_transport()\n        if pet and (not isinstance(pet.get(\'items\'), list) or transport_goods(pet) > 0):\n            raise ValueError(\'Thu van con hang/chua doc duoc tui. Dung GO de tiep tuc, khong khoi dong lai mua hang\')\n        if config.get(\'follower\'):\n            target = current_follow_target()\n            if not target or norm(target) in own_names() or not party_member(target):\n                raise ValueError(\'Can Leader da luu trong cung Party de tu mua hang\')\n            try:\n                npc = party_trade_npc(target)\n            except (ValueError, KeyError, TypeError) as error:\n                load_route_profiles()\n                if route_selected is None:\n                    say(\'Buon phu NEWGO: \'+str(error)+\' Cho lenh mua khi Leader den NPC.\')\n                    return\n            else:\n                start_party_trade(\'MUA\', target, npc=npc)\n                loop_pending, loop_return = None, None\n                return\n        path = selected_script_path()\n        with open(path, encoding=\'utf-8-sig\') as stream:\n            lines = [line.strip() for line in stream if line.strip() and not line.lstrip().startswith((\'#\', \'//\'))]\n        if not any(walk_point(line) is not None for line in lines):\n            raise ValueError(\'Script can co toa do walk de bat dau chuyen moi\')\n    stop_owned()\n    loop_pending, loop_return = None, None\n    if config[\'hunter\']:\n        last_go = float(\'-inf\')\n        run_go()\n        return\n    reset_trip()\n    say(\'Bat dau moi: tu buoc 1, di toi diem mua hang. Khong can nhap Buoc hay bam GO them.\')\n    run_go()\n\n\ndef execute(action):\n    global last_return, loop_return\n    try:\n        if action == \'NEWGO\':\n            enable_following()\n            start_new_trip_now()\n        elif action == \'LOOPON\':\n            if not loop_controls_allowed():\n                say(\'Chua cho phep lap chuyen; bo qua lenh bat lap.\')\n                return\n            if not config[\'hunter\'] and not config.get(\'follower\') and not config.get(\'finish_come\') and not selected_has_turnaround():\n                raise ValueError(\'Tich Ban ca doi va luu cau hinh truoc khi bat lap\')\n            set_loop(True)\n            say(\'Da bat lap. Neu dang dung, bam Bat dau moi hoac Tiep tuc de chay.\')\n        elif action == \'LOOPOFF\':\n            set_loop(False)\n            say(\'Da tat lap: chuyen hien tai van tiep tuc. Tuyen khu hoi ban xong se dung mua.\')\n        elif action in (\'FOLLOW\', \'UNFOLLOW\'):\n            # Role-specific command: merchants never run a script for FOLLOW.\n            if not config or not (config[\'hunter\'] or config.get(\'follower\')):\n                return\n            if action == \'UNFOLLOW\':\n                stop_owned()\n            else:\n                enable_following()\n                run_go()\n        elif action == \'STOP\':\n            set_loop(False)\n            stop_owned()\n        elif action == \'GUARDHOME\':\n            if config and config[\'hunter\']:\n                set_loop(False)\n                stop_owned()\n                execute(\'RETURN\')\n        elif action == \'GO\':\n            enable_following()\n            if active and not recovery:\n                run_go()\n                return\n            if config and not config[\'hunter\']:\n                prepare_trip()\n                if recovery or trip.get(\'recovery_pending\'):\n                    complete_recovery(manual=True)\n                    return\n            run_go()\n        elif action == \'RETURN\':\n            queue_return()\n    except Exception as error:\n        say(\'Lenh \' + action + \' that bai: \' + str(error))\n\n\ndef local_go():\n    load_identity()\n    if config:\n        execute(\'GO\')\n    else:\n        say(\'Luu cau hinh truoc.\')\n\n\ndef enable_following():\n    global follow_blocked, follow_stop_guard\n    clear_trade_fault()\n    follow_blocked,follow_stop_guard=False,None\n\n\ndef cancel_native_follow(hold=None, stop_botting=True):\n    # Cancel native Trace even if this plugin has lost its local follow flag.\n    for name in (\'stop_trace\', \'stop_trade\'):\n        fn=getattr(bot,name,None)\n        if callable(fn):\n            fn()\n    if stop_botting and callable(getattr(bot,\'stop_bot\',None)):\n        bot.stop_bot()\n    # xControl keeps its own coordinate-follow flag outside native Trace.\n    for module in list(sys.modules.values()):\n        values=getattr(module,\'__dict__\',{}) if module is not None else {}\n        if values.get(\'pName\')==\'xControl\' and callable(values.get(\'stop_follow\')):\n            values[\'stop_follow\']()\n    if hold:\n        character=bot.get_character_data() or {}\n        if character.get(\'region\')==hold[\'region\']:\n            bot.move_to(hold[\'x\'],hold[\'y\'],hold[\'z\'])\n\n\ndef send_stop_reply(token,action,via):\n    message=\'!CRSTOP \'+token+\' \'+action\n    return control_party(message)\n\n\ndef stop_following(force=True, token=None):\n    global follow_request, follow_blocked, follow_stop_guard, follow_mode\n    load_identity()\n    owned_follow=bool(follow_mode or follow_request or (active and config and config[\'hunter\']))\n    own_other_work=bool((active or recovery) and not owned_follow)\n    follow_blocked=True\n    follow_request=None\n    if owned_follow:\n        set_loop(False)\n        stop_owned()\n    elif config and (config[\'hunter\'] or config.get(\'follower\')):\n        set_loop(False)\n    anchor=snapshot_position(bot.get_character_data() or {})\n    cancel_native_follow(hold=None if own_other_work else anchor,stop_botting=not own_other_work)\n    if own_other_work:\n        # Finish a buy/sell/recovery already underway, but suppress its automatic follow afterwards.\n        say(\'Da tat theo; acc dang co tap lenh rieng. Khong tu bam Leader sau khi xong.\')\n        if token:\n            send_stop_reply(token,\'OWN_SCRIPT\',control_incoming)\n        return\n    follow_mode=None\n    follow_stop_guard={\'anchor\':anchor,\'until\':time.monotonic()+3,\'next\':time.monotonic()+0.5,\'token\':token,\'last_position\':anchor,\'stable_since\':None,\'via\':control_incoming}\n    set_state(\'Da tat theo - dang xac nhan dung di chuyen\')\n    say(\'Da huy Trace, theo toa do va lenh theo dang cho; xac nhan dung trong 3s.\')\n\n\ndef follow_stop_tick():\n    global follow_stop_guard\n    now=time.monotonic()\n    for token,record in list(follow_stop_sent.items()):\n        if now>=record[\'deadline\']:\n            detail=\'Da nhan lenh nhung chua xac nhan dung: \' if record.get(\'received\') else \'Chua nhan phan hoi tu: \'\n            say(detail+record[\'target\']+\'. Kiem tra log Nhan TAT THEO / Tu choi TAT THEO tren acc nay.\')\n            del follow_stop_sent[token]\n    context=follow_stop_guard\n    if not context or now<context[\'next\']:\n        return\n    anchor=context[\'anchor\']\n    current=snapshot_position(bot.get_character_data() or {})\n    previous=context.get(\'last_position\')\n    still=bool(current and previous and current[\'region\']==previous[\'region\'] and math.hypot(current[\'x\']-previous[\'x\'],current[\'y\']-previous[\'y\'])<=0.5)\n    if not still:\n        context[\'stable_since\']=None\n    elif context[\'stable_since\'] is None:\n        context[\'stable_since\']=now\n    context[\'last_position\']=current\n    if now>=context[\'until\']:\n        stationary=bool(current and anchor and current[\'region\']==anchor[\'region\'] and math.hypot(current[\'x\']-anchor[\'x\'],current[\'y\']-anchor[\'y\'])<=2 and context[\'stable_since\'] is not None and now-context[\'stable_since\']>=1)\n        action=\'STOPPED\' if stationary else \'MOVING\'\n        if context.get(\'token\'):\n            send_stop_reply(context[\'token\'],action,context.get(\'via\',\'party\'))\n        set_state(\'Da dung theo doi\' if stationary else \'Da tat theo; van con di chuyen, kiem tra plugin khac\')\n        if not stationary:\n            say(\'Da tat theo trong CaravanRoutes nhung vi tri van thay doi; co the con plugin/ban CaravanRoutes khac dang dieu khien.\')\n        follow_stop_guard=None\n        return\n    context[\'next\']=now+0.5\n    cancel_native_follow(hold=anchor)\n\n\ndef handle_follow_stop_ack(player,msg):\n    parts=msg.split()\n    if not parts or parts[0]!=\'!CRSTOP\':\n        return False\n    if len(parts)!=3 or not party_member(player):\n        return True\n    token,action=parts[1:]\n    record=follow_stop_sent.get(token)\n    if not record or convoy_name(player)!=convoy_name(record[\'target\']):\n        return True\n    if action==\'RECEIVED\':\n        record[\'received\']=True\n        record[\'deadline\']=time.monotonic()+8\n        say(player+\': da nhan lenh TAT THEO, dang kiem tra dung di chuyen.\')\n        return True\n    if action not in (\'STOPPED\',\'MOVING\',\'OWN_SCRIPT\'):\n        return True\n    del follow_stop_sent[token]\n    detail={\'STOPPED\':\'da xac nhan dung tai cho\',\'MOVING\':\'da tat theo nhung van con di chuyen; kiem tra plugin khac\',\'OWN_SCRIPT\':\'da tat theo; dang chay tap lenh rieng, chua dung tai cho\'}[action]\n    say(player+\': \'+detail)\n    return True\n\n\ndef pause_trace_for_rejoin(reason, delay=2, hold=False):\n    global active, follow_mode, follow_request\n    intent=follow_intent\n    if not intent or intent[\'owner\']!=identity or follow_blocked:\n        return\n    bot.stop_trace()\n    if hold:\n        stop_at_current_position()\n    restore_escort_combat()\n    active=False\n    follow_mode=None\n    follower_mount_guard.clear()\n    follow_request={\'owner\':identity,\'target\':intent[\'target\'],\'next\':time.monotonic()+delay,\n                    \'deadline\':float(\'inf\'),\'independent\':True,\'persistent\':True,\n                    \'needs_transport\':intent.get(\'needs_transport\',False),\'mount_tries\':0}\n    set_state(\'Giu lenh theo - cho Trace lai: \'+intent[\'target\'])\n    say_throttled(\'trace_rejoin\',\'Giu lenh theo \'+intent[\'target\']+\': \'+reason+\'. Se tu Trace lai khi gap nhau; khong can Leader bat lai.\',15)\n\n\ndef nearby_outdoor_position(current, target, limit):\n    regions = (current.get(\'region\'), target.get(\'region\'))\n    if not all(isinstance(region, int) and 0 <= region < 0x8000 for region in regions):\n        return False\n    try:\n        return math.hypot(float(current[\'x\'])-float(target[\'x\']),\n                          float(current[\'y\'])-float(target[\'y\'])) <= limit\n    except (KeyError, TypeError, ValueError):\n        return False\n\n\ndef trace_region_reachable(character, member):\n    region = member.get(\'region\')\n    if region is None or region == character.get(\'region\'):\n        return True\n    uid = member.get(\'player_id\')\n    if not uid:\n        return False\n    if nearby_outdoor_position(character, member, 60):\n        return True\n    # A locally visible UID and nearby coordinates outrank stale Party region data.\n    visible_players = getattr(bot, \'get_players\', lambda: {})() or {}\n    visible = visible_players.get(uid) or visible_players.get(str(uid))\n    return bool(visible and position_usable(\n        dict(visible, player_id=uid, region=character.get(\'region\')), character))\n\n\ndef trace_follow_watchdog():\n    intent=follow_intent\n    if not intent or follow_blocked or not active or follow_mode!=\'trace\':\n        return\n    now=time.monotonic()\n    character=bot.get_character_data() or {}\n    member=resolve_follow_target(intent[\'target\'])\n    reason=None\n    if not character or character.get(\'dead\'):\n        reason=\'cho nhan vat san sang\'\n    elif not member:\n        reason=\'cho du lieu Party/Leader\'\n    elif not trace_region_reachable(character, member):\n        reason=\'Leader da sang khu khac\'\n    elif intent.get(\'last_uid\') and not member.get(\'player_id\'):\n        reason=\'Leader tam thoi ra khoi tam nhin\'\n    if reason:\n        if intent.get(\'missing_since\') is None:\n            intent[\'missing_since\']=now\n        if now-intent[\'missing_since\']>=3:\n            pause_trace_for_rejoin(reason,hold=bool(character and not character.get(\'dead\')))\n        return\n    intent[\'missing_since\']=None\n    uid=member.get(\'player_id\')\n    if uid and intent.get(\'last_uid\') and uid!=intent[\'last_uid\']:\n        intent[\'last_uid\']=uid\n        pause_trace_for_rejoin(\'UID Leader thay doi sau dich chuyen\')\n        return\n    if uid:\n        intent[\'last_uid\']=uid\n\ndef start_follow_target(target):\n    global active, follow_mode, follow_request, follow_missing_since, follow_intent\n    if defer_follower_follow(target) or manual_npc_guard():\n        return False\n    if follow_blocked:\n        active=False\n        follow_mode=None\n        set_state(\'Da tat theo theo lenh Leader; cho Bat theo moi\')\n        return False\n    character=bot.get_character_data() or {}\n    if not character or character.get(\'dead\'):\n        raise ValueError(\'Nhan vat offline hoac da chet\')\n    member=resolve_follow_target(target)\n    if not member or norm(target) in own_names():\n        raise ValueError(\'Nhap ten Leader khac acc nay va dang o trong Party\')\n    if follow_intent is None or follow_intent[\'target\']!=target:\n        pet=alive_transport() if config and config.get(\'follower\') else None\n        follow_intent={\'owner\':identity,\'target\':target,\'last_uid\':member.get(\'player_id\'),\n                       \'needs_transport\':bool(pet),\'missing_since\':None}\n    if config and config.get(\'follower\'):\n        if hasattr(bot,\'stop_bot\'):\n            bot.stop_bot()\n        # Native trade is completed by the buy/sell owner, never by a Trace retry.\n        bot.stop_script()\n    bot.stop_trace()\n    candidates=list(dict.fromkeys([member.get(\'job_name\'),member.get(\'name\'),target]))\n    traced=False\n    selected=target\n    for candidate in candidates:\n        candidate = str(candidate or \'\').strip()\n        if not candidate:\n            continue\n        try:\n            traced=bool(bot.start_trace(candidate))\n        except Exception:\n            traced=False\n        if traced:\n            selected=candidate\n            break\n    if traced:\n        follow_intent[\'missing_since\']=None\n        if member.get(\'player_id\'):\n            follow_intent[\'last_uid\']=member[\'player_id\']\n        follow_mode=\'trace\'\n        active=True\n        follow_missing_since=None\n        follow_request=None\n        follower_mount_guard.clear()\n        set_state(\'Trace phBot: \'+selected)\n        say_throttled(\'trace_started\',\'Da bat Trace phBot theo \'+selected+\'.\',15)\n        return True\n    active=False\n    follow_mode=None\n    if follow_request is None:\n        follow_request={\'owner\':identity,\'target\':target,\'next\':time.monotonic()+5,\n                        \'deadline\':float(\'inf\'),\'independent\':True,\'persistent\':True,\n                        \'needs_transport\':follow_intent.get(\'needs_transport\',False),\'mount_tries\':0}\n    set_state(\'Cho phBot chap nhan Trace: \'+target)\n    say_throttled(\'trace_retry\',\'phBot chua bat duoc Trace theo \'+target+\'; thu lai moi 5s cho den khi Trace duoc hoac nhan lenh dung. Khong chuyen sang theo toa do.\',15)\n    return False\n\n\ndef maintain_trace_transport():\n    # Preserve the mounted-trader requirement while movement itself belongs to phBot Trace.\n    if follow_blocked or not active or follow_mode!=\'trace\' or not config or not config.get(\'follower\'):\n        return\n    uid,pet=follower_transport_entry()\n    if pet is None:\n        if follow_intent and follow_intent.get(\'needs_transport\'):\n            pause_trace_for_rejoin(\'cho thu van tai xuat hien lai\',hold=True)\n        elif not standalone_follow:\n            stop_owned()\n            say(\'Buon phu: mat thu van tai; dung Trace, cho xu ly thu.\')\n        return\n    now=time.monotonic()\n    if pet.get(\'mounted\'):\n        if follower_mount_guard.get(\'trace_paused\'):\n            follower_mount_guard.clear()\n            start_follow_target(current_follow_target())\n        return\n    if not follower_mount_guard.get(\'trace_paused\'):\n        bot.stop_trace()\n        stop_at_current_position()\n        follower_mount_guard[\'trace_paused\']=True\n    if now<follower_mount_guard.get(\'next\',float(\'-inf\')):\n        return\n    if follower_mount_guard.get(\'tries\',0)>=3:\n        pause_trace_for_rejoin(\'cho len lai thu van tai\',hold=True)\n        if follow_request:\n            follow_request[\'mount_tries\']=3\n        return\n    follower_mount_guard[\'tries\']=follower_mount_guard.get(\'tries\',0)+1\n    follower_mount_guard[\'next\']=now+5\n    bot.inject_joymax(0x70CB,b\'\\x01\'+struct.pack(\'<I\',uid),False)\n    set_state(\'Tam dung Trace de len lai thu van tai\')\n\n\ndef activate_follow():\n    global standalone_follow, follow_override\n    load_identity()\n    if not identity or not config:\n        say(\'Dang nhap va Luu cau hinh truoc khi bat di theo.\')\n        return\n    try:\n        leaders = [name.strip() for name in QtBind.text(gui, leaders_box).split(\',\') if name.strip()]\n        targets = [name for name in leaders if norm(name) not in own_names() and party_member(name)]\n        if not targets:\n            raise ValueError(\'Nhap ten Leader o dong Leader(s); Leader can o cung Party va khac acc nay\')\n        target = targets[0]\n        if defer_follower_follow(target):\n            return\n        # Explicit mode switch cancels owned route/recovery, preserving its saved checkpoint.\n        set_loop(False)\n        stop_owned()\n        if not config[\'hunter\'] and hasattr(bot, \'stop_bot\'):\n            bot.stop_bot()\n        follow_override = target\n        enable_following()\n        start_follow_target(target)\n        standalone_follow = True\n        say(\'Di theo doc lap Leader \'+target+\': khong mua hang/khong kiem tra thu hay moc thu hoi.\')\n    except Exception as error:\n        say(\'Khong bat duoc di theo: \'+str(error))\n\n\ndef current_follow_target():\n    return (follow_override or (config or {}).get(\'follow\', \'\')).strip()\n\n\ndef send_guard_command(action):\n    if not config or not (own_names() & names(config[\'leaders\'])):\n        say(\'Chi Leader trong danh sach da luu duoc goi di theo/dung theo.\')\n        return\n    requested = list(dict.fromkeys(name.strip() for name in QtBind.text(gui, follow_box).split(\',\') if name.strip()))\n    if not requested:\n        say(\'Nhap ten nhan lenh, ngan cach bang dau phay: AG_He, AGbuon2\')\n        return\n    targets, used = [], set()\n    for name in requested:\n        member = resolve_follow_target(name)\n        if norm(name) in own_names():\n            say(\'Bo qua chinh Leader: \'+name)\n            continue\n        if not member:\n            say(\'Bo qua ten khong co trong Party: \'+name)\n            continue\n        canonical = member.get(\'name\') or name\n        if norm(canonical) not in used:\n            targets.append(canonical)\n            used.add(norm(canonical))\n    # One targeted message per character avoids long/truncated chat payloads.\n    for target in targets:\n        payload = base64.b64encode(target.encode(\'utf-8\')).decode(\'ascii\')\n        token = uuid.uuid4().hex[:16]\n        message = PREFIX+token+\' \'+action+\' \'+payload\n        if len(message)>120:\n            say(\'Ten qua dai, khong gui: \'+target)\n            continue\n        seen[token] = time.monotonic()\n        if action==\'FOLLOWTO\':\n            for old_token,record in list(follow_stop_sent.items()):\n                if convoy_name(record[\'target\'])==convoy_name(target):\n                    del follow_stop_sent[old_token]\n        if action==\'UNFOLLOWTO\':\n            follow_stop_sent[token]={\'target\':target,\'deadline\':time.monotonic()+12}\n        if control_party(message):\n            if action==\'UNFOLLOWTO\':\n                follow_stop_sent[token].update(message=message)\n            say(\'Da goi {}: {} Leader nay.\'.format(target, \'di theo\' if action==\'FOLLOWTO\' else \'dung theo\'))\n        else:\n            say(\'Khong gui duoc lenh cho \'+target)\n\n\ndef receive_guard_command(player, action, payload, token=None):\n    global follow_override, follow_request, last_go, loop_pending\n    if not config:\n        return\n    try:\n        if len(payload) > 100:\n            return\n        guard = base64.b64decode(payload, validate=True).decode(\'utf-8\')\n        if norm(guard) not in own_names():\n            return\n        if action == \'UNFOLLOWTO\':\n            say(\'Nhan TAT THEO tu \'+player+\' qua Party; huy theo va kiem tra dung.\')\n            if token:\n                control_party(\'!CRSTOP \'+token+\' RECEIVED\')\n            stop_following(force=True,token=token)\n            return\n        member = resolve_follow_target(player)\n        target = member.get(\'name\') if member else player\n        if not target or norm(target) in own_names():\n            return\n        if defer_follower_follow(target):\n            return\n        set_loop(False)\n        stop_owned()\n        follow_override = target\n        enable_following()\n        loop_pending = None\n        last_go = float(\'-inf\')\n        follow_request = {\'owner\': identity, \'target\': target,\n                          \'next\': time.monotonic(), \'deadline\': time.monotonic()+60, \'independent\': True}\n        say(\'Nhan lenh tu {}: acc nay se tim va di theo {}. KHONG mua hang.\'.format(player, target))\n        follow_request_tick()\n    except (ValueError, UnicodeError, TypeError) as error:\n        say(\'Lenh goi Bao tieu khong hop le: \' + str(error))\n\n\ndef follow_request_tick():\n    global follow_request, standalone_follow\n    context = follow_request\n    if not context:\n        return\n    if follow_blocked:\n        follow_request=None\n        return\n    if context[\'owner\'] != identity or not config:\n        follow_request = None\n        return\n    now = time.monotonic()\n    if config.get(\'follower\') and (follower_state or finish_context or trade_npc_close):\n        context[\'next\']=now+2\n        context[\'deadline\']=max(context.get(\'deadline\',now),now+60)\n        return\n    if active:\n        follow_request = None\n        return\n    if now < context[\'next\']:\n        return\n    if not context.get(\'persistent\') and now > context[\'deadline\']:\n        follow_request = None\n        set_state(\'Het thoi gian tim acc Buon; can goi lai\')\n        say(\'Chua tim/bam duoc {} sau 60s. Can cung khu, trong tam phBot; khong tu teleport.\'.format(context[\'target\']))\n        return\n    context[\'next\'] = now+5\n    try:\n        if context.get(\'independent\'):\n            member = resolve_follow_target(context[\'target\'])\n            if not member:\n                set_state(\'Dang cho Leader vao Party: \' + context[\'target\'])\n                return\n            character=bot.get_character_data() or {}\n            if not character or character.get(\'dead\'):\n                raise ValueError(\'cho nhan vat hoi sinh/du lieu spawn\')\n            if not trace_region_reachable(character, member):\n                raise ValueError(\'cho Leader va acc nay o cung khu\')\n            uid,pet=follower_transport_entry() if config.get(\'follower\') else (None,None)\n            if context.get(\'needs_transport\') or pet:\n                if not pet:\n                    raise ValueError(\'cho thu van tai xuat hien; khong tu mua/goi thu sau teleport\')\n                if not pet.get(\'mounted\'):\n                    if context.get(\'mount_uid\')!=uid:\n                        context.update(mount_uid=uid,mount_tries=0)\n                    if context.get(\'mount_tries\',0)<3:\n                        bot.inject_joymax(0x70CB,b\'\\x01\'+struct.pack(\'<I\',uid),False)\n                        context[\'mount_tries\']=context.get(\'mount_tries\',0)+1\n                    raise ValueError(\'cho len lai thu van tai, giu lenh theo\')\n            if not config[\'hunter\'] and hasattr(bot, \'stop_bot\'):\n                bot.stop_bot()\n            start_follow_target(context[\'target\'])\n            standalone_follow = True\n        else:\n            run_go()\n        if active:\n            follow_request = None\n            return\n    except Exception as error:\n        say_throttled(\'trace_wait_target\',\'Dang cho Trace {}: {}\'.format(context[\'target\'],error),30)\n    set_state(\'Dang tim acc Buon: \' + context[\'target\'])\n\n\ndef send_team(action):\n    load_identity()\n    if not config or not (own_names() & names(config[\'leaders\'])):\n        say(\'Chi nhan vat trong danh sach Leader da luu duoc goi ca doi.\')\n        return\n    if not bot.get_party():\n        say(\'Can o trong Party de goi ca doi.\')\n        return\n    loaded_start = False\n    if action == \'NEWGO\' and not config[\'hunter\'] and not config.get(\'follower\'):\n        try:\n            pet = finish_transport()\n            if pet and transport_goods(pet) > 0:\n                if active or recovery or return_request or finish_context or convoy_controller or local_sale or route_crossing:\n                    raise ValueError(\'Dang chay/xu ly giao dich. Tam dung hoac cho xu ly xong truoc khi goi mua.\')\n                if not pet.get(\'mounted\'):\n                    raise ValueError(\'Len thu dang cho hang truoc khi goi Buon phu mua.\')\n                if QtBind.isChecked(gui, hunter_check) or QtBind.isChecked(gui, follower_check):\n                    raise ValueError(\'Luu dung vai tro Leader buon chinh truoc khi goi ca doi.\')\n                if (QtBind.text(gui, step_box).strip() or \'0\') != \'0\':\n                    raise ValueError(\'De Buoc = 0 de dinh vi tuyen va giu hang Leader, khong mua lai.\')\n                loaded_start = True\n            with open(selected_script_path(), encoding=\'utf-8-sig\') as stream:\n                lines = [line.strip() for line in stream if line.strip() and not line.lstrip().startswith((\'#\', \'//\'))]\n            validate_route_ferry_steps(lines)\n        except (OSError, ValueError) as error:\n            say(\'Chua goi ca doi: \'+str(error))\n            return\n    # Loaded leaders resume after buying; followers receive GO to clear a prior STOP,\n    # then the existing BUY_QUERY handshake summons/buys only on follower accounts.\n    if loaded_start:\n        action = \'GO\'\n    token = uuid.uuid4().hex[:16]\n    message = PREFIX + token + \' \' + action\n    seen[token] = time.monotonic()\n    if control_party(message):\n        if loaded_start:\n            globals()[\'route_switch_requested\'] = True\n            globals()[\'loaded_convoy_start\'] = True\n            say(\'Leader da co hang: giu thu/hang, bo qua mua lai; goi Buon phu mua du va len thu truoc khi di.\')\n        else:\n            say(\'Da gui \'+action+\' den Party. Moi acc tu kiem tra dieu kien.\')\n        try:\n            execute(action)\n        finally:\n            if loaded_start:\n                globals().pop(\'loaded_convoy_start\', None)\n    else:\n        say(\'Khong gui duoc chat Party; chua thuc hien lenh.\')\n\n\ndef team_follow():\n    load_identity()\n    send_guard_command(\'FOLLOWTO\')\n\n\ndef team_unfollow():\n    load_identity()\n    send_guard_command(\'UNFOLLOWTO\')\n\n\ndef team_loop_on():\n    send_team(\'LOOPON\')\n\n\ndef team_loop_off():\n    send_team(\'LOOPOFF\')\n\n\ndef team_go():\n    send_team(\'GO\')\n\n\ndef team_stop():\n    send_team(\'STOP\')\n\n\ndef team_return():\n    send_team(\'RETURN\')\n\n\ndef party_command_parts(msg, prefix):\n    parts = msg.split()\n    if parts and parts[0] == prefix and len(parts)>1 and len(parts[1])==16 and all(c in \'0123456789abcdef\' for c in parts[1]):\n        parts.insert(1, \'\')\n    return parts\n\n\ndef handle_chat(t, player, msg):\n    global follow_override\n    load_identity()\n    stop_for_me=False\n    if isinstance(msg,str):\n        diagnostic=party_command_parts(msg,\'!CR1\')\n        if len(diagnostic)==5 and diagnostic[0]==\'!CR1\' and diagnostic[3]==\'UNFOLLOWTO\':\n            try:\n                target=base64.b64decode(diagnostic[4],validate=True).decode(\'utf-8\')\n                stop_for_me=norm(target) in own_names()\n            except (ValueError,UnicodeError,TypeError):\n                pass\n    if stop_for_me and not config:\n        say_throttled(\'stop_no_config\',\'Tu choi TAT THEO: acc nay chua Luu cau hinh Leader.\',10)\n    if not config or not isinstance(player, str) or not isinstance(msg, str):\n        return\n    if come_handle_chat(t, player, msg):\n        return\n    if t != 4:\n        return\n    if handle_buy_departure_chat(player,msg):\n        return\n    if handle_follow_stop_ack(player,msg):\n        return\n    if handle_follower_wait_chat(player, msg):\n        return\n    if handle_convoy(player, msg):\n        return\n    if not trusted_leader(player) or not party_member(player):\n        if stop_for_me:\n            say_throttled(\'stop_sender\',\'Tu choi TAT THEO tu \'+str(player)+\': kiem tra ten that/ten nghe trong Leader va cung Party.\',10)\n        return\n    parts = party_command_parts(msg, \'!CR1\')\n    if len(parts) not in (4, 5) or parts[0] != \'!CR1\':\n        return\n    targeted = parts[3] in (\'FOLLOWTO\', \'UNFOLLOWTO\')\n    if (targeted and len(parts) != 5) or (not targeted and (len(parts) != 4 or parts[3] not in (\'GO\', \'STOP\', \'RETURN\', \'FOLLOW\', \'UNFOLLOW\', \'LOOPON\', \'LOOPOFF\', \'NEWGO\', \'GUARDHOME\'))):\n        return\n    token = parts[2]\n    if len(token) != 16 or any(c not in \'0123456789abcdef\' for c in token):\n        return\n    if token in seen:\n        if targeted and parts[3]==\'UNFOLLOWTO\':\n            receive_guard_command(player,parts[3],parts[4],token)\n        return\n    now = time.monotonic()\n    for key in list(seen):\n        if now - seen[key] > 600:\n            del seen[key]\n    if len(seen) >= 512:\n        return\n    seen[token] = now\n    if targeted:\n        receive_guard_command(player, parts[3], parts[4], token)\n    else:\n        if parts[3] in (\'NEWGO\', \'GO\') and (config[\'hunter\'] or config.get(\'follower\')) and not current_follow_target():\n            member = resolve_follow_target(player)\n            follow_override = member.get(\'name\') if member else player\n            readable_set_text(gui, follow_box, follow_override)\n        execute(parts[3])\n\n\ndef finish_transport():\n    pets = bot.get_pets()\n    if not isinstance(pets, dict):\n        raise ValueError(\'Chua doc duoc du lieu thu, khong huy thu khi chua xac minh hang\')\n    transports = [pet for pet in pets.values() if pet.get(\'type\') == \'transport\' and float(pet.get(\'hp\', 0)) > 0]\n    if len(transports) > 1:\n        raise ValueError(\'Co nhieu thu van tai, can kiem tra thu cong\')\n    pet = transports[0] if transports else None\n    if pet is not None and not isinstance(pet.get(\'items\'), list):\n        raise ValueError(\'Khong doc duoc tui hang thu\')\n    return pet\n\n\ndef persist_finish(stage):\n    trip[\'finish_stage\'] = stage\n    persist_trip()\n\n\ndef begin_finish(coordinated=False, wait_for_ve=False):\n    global finish_context, merchant_step\n    merchant_step = None\n    if not coordinated and config.get(\'sell_team\') and own_names() & names(config[\'leaders\']) and not config.get(\'follower\'):\n        sell_team()\n        return\n    saved = (trip or {}).get(\'finish_stage\')\n    pet = finish_transport()\n    if local_sale and local_sale.get(\'keep\'):\n        if pet is None:\n            raise ValueError(\'Can thu van tai hien tai de ban va mua lai.\')\n        stage = \'sell\' if transport_goods(pet) else \'sold\'\n    elif pet and transport_goods(pet) > 0 and coordinated:\n        # A fresh SELL batch owns this sale, irrespective of last trip\'s checkpoint.\n        stage = \'sell\'\n    elif saved in (\'sold\', \'terminate\', \'ve\', \'sold_wait\', \'done\'):\n        if pet and transport_goods(pet) > 0:\n            raise ValueError(\'Thu lai co hang; dung ket thuc de tranh huy hang\')\n        stage = \'terminate\' if pet else \'ve\'\n    else:\n        if pet is None:\n            raise ValueError(\'Khong thay thu van tai de xac minh da ban hang. Kiem tra thu cong\')\n        stage = \'sell\' if transport_goods(pet) > 0 else \'sold\'\n    finish_context = {\'stage\': stage, \'deadline\': time.monotonic()+90, \'sent\': False,\n                      \'wait_for_ve\': wait_for_ve}\n    if not wait_for_ve and not (local_sale and local_sale.get(\'keep\')):\n        persist_finish(stage)\n    if local_sale and local_sale.get(\'keep\'):\n        say(\'Doi chieu: ban hang tren thu hien tai, cho ca doi ban xong.\')\n    else:\n        say(\'Ket thuc tuyen: xu ly ban/huy/VE truc tiep; khong phu thuoc dieu kien Trong khu vuc dao tao.\')\n    finish_tick()\n\n\ndef finish_tick():\n    global finish_context, active, last_return\n    context = finish_context\n    if not context:\n        return\n    if time.monotonic() > context[\'deadline\']:\n        bot.stop_script()\n        finish_context = None\n        active = False\n        set_state(\'Ket thuc tuyen bi dung: qua thoi gian cho\')\n        say(\'Chua xac minh xong ban/huy/VE; GO de thu lai. Chua huy thu khi con hang.\')\n        return\n    stage = context[\'stage\']\n    if stage == \'sell\':\n        pet = finish_transport()\n        if pet is None:\n            raise ValueError(\'Thu bien mat truoc khi xac minh ban het; khong gui VE\')\n        count = transport_goods(pet)\n        if count > 0:\n            if not context[\'sent\']:\n                context[\'sent\'] = True\n                context[\'npc_trade_started_at\'] = time.monotonic()\n                bind_native_trade(context)\n                if bot.start_script(\'oldtrade,sell\\nwait,90000\\n\') is False:\n                    raise ValueError(\'phBot khong chay duoc lenh ban\')\n                say(\'Da gui oldtrade,sell; giu script cho trong khi ban. Chi dong NPC khi tui thu ve 0.\')\n            context.pop(\'empty_since\', None)\n            set_state(\'Dang ban: con {} hang tren thu\'.format(count))\n            return\n        # Do not close an NPC on a transient empty inventory update.\n        if \'empty_since\' not in context:\n            context[\'empty_since\'] = time.monotonic()\n            return\n        if time.monotonic()-context[\'empty_since\'] < 1:\n            return\n        bot.stop_script()\n        context.update(stage=\'sold\', sent=False)\n        if not context.get(\'wait_for_ve\') and not (local_sale and local_sale.get(\'keep\')):\n            persist_finish(\'sold\')\n        stage = \'sold\'\n    if stage == \'sold\':\n        if not ensure_trade_npc_closed(context, time.monotonic()):\n            return\n        pet = finish_transport()\n        if pet and transport_goods(pet) > 0:\n            raise ValueError(\'Thu van con hang; khong huy\')\n        if local_sale and local_sale.get(\'keep\'):\n            if pet is None:\n                raise ValueError(\'Thu da bien mat truoc khi mua lai.\')\n            finish_context, active = None, False\n            set_state(\'Da ban het, giu thu va cho mua lai\')\n            sale_reply(\'SOLD\')\n            return\n        context.update(stage=\'terminate\' if pet else \'ve\', sent=False,\n                       deadline=time.monotonic()+45)\n        if not context.get(\'wait_for_ve\'):\n            persist_finish(context[\'stage\'])\n        stage = context[\'stage\']\n    if stage == \'terminate\':\n        pet = finish_transport()\n        if pet:\n            if transport_goods(pet) > 0:\n                raise ValueError(\'Thu con hang; khong huy\')\n            if not context[\'sent\']:\n                context[\'sent\'] = True\n                if bot.start_script(\'terminate,all\\n\') is False:\n                    raise ValueError(\'phBot khong chay duoc terminate,all\')\n                say(\'Da ban het; yeu cau terminate,all. Doi thu bien mat.\')\n            set_state(\'Da ban het - dang huy thu\')\n            return\n        bot.stop_script()\n        context.update(stage=\'ve\', sent=False)\n        if not context.get(\'wait_for_ve\'):\n            persist_finish(\'ve\')\n        stage = \'ve\'\n    if stage == \'ve\':\n        if context.get(\'wait_for_ve\'):\n            finish_context, active = None, False\n            set_state(\'Da ban/huy thu - cho Leader VE\')\n            say(\'BAN: da ban het va huy thu. Cho Leader chat VE neu can.\')\n            return\n        if not local_sale and own_names() & names(config[\'leaders\']):\n            if \'come_at\' not in context:\n                context[\'come_at\'] = time.monotonic()+2\n                set_state(\'Da ban/huy thu - cho 2 giay roi VE\')\n                return\n            if time.monotonic() < context[\'come_at\']:\n                return\n            if not phBotChat.Party(\'VE\'):\n                raise ValueError(\'Khong gui duoc Party VE\')\n            trip[\'cursor\'], trip[\'uncertain\'] = len(trip_lines), None\n            persist_finish(\'return_pending\')\n            finish_context, active = None, False\n            execute(\'RETURN\')\n            return\n        trip[\'cursor\'], trip[\'uncertain\'] = len(trip_lines), None\n        persist_finish(\'sold_wait\')\n        finish_context, active = None, False\n        set_state(\'Da ban/huy thu - cho Leader VE\')\n        if local_sale:\n            sale_reply(\'SOLD\')\n\n\n\ndef handle_come(t, player, msg):\n    if t not in (1, 4) or msg.strip().upper() != \'VE\' or not config:\n        return False\n    if t == 1 and not config[\'hunter\']:\n        return True  # All COME addresses guards; Party COME can return both roles.\n    if norm(player) in own_names():\n        return True  # The sender performs its own return after the broadcast.\n    if not trusted_leader(player) or not party_member(player):\n        return False\n    if not config[\'hunter\']:\n        pet = alive_transport()\n        if pet and transport_goods(pet) > 0:\n            say(\'Nhan VE nhung acc buon con hang; chua ve thanh, can ban truoc.\')\n            return True\n    if trip and trip.get(\'finish_stage\') == \'sold_wait\':\n        persist_finish(\'return_pending\')\n    say(\'Nhan VE tu Leader: dung va ve thanh.\')\n    execute(\'RETURN\')\n    return True\n\n\ndef transport_goods(pet):\n    return sum(max(0, int(item.get(\'quantity\', 1))) for item in (pet.get(\'items\') or []) if isinstance(item, dict))\n\n\ndef snapshot_position(source, fallback=None):\n    fallback = fallback or {}\n    try:\n        position = {\'region\': source.get(\'region\', fallback.get(\'region\')),\n                    \'x\': float(source[\'x\']), \'y\': float(source[\'y\']),\n                    \'z\': float(source.get(\'z\') or 0)}\n        if position[\'region\'] is None or not all(math.isfinite(position[k]) for k in (\'x\', \'y\', \'z\')):\n            return None\n        return position\n    except (KeyError, ValueError, TypeError):\n        return None\n\n\ndef pickup_search_position_allowed(context):\n    center = context.get(\'search_center\')\n    current = snapshot_position(bot.get_character_data() or {})\n    return bool(center and current and current[\'region\'] == center[\'region\'] and\n                math.hypot(current[\'x\']-center[\'x\'], current[\'y\']-center[\'y\']) <= 35.0)\n\n\ndef prepare_pickup_search(context):\n    center = context.get(\'search_center\') or snapshot_position(bot.get_character_data() or {})\n    if not center:\n        raise ValueError(\'Chua co toa do sau dich chuyen de lam tam gioi han 35m\')\n    context[\'search_center\'] = center\n    drop = snapshot_position(context.get(\'drop_position\') or context[\'position\']) or center\n    # Use only real script waypoints. Restrict to one contiguous walk segment,\n    # never join across a teleport or other native action block.\n    walks = [(i, walk_point(line)) for i, line in enumerate(trip_lines)]\n    candidates = [(i, point) for i, point in walks if point is not None and\n                  math.hypot(point[0]-center[\'x\'], point[1]-center[\'y\']) <= 35]\n    if not candidates:\n        raise ValueError(\'Khong co toa do walk trong script nam trong 35m; dung nhat, khong tao vong tim tu do\')\n    anchor = min(candidates, key=lambda pair: (math.hypot(pair[1][0]-drop[\'x\'], pair[1][1]-drop[\'y\']),\n                                               abs(pair[0]-(trip or {}).get(\'cursor\', 0))))\n    by_index = dict(candidates)\n    left = right = anchor[0]\n    while left-1 in by_index:\n        left -= 1\n    while right+1 in by_index:\n        right += 1\n    order = list(range(anchor[0], right+1)) + list(range(right-1, left-1, -1))\n    ordered = [(i, by_index[i]) for i in order]\n    context.update(search_points=[(point[0], point[1]) for _, point in ordered],\n                   search_heights=[point[2] for _, point in ordered],\n                   search_steps=[i+1 for i, _ in ordered], search_index=0, last_goods=None,\n                   last_progress=time.monotonic(), search_move_sent=False,\n                   last_search_move=float(\'-inf\'))\n    if trip and trip.get(\'recovery_pending\'):\n        trip[\'recovery_pending\'][\'search_center\'] = center\n        persist_trip()\n    say(\'Tam sau dich chuyen: {}. Tim G tai {} moc walk script (buoc {}..{}), gioi han 35m. Diem roi={}. Khong tao vong tron.\'.format(\n        center, len(ordered), left+1, right+1, drop))\n    if math.hypot(drop[\'x\']-center[\'x\'], drop[\'y\']-center[\'y\']) > 35:\n        say(\'Diem roi ngoai 35m; chi tim cac moc script trong gioi han, khong tu mo rong.\')\n\n\ndef pickup_search_tick(context, count):\n    if not pickup_search_position_allowed(context):\n        recovery_failed(\'Da ra ngoai 35m quanh diem dich chuyen; dung di chuyen va nhat G\')\n        return False\n    now = time.monotonic()\n    previous = context.get(\'last_goods\')\n    if count > (previous or 0):\n        if not context.get(\'cluster_until\'):\n            stop_at_current_position()\n            say(\'Da nhat duoc hang; dung tai cho va G lien tuc. Chi doi moc khi 10s khong tang hang.\')\n        context[\'cluster_until\'] = now+10\n        context[\'last_progress\'] = now\n    if previous != count:\n        context[\'last_goods\'], context[\'last_progress\'] = count, now\n    if context.get(\'cluster_until\'):\n        if count > 0 and now < context[\'cluster_until\']:\n            set_state(\'Dung nhat G tai cum hang: {} hang\'.format(count))\n            return True\n        context.pop(\'cluster_until\', None)\n        context[\'last_progress\'] = now\n        say(\'10s khong nhat them hang; tiep tuc G/tim tai cac moc script trong 35m.\')\n    index = context[\'search_index\']\n    points = context[\'search_points\']\n    if index >= len(points):\n        return True  # search finished: stay inside the boundary and keep trying G until timeout\n    target = points[index]\n    current = snapshot_position(bot.get_character_data() or {})\n    if math.hypot(current[\'x\']-target[0], current[\'y\']-target[1]) > 1.0:\n        if now-context[\'last_search_move\'] >= 2:\n            bot.move_to(target[0], target[1], context.get(\'search_heights\', [context[\'search_center\'][\'z\']]*len(points))[index])\n            context[\'last_search_move\'] = now\n            context[\'search_move_sent\'] = True\n        context[\'last_progress\'] = now\n        set_state(\'Tim hang trong 35m: diem {}/{}\'.format(index+1, len(points)))\n        return False  # press G after arriving, avoiding pickup interrupting this movement\n    if now-context[\'last_progress\'] >= 2:\n        context[\'search_index\'] += 1\n        context[\'last_progress\'] = now\n    return True\n\n\ndef remember_transports():\n    global transport_cache\n    getter = getattr(bot, \'get_pets\', None)\n    if not getter:\n        return\n    pets = getter() or {}\n    for uid, pet in pets.items():\n        if pet.get(\'type\') == \'transport\' and float(pet.get(\'hp\', 0)) > 0:\n            character = bot.get_character_data() or {}\n            pet_position = snapshot_position(pet, character) if \'x\' in pet and \'y\' in pet else None\n            last_position = pet_position or snapshot_position(character)\n            transport_cache[int(uid)] = dict(pet, goods=transport_goods(pet),\n                last_position=last_position, position_source=\'pet\' if pet_position else \'character\')\n    # Do not infer death from disappearance: it may be a teleport or recall.\n    if active and config and not config[\'hunter\'] and not recovery:\n        for uid, pet in pets.items():\n            if int(uid) in transport_cache and pet.get(\'type\') == \'transport\' and pet.get(\'hp\') == 0:\n                transport_died(int(uid))\n                break\n\n\ndef restore_pickup_settings(context):\n    area = context.get(\'training_backup\')\n    if area:\n        bot.set_training_script(area.get(\'path\', \'\'))\n        bot.set_training_position(area[\'region\'], area[\'x\'], area[\'y\'], area.get(\'z\', 0))\n        bot.set_training_radius(area[\'radius\'])\n\n\ndef cancel_recovery(restore=True):\n    global recovery\n    stop_pickup_keys()\n    context, recovery = recovery, None\n    if not context:\n        return\n    try:\n        if context.get(\'pickup_started\'):\n            bot.stop_bot()\n        if context.get(\'stage\') in (\'spawn\', \'fallback_spawn\'):\n            bot.stop_script()\n        if context.get(\'search_move_sent\'):\n            current = snapshot_position(bot.get_character_data() or {})\n            if current:\n                bot.move_to(current[\'x\'], current[\'y\'], current[\'z\'])\n    finally:\n        if restore:\n            restore_pickup_settings(context)\n    # The saved recovery marker remains, requiring explicit verification before GO.\n\n\ndef recovery_failed(message):\n    cancel_recovery(restore=True)\n    set_state(\'Thu chet: da dung - \' + message)\n    say(\'Khoi phuc dung: \' + message + \'. Khong tu dung them cuon/khong tu mua hang.\')\n\n\nferry_transport_grace = 0.0\n\n\ndef transport_died(uid):\n    global recovery\n    if not transport_feature_allowed():\n        return\n    if finish_context and finish_context.get(\'stage\') in (\'terminate\', \'ve\'):\n        return\n    if not active or standalone_follow or not config or config[\'hunter\'] or recovery or uid not in transport_cache:\n        return\n    cached = transport_cache[uid]\n    if (merchant_step and merchant_step.get(\'terminates_transport\')\n            and isinstance(cached.get(\'items\'), list) and cached.get(\'goods\') == 0):\n        transport_cache.pop(uid, None)\n        say(\'Thu UID={} da het hang va duoc huy theo TXT; tiep tuc xu ly tuyen.\'.format(uid))\n        return\n    if time.monotonic() < ferry_transport_grace:\n        say_throttled(\'ferry_transport_grace\',\n                      \'Dang qua pha: tam hoan xu ly thu chet. Se kiem tra lai HP cua thu.\', 8)\n        return\n    c = bot.get_character_data() or {}\n    position = {k: c.get(k) for k in (\'region\', \'x\', \'y\', \'z\')}\n    position[\'z\'] = position.get(\'z\') or 0\n    drop_position = transport_cache[uid].get(\'last_position\') or snapshot_position(c)\n    position_source = transport_cache[uid].get(\'position_source\', \'character\')\n    goods = transport_cache[uid].get(\'goods\', 0)\n    mode = selected_transport_mode() or 1\n    stop_owned()\n    bot.stop_bot()  # All death modes must stop native bot movement before recovery.\n    transport_cache.pop(uid, None)\n    if trip:\n        trip[\'recovery_pending\'] = {\'position\': position, \'drop_position\': drop_position, \'position_source\': position_source, \'goods\': goods, \'uid\': uid}\n        persist_trip()\n    say(\'Da luu toa do hang roi cuoi: {} | nguon={}\'.format(drop_position, position_source))\n    say(\'Thu van tai UID={} chet. Che do={} | hang ghi nhan={}. Da giu moc tuyen.\'.format(uid, mode, goods))\n    if mode == 1:\n        set_state(\'Thu chet: dung tai cho, cho xu ly hang\')\n        return\n    if c.get(\'dead\'):\n        set_state(\'Nhan vat cung da chet - can hoi sinh/xu ly thu cong\')\n        return\n    if mode == 3 and (not hasattr(bot, \'reverse_return\') or not callable(getattr(bot, \'get_pets\', None))):\n        say(\'phBot thieu API reverse_return/get_pets. Da dung; chua dung cuon.\')\n        return\n    if mode == 3:\n        pickup_client_info()  # Fail before consuming scrolls if no game window exists.\n    # Stage is assigned before using the scroll so even synchronous callbacks see it.\n    recovery = {\'stage\': \'return\', \'deadline\': time.monotonic()+90,\n                \'mode\': mode, \'position\': position, \'drop_position\': drop_position, \'goods\': goods,\n                \'owner\': identity, \'script\': (trip or {}).get(\'path\')}\n    if not bot.use_return_scroll():\n        recovery_failed(\'Khong dung duoc Return Scroll\')\n        return\n    set_state(\'Thu chet: dang ve thanh\')\n\n\ndef recovery_near_origin(context):\n    c = bot.get_character_data() or {}\n    pos = context[\'position\']\n    try:\n        return c.get(\'region\') == pos.get(\'region\') and math.hypot(c[\'x\']-pos[\'x\'], c[\'y\']-pos[\'y\']) <= 35\n    except (KeyError, TypeError):\n        return False\n\n\ndef alive_transport():\n    for uid, pet in (bot.get_pets() or {}).items():\n        if pet.get(\'type\') == \'transport\' and float(pet.get(\'hp\', 0)) > 0:\n            return pet\n    return None\n\n\ndef find_pickup_window(pid):\n    if os.name != \'nt\':\n        return 0\n    import ctypes\n    from ctypes import wintypes\n    user = ctypes.WinDLL(\'user32\', use_last_error=True)\n    callback_type = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)\n    user.EnumWindows.argtypes = [callback_type, wintypes.LPARAM]\n    user.EnumWindows.restype = wintypes.BOOL\n    user.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]\n    user.GetWindowThreadProcessId.restype = wintypes.DWORD\n    user.GetClientRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]\n    user.GetClientRect.restype = wintypes.BOOL\n    windows = []\n    def collect(window, _):\n        owner = wintypes.DWORD()\n        user.GetWindowThreadProcessId(window, ctypes.byref(owner))\n        rect = wintypes.RECT()\n        if owner.value == pid and user.GetClientRect(window, ctypes.byref(rect)):\n            width, height = rect.right-rect.left, rect.bottom-rect.top\n            if width >= 200 and height >= 150:\n                windows.append((width*height, int(window)))\n        return True\n    callback = callback_type(collect)\n    user.EnumWindows(callback, 0)\n    return max(windows)[1] if windows else 0\n\n\ndef pickup_client_info():\n    client = bot.get_client() or {}\n    pid, window = int(client.get(\'pid\') or 0), int(client.get(\'window\') or 0)\n    if pid and not window and client.get(\'running\') is not False:\n        window = find_pickup_window(pid)\n    if not pid or not window or client.get(\'running\') is False:\n        raise ValueError(\'Can client game con chay de tu hien cua so/nhat G; clientless/kill client khong co cua so de mo\')\n    return pid, window\n\n\ndef focus_pickup_client():\n    # User-requested automatic game-window restore/selection while recovering cargo.\n    if os.name != \'nt\':\n        return False\n    import ctypes\n    from ctypes import wintypes\n    pid, window = pickup_client_info()\n    user = ctypes.WinDLL(\'user32\', use_last_error=True)\n    user.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]\n    user.GetWindowThreadProcessId.restype = wintypes.DWORD\n    user.IsIconic.argtypes = [wintypes.HWND]\n    user.IsIconic.restype = wintypes.BOOL\n    user.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]\n    user.BringWindowToTop.argtypes = [wintypes.HWND]\n    user.BringWindowToTop.restype = wintypes.BOOL\n    user.SetForegroundWindow.argtypes = [wintypes.HWND]\n    user.SetForegroundWindow.restype = wintypes.BOOL\n    user.GetForegroundWindow.restype = wintypes.HWND\n    owner = wintypes.DWORD()\n    user.GetWindowThreadProcessId(window, ctypes.byref(owner))\n    if owner.value != pid:\n        return False\n    user.ShowWindow(window, 9 if user.IsIconic(window) else 5)  # restore minimized OR show hidden\n    user.BringWindowToTop(window)\n    user.SetForegroundWindow(window)\n    foreground = user.GetForegroundWindow()\n    owner.value = 0\n    if not foreground:\n        return False\n    user.GetWindowThreadProcessId(foreground, ctypes.byref(owner))\n    return owner.value == pid\n\n\ndef send_pickup_g(pid, window):\n    global pickup_user32, pickup_input_type\n    if os.name != \'nt\':\n        raise OSError(\'Gui phim G can Windows\')\n    import ctypes\n    from ctypes import wintypes\n    user = pickup_user32\n    if user is None:\n        user = ctypes.WinDLL(\'user32\', use_last_error=True)\n        user.IsWindow.argtypes = [wintypes.HWND]\n        user.IsWindow.restype = wintypes.BOOL\n        user.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]\n        user.GetWindowThreadProcessId.restype = wintypes.DWORD\n        user.GetForegroundWindow.argtypes = []\n        user.GetForegroundWindow.restype = wintypes.HWND\n        user.MapVirtualKeyW.argtypes = [wintypes.UINT, wintypes.UINT]\n        user.MapVirtualKeyW.restype = wintypes.UINT\n        user.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]\n        user.PostMessageW.restype = wintypes.BOOL\n        pickup_user32 = user\n    owner = wintypes.DWORD()\n    if not user.IsWindow(window) or not user.GetWindowThreadProcessId(window, ctypes.byref(owner)) or owner.value != pid:\n        raise ValueError(\'Cua so/PID game thay doi; khong gui nham acc\')\n    foreground = user.GetForegroundWindow()\n    front_owner = wintypes.DWORD()\n    if foreground:\n        user.GetWindowThreadProcessId(foreground, ctypes.byref(front_owner))\n    scan = user.MapVirtualKeyW(0x47, 0) & 0xFF\n    if front_owner.value == pid:\n        if pickup_input_type is None:\n            # Fixed-width Win32 members retain the correct x86/x64 INPUT union layout.\n            class KEYBDINPUT(ctypes.Structure):\n                _fields_ = [(\'wVk\', ctypes.c_uint16), (\'wScan\', ctypes.c_uint16),\n                            (\'dwFlags\', ctypes.c_uint32), (\'time\', ctypes.c_uint32),\n                            (\'dwExtraInfo\', ctypes.c_size_t)]\n            class MOUSEINPUT(ctypes.Structure):\n                _fields_ = [(\'dx\', ctypes.c_int32), (\'dy\', ctypes.c_int32),\n                            (\'mouseData\', ctypes.c_uint32), (\'dwFlags\', ctypes.c_uint32),\n                            (\'time\', ctypes.c_uint32), (\'dwExtraInfo\', ctypes.c_size_t)]\n            class HARDWAREINPUT(ctypes.Structure):\n                _fields_ = [(\'uMsg\', ctypes.c_uint32), (\'wParamL\', ctypes.c_uint16), (\'wParamH\', ctypes.c_uint16)]\n            class INPUTUNION(ctypes.Union):\n                _fields_ = [(\'ki\', KEYBDINPUT), (\'mi\', MOUSEINPUT), (\'hi\', HARDWAREINPUT)]\n            class INPUT(ctypes.Structure):\n                _anonymous_ = (\'u\',)\n                _fields_ = [(\'type\', ctypes.c_uint32), (\'u\', INPUTUNION)]\n            pickup_input_type = INPUT\n            user.SendInput.argtypes = [wintypes.UINT, ctypes.POINTER(INPUT), ctypes.c_int]\n            user.SendInput.restype = wintypes.UINT\n        INPUT = pickup_input_type\n        down, up = INPUT(), INPUT()\n        down.type = up.type = 1\n        down.ki.wScan = up.ki.wScan = scan\n        down.ki.dwFlags, up.ki.dwFlags = 0x0008, 0x0008 | 0x0002\n        if user.SendInput(1, ctypes.byref(down), ctypes.sizeof(INPUT)) != 1:\n            raise OSError(\'Windows chan phim G thuc (SendInput); kiem tra quyen phBot/game\')\n        try:\n            threading.Event().wait(0.025)\n        finally:\n            if user.SendInput(1, ctypes.byref(up), ctypes.sizeof(INPUT)) != 1:\n                raise OSError(\'Windows khong nha duoc phim G\')\n        return \'real\'\n    # Background fallback stays restricted to the client\'s own window. The status\n    # explicitly distinguishes it from actual foreground keyboard input.\n    down = 1 | (scan << 16)\n    up = ctypes.c_ssize_t(down | (1 << 30) | (1 << 31)).value\n    first = user.PostMessageW(window, 0x0100, 0x47, down)\n    char_ok = user.PostMessageW(window, 0x0102, ord(\'g\'), down)\n    last = user.PostMessageW(window, 0x0101, 0x47, up)\n    if not first or not char_ok or not last:\n        raise OSError(\'Windows chan thong diep G nen: \' + str(ctypes.get_last_error()))\n    return \'background\'\n\n\ndef stop_pickup_keys():\n    global pickup_key_runtime\n    runtime, pickup_key_runtime = pickup_key_runtime, None\n    if runtime:\n        runtime[\'stop\'].set()\n        worker = runtime[\'thread\']\n        if worker is not threading.current_thread():\n            worker.join(timeout=0.2)\n\n\ndef start_pickup_keys(context):\n    global pickup_key_runtime\n    stop_pickup_keys()\n    stopped = threading.Event()\n    def send_once():\n        started = time.monotonic()\n        mode = send_pickup_g(context[\'pickup_pid\'], context[\'pickup_window\'])\n        context[\'g_mode\'] = mode or \'unknown\'\n        context[\'g_count\'] += 1\n        context[\'g_real_count\'] = context.get(\'g_real_count\', 0) + (1 if mode == \'real\' else 0)\n        context[\'last_g\'] = started\n    # First G immediately after mounted state is confirmed, not at the next waypoint.\n    send_once()\n    def pump():\n        due = context[\'last_g\']+0.05\n        while not stopped.wait(max(0.001, due-time.monotonic())):\n            if time.monotonic() >= context[\'deadline\']:\n                break\n            try:\n                send_once()\n                due = max(context[\'last_g\']+0.05, time.monotonic()+0.001)\n            except Exception as error:\n                context[\'key_error\'] = str(error)\n                break\n    worker = threading.Thread(target=pump, name=\'CaravanPickupG\', daemon=True)\n    pickup_key_runtime = {\'stop\': stopped, \'thread\': worker, \'context\': context}\n    worker.start()\n\n\ndef prepare_direct_pickup_route(context):\n    current = snapshot_position(bot.get_character_data() or {})\n    drop = snapshot_position(context.get(\'drop_position\') or context[\'position\'])\n    if not current or not drop or current[\'region\'] != drop[\'region\']:\n        raise ValueError(\'Thieu toa do/cung khu de di ve diem roi\')\n    context[\'search_center\'] = drop  # fixed cargo position, never a moving center\n    walks = [(i, walk_point(line)) for i, line in enumerate(trip_lines)]\n    walks = [(i, point) for i, point in walks if point is not None]\n    route = []\n    if walks:\n        start = min(walks, key=lambda pair: math.hypot(pair[1][0]-current[\'x\'], pair[1][1]-current[\'y\']))\n        finish = min(walks, key=lambda pair: math.hypot(pair[1][0]-drop[\'x\'], pair[1][1]-drop[\'y\']))\n        step = 1 if finish[0] >= start[0] else -1\n        indices = list(range(start[0], finish[0]+step, step))\n        by_index = dict(walks)\n        # Only follow a contiguous walk stretch; otherwise use the known drop directly.\n        if all(i in by_index for i in indices):\n            route = [by_index[i] for i in indices if math.hypot(by_index[i][0]-drop[\'x\'], by_index[i][1]-drop[\'y\']) <= 35]\n    route.append((drop[\'x\'], drop[\'y\'], drop[\'z\']))\n    context.update(approach_points=route, approach_index=0, initial_until=time.monotonic()+2,\n                   last_goods=0, cluster_locked=False, last_search_move=float(\'-inf\'),\n                   search_move_sent=False, returning_to_drop=False)\n    if trip and trip.get(\'recovery_pending\'):\n        trip[\'recovery_pending\'][\'search_center\'] = drop\n        persist_trip()\n\n\ndef start_recovery_pickup():\n    context = recovery\n    pid, window = pickup_client_info()\n    pet = alive_transport()\n    if not pet or not pet.get(\'mounted\'):\n        raise ValueError(\'Chi nhat G sau khi da len thu van tai moi\')\n    context.update(stage=\'pickup\', deadline=time.monotonic()+180,\n                   pickup_pid=pid, pickup_window=window, last_g=float(\'-inf\'), g_count=0)\n    prepare_direct_pickup_route(context)\n    context[\'focus_ready\'] = focus_pickup_client()\n    context[\'next_auto_focus\'] = time.monotonic()+2\n    context[\'last_focus_warning\'] = float(\'-inf\')\n    say(\'Tu hien/chon cua so game de nhat: \' + (\'OK\' if context[\'focus_ready\'] else \'chua duoc, se thu lai moi 2s\'))\n    start_pickup_keys(context)\n    say(\'Che do gui G: {} (real=ban phim thuc, background=gui nen).\'.format(context.get(\'g_mode\', \'?\')))\n    set_state(\'Nhat G ngay tai cho; sau 2s chua co hang moi di ve diem roi\')\n    say(\'Da len thu: G ngay, chu ky 0.05s, PID={} HWND={}. Nhat cuc dau thi dung tai cho; 180s khong them hang se goi doi ve thanh.\'.format(pid, window))\n\n\ndef pickup_timeout_home():\n    count = transport_goods(alive_transport() or {})\n    set_loop(False)\n    stop_owned()\n    say(\'180s khong nhat them hang (hien co {}). Dung lap, goi Bao tieu va ve thanh dung im.\'.format(count))\n    send_team(\'GUARDHOME\')\n    execute(\'RETURN\')\n\n\ndef recovery_pickup_g_tick(pet):\n    context = recovery\n    if context.get(\'g_mode\') == \'background\' and time.monotonic() >= context.get(\'next_auto_focus\', 0):\n        context[\'next_auto_focus\'] = time.monotonic()+2\n        context[\'focus_ready\'] = focus_pickup_client()\n        if not context[\'focus_ready\'] and time.monotonic()-context.get(\'last_focus_warning\', float(\'-inf\')) >= 10:\n            context[\'last_focus_warning\'] = time.monotonic()\n            say(\'Dang tu hien/chon client, Windows chua cho len truoc. G nen van gui dung client; se tu thu lai, khong gui phim that vao cua so khac.\')\n    if context.get(\'key_error\'):\n        recovery_failed(\'Khong gui duoc G: \' + context[\'key_error\'])\n        return\n    if not pet.get(\'mounted\'):\n        recovery_failed(\'Da xuong thu trong luc nhat G\')\n        return\n    if pickup_client_info() != (context[\'pickup_pid\'], context[\'pickup_window\']):\n        recovery_failed(\'Client/PID thay doi trong luc nhat G\')\n        return\n    current = snapshot_position(bot.get_character_data() or {})\n    drop = context[\'search_center\']\n    if not current or current[\'region\'] != drop[\'region\']:\n        recovery_failed(\'Khac khu voi diem roi hang; khong the tu di ve\')\n        return\n    now = time.monotonic()\n    count = transport_goods(pet)\n    previous = context.get(\'last_goods\', 0)\n    distance = math.hypot(current[\'x\']-drop[\'x\'], current[\'y\']-drop[\'y\'])\n    if count > previous:\n        context[\'deadline\'] = now+180  # 180 seconds of NO new cargo, not a total-pickup limit\n        if distance <= 35:\n            if context.get(\'search_move_sent\'):\n                # Cancel only our search walk; do not issue a new movement packet\n                # that could interrupt the game\'s own pickup action.\n                stop_at_current_position()\n                context[\'search_move_sent\'] = False\n            context[\'cluster_locked\'] = True\n            context[\'returning_to_drop\'] = False\n        say(\'Da thay cum hang, {} -> {}: TIEP TUC NHAN G de gom cac cuc gan do, khong dung nhat/khong doi moc.\'.format(previous, count))\n    context[\'last_goods\'] = count\n    worker_ok = (pickup_key_runtime and pickup_key_runtime.get(\'context\') is context and pickup_key_runtime[\'thread\'].is_alive())\n    if not worker_ok and not context.get(\'key_error\') and now < context[\'deadline\']:\n        start_pickup_keys(context)\n    if distance > 35:\n        context[\'cluster_locked\'] = False\n        if not context[\'returning_to_drop\']:\n            say(\'Ra ngoai 35m quanh diem roi; tu quay ve diem roi va van G, khong tam dung thu hoi.\')\n        context[\'returning_to_drop\'] = True\n        if now-context[\'last_search_move\'] >= 1:\n            bot.move_to(drop[\'x\'], drop[\'y\'], drop[\'z\'])\n            context[\'last_search_move\'] = now\n            context[\'search_move_sent\'] = True\n        set_state(\'Quay ve diem roi ({:.1f}m), van G\'.format(distance))\n        return\n    items = pet.get(\'items\')\n    full = isinstance(items, list) and bool(items) and all(item is not None for item in items)\n    if context[\'goods\'] > 0 and count >= context[\'goods\']:\n        complete_recovery()\n        return\n    if context[\'goods\'] <= 0 and full and count > 0:\n        complete_recovery(full=True)\n        return\n    if full:\n        stop_at_current_position()\n        set_state(\'Thu day nhung chua du hang - G/cho xu ly, het 180s se ve thanh\')\n        return\n    if context[\'returning_to_drop\']:\n        if distance > 3:\n            if now-context[\'last_search_move\'] >= 1:\n                bot.move_to(drop[\'x\'], drop[\'y\'], drop[\'z\'])\n                context[\'last_search_move\'] = now\n                context[\'search_move_sent\'] = True\n            return\n        context[\'returning_to_drop\'] = False\n        context[\'cluster_locked\'] = count > 0\n        stop_at_current_position()\n        context[\'search_move_sent\'] = False\n    if context[\'cluster_locked\'] or now < context[\'initial_until\']:\n        set_state(\'Dang gom cum bang G {}: {}/{} | that {}\'.format(context.get(\'g_mode\', \'?\'), count, context[\'goods\'] or \'?\', context.get(\'g_real_count\', 0)))\n        return\n    points = context[\'approach_points\']\n    index = context[\'approach_index\']\n    # Near/passed a script point is enough; G never waits for an exact coordinate.\n    while index < len(points):\n        target = points[index]\n        close = math.hypot(current[\'x\']-target[0], current[\'y\']-target[1]) <= 3\n        passed = False\n        if index > 0:\n            start = points[index-1]\n            dx, dy = target[0]-start[0], target[1]-start[1]\n            length2 = dx*dx+dy*dy\n            if length2:\n                projection = ((current[\'x\']-start[0])*dx+(current[\'y\']-start[1])*dy)/length2\n                cross = abs((current[\'x\']-start[0])*dy-(current[\'y\']-start[1])*dx)/math.sqrt(length2)\n                passed = projection >= 1 and cross <= 5\n        if not close and not passed:\n            break\n        index += 1\n    context[\'approach_index\'] = index\n    if index >= len(points):\n        if context.get(\'search_move_sent\'):\n            stop_at_current_position()\n            context[\'search_move_sent\'] = False\n        set_state(\'Da gan diem roi - G {} | that {} / tong {}\'.format(context.get(\'g_mode\', \'?\'), context.get(\'g_real_count\', 0), context[\'g_count\']))\n        return\n    if now-context[\'last_search_move\'] >= 1:\n        target = points[index]\n        bot.move_to(*target)\n        context[\'last_search_move\'] = now\n        context[\'search_move_sent\'] = True\n    set_state(\'Di ve diem roi va G lien tuc: {}/{}\'.format(count, context[\'goods\'] or \'?\'))\n\n\ndef complete_recovery(manual=False, full=False):\n    global recovery\n    context = recovery or ((trip or {}).get(\'recovery_pending\'))\n    if not context:\n        say(\'Khong co su co thu chet dang cho xu ly.\')\n        return\n    if not manual:\n        if context.get(\'search_center\'):\n            if not pickup_search_position_allowed(context):\n                raise ValueError(\'Can o trong 35m quanh diem dich chuyen de tiep tuc tu dong\')\n        elif not recovery_near_origin(context):\n            raise ValueError(\'Can quay lai gan vi tri hang roi (<=35m, cung khu) de tiep tuc tu dong\')\n    pet = alive_transport()\n    if not pet or (not manual and not pet.get(\'mounted\')):\n        raise ValueError(\'Can thu van tai moi con song\' + (\'\' if manual else \' va da len thu\'))\n    count = transport_goods(pet)\n    if not manual:\n        if context.get(\'goods\', 0) > 0 and count < context[\'goods\']:\n            return\n        if context.get(\'goods\', 0) <= 0 and not (full and count > 0):\n            return\n    if manual and count <= 0:\n        raise ValueError(\'Thu moi chua co hang, chua the tiep tuc\')\n    cancel_recovery(restore=True)\n    if trip:\n        if manual:\n            trip[\'last_manual_recovery\'] = {\'goods\': count, \'position\': snapshot_position(bot.get_character_data() or {}), \'old_drop\': context.get(\'drop_position\') or context.get(\'position\')}\n        trip.pop(\'recovery_pending\', None)\n        persist_trip()\n    say(\'Da thu hoi {} hang{}; tiep tuc moc tuyen, khong mua lai.\'.format(count, \' (xac nhan thu cong)\' if manual else (\' (tui thu day)\' if full else \'\')))\n    if trip and trip.get(\'uncertain\') is not None:\n        set_state(\'Da thu hoi; chon Buoc sau khoi lenh dang do roi GO\')\n        return\n    if manual:\n        say(\'GO thu cong: da nhan hang tren thu, huy thu hoi cu. Bo chan vi tri diem roi/35m/30m va khoang cach vao tuyen cho lan tiep tuc nay.\')\n    run_go(manual_recovery=manual)\n\n\ndef confirm_recovered():\n    load_identity()\n    if not config or config[\'hunter\']:\n        say(\'Nut nay chi danh cho acc buon.\')\n        return\n    try:\n        if not trip:\n            prepare_trip()\n        complete_recovery(manual=True)\n    except Exception as error:\n        say(\'Chua tiep tuc: \' + str(error))\n\n\ndef start_transport_spawn(context, fallback=False):\n    pet = alive_transport()\n    script = \'mount,transport\\n\' if pet else \'oldtrade,spawn\\nmount,transport\\n\'\n    if fallback:\n        context[\'stage\'] = \'fallback_spawn\'\n        say(\'Da toi diem roi hang bang chay bo; thu goi/len thu tai day, khong lap dich chuyen nua.\')\n    else:\n        context[\'spawn_tries\'] = context.get(\'spawn_tries\', 0)+1\n        context[\'stage\'] = \'spawn\'\n        say(\'Thu goi/len thu sau dich chuyen: luot {}/3.\'.format(context[\'spawn_tries\']))\n    context[\'deadline\'] = time.monotonic()+45\n    if trip and trip.get(\'recovery_pending\'):\n        trip[\'recovery_pending\'][\'spawn_tries\'] = context.get(\'spawn_tries\', 0)\n        persist_trip()\n    if bot.start_script(script) is False:\n        retry_spawn_or_walk(context, \'phBot tu choi lenh goi/len thu\')\n\n\ndef start_walk_to_drop(context):\n    target = snapshot_position(context.get(\'drop_position\') or context[\'position\'])\n    current = snapshot_position(bot.get_character_data() or {})\n    if not target or not current or target[\'region\'] != current[\'region\']:\n        recovery_failed(\'Khong the chay bo toi diem roi: thieu toa do hoac khac khu\')\n        return\n    context.update(stage=\'walk_drop\', walk_target=target, deadline=time.monotonic()+180,\n                   last_walk=float(\'-inf\'), search_move_sent=True)\n    say(\'Da thu 3 luot van chua len thu; chay bo toi toa do roi {}. Chi di toi diem da luu, khong tim tu do.\'.format(target))\n    set_state(\'Chay bo ve diem roi hang de goi thu\')\n\n\ndef retry_spawn_or_walk(context, reason):\n    bot.stop_script()\n    if context.get(\'stage\') == \'fallback_spawn\':\n        recovery_failed(\'Da thu 3 luot dich chuyen va goi tai diem roi van that bai: \' + reason)\n        return\n    if context.get(\'spawn_tries\', 0) >= 3:\n        start_walk_to_drop(context)\n    else:\n        context.update(stage=\'retry_return_ready\', retry_at=time.monotonic()+2,\n                       deadline=time.monotonic()+20)\n        say(\'Goi/len thu that bai ({}); se ve thanh va Reverse thu luot {}/3.\'.format(reason, context.get(\'spawn_tries\', 0)+1))\n        set_state(\'Cho 2s de ve thanh/Reverse thu lai goi thu\')\n\n\ndef recovery_tick():\n    if recovery and not transport_feature_allowed():\n        recovery_failed(\'Da bo tich xu ly thu chet\')\n        return\n    if not recovery:\n        return\n    context = recovery\n    c = bot.get_character_data() or {}\n    if context[\'owner\'] != identity or not c or c.get(\'dead\') or not bot.get_party():\n        recovery_failed(\'Nhan vat/Party thay doi hoac nhan vat chet\')\n        return\n    if context[\'stage\'] in (\'spawn\', \'fallback_spawn\'):\n        pet = alive_transport()\n        if pet and pet.get(\'mounted\'):\n            bot.stop_script()\n            start_recovery_pickup()\n            return\n    if context[\'stage\'] == \'pickup\':\n        current_pet = alive_transport()\n        if current_pet and transport_goods(current_pet) > context.get(\'last_goods\', 0):\n            context[\'deadline\'] = time.monotonic()+180\n    if time.monotonic() > context[\'deadline\']:\n        if context[\'stage\'] in (\'spawn\', \'fallback_spawn\'):\n            retry_spawn_or_walk(context, \'qua 45s chua goi/len duoc thu\')\n        elif context[\'stage\'] == \'pickup\':\n            pickup_timeout_home()\n        else:\n            recovery_failed(\'Qua thoi gian cho \' + context[\'stage\'])\n        return\n    if context[\'stage\'] == \'retry_return_ready\':\n        if time.monotonic() < context[\'retry_at\']:\n            return\n        context[\'stage\'], context[\'deadline\'] = \'return\', time.monotonic()+90\n        if not bot.use_return_scroll():\n            recovery_failed(\'Khong dung duoc Return Scroll cho luot thu lai\')\n        else:\n            say(\'Da dung Return cho luot thu lai; doi ve thanh roi Reverse.\')\n    elif context[\'stage\'] == \'reverse_ready\':\n        remaining = max(0, int(math.ceil(context.get(\'reverse_at\', 0)-time.monotonic())))\n        if remaining:\n            if context.get(\'last_wait_remaining\') != remaining:\n                context[\'last_wait_remaining\'] = remaining\n                set_state(\'Da ve thanh - cho {}s truoc Reverse\'.format(remaining))\n            return\n        # Delayed to event_loop after the town spawn callback has completed.\n        context[\'stage\'], context[\'deadline\'] = \'reverse\', time.monotonic()+90\n        if not bot.reverse_return(0, \'\'):\n            recovery_failed(\'Thieu/khong dung duoc cuon Dich chuyen nguoc\')\n        else:\n            set_state(\'Dang dich chuyen nguoc ve diem hang roi\')\n    elif context[\'stage\'] == \'spawn_ready\':\n        if not recovery_near_origin(context):\n            recovery_failed(\'Dich chuyen nguoc khong ve dung diem hang roi\')\n            return\n        context[\'search_center\'] = snapshot_position(bot.get_character_data() or {})\n        if not context[\'search_center\']:\n            recovery_failed(\'Khong ghi duoc toa do sau dich chuyen\')\n            return\n        start_transport_spawn(context)\n    elif context[\'stage\'] in (\'spawn\', \'fallback_spawn\'):\n        pass  # mounted state was checked before the timeout branch\n    elif context[\'stage\'] == \'walk_drop\':\n        target = context[\'walk_target\']\n        current = snapshot_position(c)\n        if not current or current[\'region\'] != target[\'region\']:\n            recovery_failed(\'Da doi khu trong luc chay bo tim diem roi\')\n            return\n        if math.hypot(current[\'x\']-target[\'x\'], current[\'y\']-target[\'y\']) <= 2:\n            stop_at_current_position()\n            # Directed fallback travel may leave the old 35m search circle. Search is\n            # bounded again around the saved cargo location once the walk is complete.\n            context[\'search_center\'] = current\n            start_transport_spawn(context, fallback=True)\n        elif time.monotonic()-context[\'last_walk\'] >= 2:\n            bot.move_to(target[\'x\'], target[\'y\'], target[\'z\'])\n            context[\'last_walk\'] = time.monotonic()\n    elif context[\'stage\'] == \'pickup\':\n        pet = alive_transport()\n        if not pet:\n            recovery_failed(\'Thu van tai moi khong con song\')\n            return\n        recovery_pickup_g_tick(pet)\n\n\ndef handle_event(t, data):\n    # EVENT_TRANSPORT_DIED=3 also covers horses; only act on our tracked transport.\n    load_identity()\n    if t != 3:\n        return\n    try:\n        transport_died(int(data))\n    except Exception as error:\n        recovery_failed(str(error))\n\n\ndef selected_escort_radius():\n    for radius, widget in ((20, escort_20_check), (30, escort_30_check), (50, escort_50_check)):\n        if QtBind.isChecked(gui, widget):\n            return radius\n    return 0\n\n\ndef select_escort_radius(radius, checked):\n    global escort_ui_updating, escort_state, merchant_step\n    if escort_ui_updating:\n        return\n    escort_monitor.clear()\n    escort_ui_updating = True\n    try:\n        if checked:\n            for value, widget in ((20, escort_20_check), (30, escort_30_check), (50, escort_50_check)):\n                QtBind.setChecked(gui, widget, value == radius)\n        if escort_state:\n            stop_at_current_position()\n            escort_state, merchant_step = None, None\n        restore_escort_combat()\n    finally:\n        escort_ui_updating = False\n    selected = selected_escort_radius()\n    say(\'Pham vi Bao tieu: {}m\'.format(selected) if selected else \'Khong ap pham vi Bao tieu; tra ve training area mac dinh da luu cua phBot.\')\n\n\ndef escort_20_changed(checked):\n    select_escort_radius(20, checked)\n\n\ndef escort_30_changed(checked):\n    select_escort_radius(30, checked)\n\n\ndef escort_50_changed(checked):\n    select_escort_radius(50, checked)\n\n\ndef stop_at_current_position():\n    current = snapshot_position(bot.get_character_data() or {})\n    if current:\n        bot.move_to(current[\'x\'], current[\'y\'], current[\'z\'])\n\n\ndef escort_gate():\n    global escort_state, merchant_step\n    radius = selected_escort_radius()\n    if not radius or not config or config[\'hunter\'] or recovery:\n        return True\n    if merchant_step and not merchant_step.get(\'direct\'):\n        escort_monitor[\'miss_since\'] = None\n        return True\n    configured = QtBind.text(gui, follow_box).strip() or config.get(\'guards\', \'\')\n    candidates = [name.strip() for name in configured.split(\',\') if name.strip()]\n    candidates = [name for name in candidates if convoy_name(name) not in trade_followers]\n    hunters = [name for name in candidates if convoy_name(name) in party_hunters]\n    if len(candidates) > 1 and not hunters:\n        if merchant_step:\n            stop_at_current_position()\n            merchant_step = None\n        set_state(\'Cho xac nhan vai tro Bao tieu\')\n        say_throttled(\'escort_role\', \'Chua xac dinh Bao tieu; kiem tra vai tro va cung ban plugin.\', 30)\n        return False\n    guard = next(iter(hunters or candidates), \'\')\n    key = (identity, norm(guard), radius)\n    now = time.monotonic()\n    if escort_monitor.get(\'key\') != key:\n        escort_monitor.clear()\n        escort_monitor.update(key=key, sampled=float(\'-inf\'), result=False,\n                              ever_seen=False, miss_since=None)\n    # merchant_tick may check a gate twice while advancing one waypoint. Reuse one sample.\n    if now-escort_monitor[\'sampled\'] < 0.45:\n        return escort_monitor[\'result\']\n    result = escort_sample(radius, guard, now)\n    escort_monitor[\'sampled\'], escort_monitor[\'result\'] = now, result\n    return result\n\n\nESCORT_SEARCH_STEPS = 10\nESCORT_SEARCH_RADIUS = 60\nESCORT_STEP_STALL_SECONDS = 15\n\n\ndef finish_escort_search(guard, checked, reason):\n    # Stop locally before sending the one-shot Party command. The trip cursor\n    # stays at the original forward waypoint.\n    stop_owned()\n    set_state(\'Tam dung tim Bao tieu - {} moc da kiem tra\'.format(checked))\n    if checked < ESCORT_SEARCH_STEPS:\n        say(\'Tim Bao tieu {}: {}; da toi {}/{} moc. Chua gui VE.\'.format(\n            guard, reason, checked, ESCORT_SEARCH_STEPS))\n        return False\n    say(\'Bao tieu {}: da kiem tra {}/{} moc trong ban kinh {}m, khong thay; danh dau ket.\'.format(\n        guard, checked, ESCORT_SEARCH_STEPS, ESCORT_SEARCH_RADIUS))\n    if not bot.get_party() or not (own_names() & come_get_leaders()):\n        say(\'Chua gui VE: can o Party va acc nay phai la Leader VE da luu.\')\n        return False\n    if not control_party(\'VE\'):\n        say(\'Khong gui duoc VE Party. Leader dang dung tai moc cu.\')\n        return False\n    say(\'Da gui VE Party sau {} moc. Acc buon con hang giu nguyen quy tac bao ve hang.\'.format(checked))\n    # Own chat can be absent on some phBot builds. Use the same authorization\n    # and cargo checks as an incoming VE, with the existing return cooldown.\n    name = (bot.get_character_data() or {}).get(\'name\')\n    if name and not return_request and time.monotonic() - last_return >= 30:\n        come_handle_chat(4, name, \'VE\')\n    return False\n\n\ndef escort_backtrack_points(current):\n    # Count actual script waypoints, newest first, without crossing a ferry\n    # or replaying an oldtrade command.\n    if not trip:\n        return []\n    points = []\n    previous = current\n    cursor = min(trip[\'cursor\'], len(trip_lines))\n    for index in range(cursor - 1, -1, -1):\n        waypoint = walk_point(trip_lines[index])\n        if waypoint is None:\n            break\n        x, y, z = waypoint\n        if math.hypot(previous[\'x\'] - x, previous[\'y\'] - y) <= 2:\n            continue\n        point = {\'x\': x, \'y\': y, \'z\': z, \'step\': index + 1}\n        points.append(point)\n        previous = point\n        if len(points) == ESCORT_SEARCH_STEPS:\n            break\n    return points\n\n\ndef visible_escort_member(member, current):\n    """Party establishes identity; only a locally spawned player establishes proximity."""\n    if not member or member.get(\'dead\') or member.get(\'hp_percent\') == 0:\n        return None\n    uid = member.get(\'player_id\')\n    if not uid:\n        return None\n    players = getattr(bot, \'get_players\', lambda: {})() or {}\n    visible = players.get(uid) or players.get(str(uid))\n    if not isinstance(visible, dict) or visible.get(\'dead\') or visible.get(\'hp_percent\') == 0:\n        return None\n    # Reject UID reuse when the local player record supplies a different name.\n    expected = {norm(member.get(\'name\')), norm(member.get(\'job_name\'))} - {\'\'}\n    actual = {norm(visible.get(\'name\')), norm(visible.get(\'job_name\'))} - {\'\'}\n    if expected and actual and not expected.intersection(actual):\n        return None\n    position = snapshot_position(visible, current)\n    if not position:\n        return None\n    if position[\'region\'] != current[\'region\'] and not nearby_outdoor_position(current, position, 120):\n        return None\n    return dict(visible, **position, player_id=uid)\n\n\ndef escort_sample(radius, guard, now):\n    global escort_state, merchant_step\n    current = snapshot_position(bot.get_character_data() or {})\n    if not current:\n        return False\n    party_member = resolve_follow_target(guard) if guard else None\n    member = visible_escort_member(party_member, current)\n    distance = float(\'inf\')\n    reason = (\'khong tim thay ten trong Party\' if not party_member else\n              \'chua thay UID Bao tieu trong danh sach nguoi xung quanh\')\n    if member:\n        distance = math.hypot(member[\'x\'] - current[\'x\'], member[\'y\'] - current[\'y\'])\n        reason = \'ngoai ban kinh ({:.1f}m, UID hien quanh Leader)\'.format(distance)\n\n    # Once reacquired at 60m, allow the escort to close the gap during\n    # resumption. Restore the configured radius as soon as they are inside it.\n    if distance <= radius:\n        escort_monitor.pop(\'rejoining\', None)\n    found_radius = ESCORT_SEARCH_RADIUS if escort_state or escort_monitor.get(\'rejoining\') else radius\n    if distance <= found_radius:\n        escort_monitor[\'miss_since\'] = None\n        if escort_state:\n            if escort_state.get(\'found_uid\') != member[\'player_id\']:\n                escort_state[\'found_since\'] = None\n                escort_state[\'found_uid\'] = member[\'player_id\']\n            if escort_state[\'found_since\'] is None:\n                escort_state[\'found_since\'] = now\n                stop_at_current_position()\n            if now - escort_state[\'found_since\'] < 2:\n                set_state(\'Dang xac nhan Bao tieu on dinh trong {}m\'.format(found_radius))\n                return False\n            escort_state, merchant_step = None, None\n            if distance > radius:\n                escort_monitor[\'rejoining\'] = True\n            say(\'Da thay Bao tieu {} UID={} trong {:.1f}m lien tuc 2s; tiep tuc dung moc cu.\'.format(\n                guard, member[\'player_id\'], distance))\n        return True\n\n    if escort_monitor.get(\'miss_since\') is None:\n        escort_monitor[\'miss_since\'] = now\n    missing = now - escort_monitor[\'miss_since\']\n    if not escort_state and missing < 30:\n        if merchant_step:\n            stop_at_current_position()\n            merchant_step = None\n        set_state(\'Cho Bao tieu trong {}m: {}/30s\'.format(found_radius, int(missing)))\n        return False\n    if not escort_state:\n        points = escort_backtrack_points(current)\n        stop_at_current_position()\n        merchant_step = None\n        escort_state = {\'points\': points, \'index\': 0, \'last_move\': float(\'-inf\'),\n                        \'move_after\': now + 0.5, \'progress_at\': now + 0.5,\n                        \'best_distance\': None, \'found_since\': None, \'finish_at\': None}\n        say(\'Bao tieu {} mat/xa ngoai {}m lien tuc 30s ({}): quay lai toi da {} moc, tim trong {}m.\'.format(\n            guard or \'(chua nhap ten)\', found_radius, reason, ESCORT_SEARCH_STEPS, ESCORT_SEARCH_RADIUS))\n\n    context = escort_state\n    if context[\'found_since\'] is not None:\n        context[\'found_since\'] = None\n        context[\'progress_at\'] = now\n    points = context[\'points\']\n    if context[\'index\'] < len(points):\n        target = points[context[\'index\']]\n        remaining = math.hypot(current[\'x\'] - target[\'x\'], current[\'y\'] - target[\'y\'])\n        if remaining <= 2:\n            context[\'index\'] += 1\n            context[\'best_distance\'] = None\n            context[\'progress_at\'] = now\n            context[\'last_move\'] = float(\'-inf\')\n            say(\'Tim Bao tieu {}: da toi moc {}/{} (buoc tuyen {}).\'.format(\n                guard, context[\'index\'], ESCORT_SEARCH_STEPS, target[\'step\']))\n            return False\n        best = context[\'best_distance\']\n        if best is None or best - remaining >= 1:\n            context[\'best_distance\'] = remaining\n            context[\'progress_at\'] = now\n        if now - context[\'progress_at\'] >= ESCORT_STEP_STALL_SECONDS:\n            return finish_escort_search(guard, context[\'index\'],\n                                        \'khong tien duoc toi moc ke tiep\')\n        if now >= context[\'move_after\'] and now - context[\'last_move\'] >= 2:\n            result = bot.move_to(target[\'x\'], target[\'y\'], target[\'z\'])\n            context[\'last_move\'] = now\n            if result is False:\n                say_throttled(\'escort_move_rejected\',\n                              \'phBot tu choi quay lai buoc tuyen {}; se thu lai.\'.format(target[\'step\']), 5)\n        set_state(\'Tim {}: moc {}/{}, ban kinh {}m\'.format(\n            guard, context[\'index\'] + 1, ESCORT_SEARCH_STEPS, ESCORT_SEARCH_RADIUS))\n        return False\n\n    if context[\'finish_at\'] is None:\n        stop_at_current_position()\n        context[\'finish_at\'] = now + 2\n    if now < context[\'finish_at\']:\n        return False\n    return finish_escort_search(guard, context[\'index\'], \'het moc lien tuc tren cung doan tuyen\')\n\n\ndef restore_escort_combat():\n    global combat_area_backup, last_combat_anchor\n    area, combat_area_backup = combat_area_backup, None\n    last_combat_anchor = float(\'-inf\')\n    if area:\n        bot.set_training_position(area[\'region\'], area[\'x\'], area[\'y\'], area.get(\'z\', 0))\n        bot.set_training_radius(area[\'radius\'])\n\n\ndef update_escort_combat():\n    global combat_area_backup, last_combat_anchor\n    if not active or not config or not config[\'hunter\'] or not selected_escort_radius():\n        return\n    now = time.monotonic()\n    if now-last_combat_anchor < 2:\n        return\n    last_combat_anchor = now\n    member = resolve_follow_target(current_follow_target())\n    current = snapshot_position(bot.get_character_data() or {})\n    if not member or not current or not member.get(\'player_id\'):\n        return\n    target = snapshot_position(member, current)\n    if not target or target[\'region\'] != current[\'region\']:\n        return\n    getter = getattr(bot, \'get_training_area\', None)\n    area = getter() if getter else None\n    if not area or not all(k in area for k in (\'region\', \'x\', \'y\', \'radius\')):\n        return\n    if combat_area_backup is None:\n        combat_area_backup = dict(area)\n    bot.set_training_position(target[\'region\'], target[\'x\'], target[\'y\'], target.get(\'z\', 0))\n    bot.set_training_radius(selected_escort_radius())\n\n\ndef set_loop(enabled):\n    global loop_enabled, loop_pending, loop_return\n    loop_enabled = bool(enabled) and loop_controls_allowed()\n    if not loop_enabled:\n        loop_pending, loop_return = None, None\n    readable_set_text(gui, loop_label, \'Lap: \' + (\'BAT\' if loop_enabled else \'TAT\'))\n    sync_loop_checks()\n\n\ndef loop_tick():\n    global loop_pending\n    if loop_enabled and not loop_controls_allowed():\n        set_loop(False)\n        return\n    if not loop_enabled or not loop_pending or recovery:\n        return\n    context = loop_pending\n    if context[\'owner\'] != identity:\n        set_loop(False)\n        return\n    now = time.monotonic()\n    if now < context[\'at\']:\n        return\n    c = bot.get_character_data() or {}\n    if not c or c.get(\'dead\') or not bot.get_party():\n        set_loop(False)\n        say(\'Tat lap: nhan vat offline/chet/khong con Party.\')\n        return\n    if active:\n        loop_pending = None\n        return\n    if context[\'kind\'] == \'merchant\':\n        loop_pending = None\n        try:\n            # Only a confirmed completed return resets the route for a fresh purchase.\n            if not trip or trip.get(\'finish_stage\') != \'done\' or trip.get(\'recovery_pending\'):\n                raise ValueError(\'Chua xac nhan ket thuc chuyen cu/thu hoi hang\')\n            reset_trip()\n            say(\'Lap chuyen: da ve thanh, di den diem mua hang va chay lai script.\')\n            run_go()\n            if not active:\n                raise ValueError(\'Chua khoi chay duoc chuyen moi\')\n        except Exception as error:\n            set_loop(False)\n            say(\'Dung lap: \' + str(error))\n    else:\n        if now > context[\'deadline\']:\n            set_loop(False)\n            say(\'Bao tieu: qua 60s chua bam lai duoc, can bat lai.\')\n            return\n        if now-last_go < 15:\n            context[\'at\'] = last_go+15\n            return\n        try:\n            run_go()\n            if active:\n                loop_pending = None\n                say(\'Lap chuyen: Bao tieu da bam lai acc buon.\')\n            else:\n                context[\'at\'] = now+5\n        except Exception as error:\n            context[\'at\'] = now+5\n            say(\'Bao tieu cho bam lai: \' + str(error))\n\n\ndef schedule_loop_after_return():\n    global loop_return, loop_pending\n    if not loop_enabled or not loop_return or loop_return[\'owner\'] != identity or recovery:\n        return\n    origin = loop_return[\'origin\']\n    c = bot.get_character_data() or {}\n    moved = c.get(\'region\') != origin.get(\'region\')\n    if not moved:\n        try:\n            moved = math.hypot(c[\'x\']-origin[\'x\'], c[\'y\']-origin[\'y\']) > 30\n        except (KeyError, TypeError):\n            moved = False\n    if not moved:\n        return\n    if not config[\'hunter\'] and (not trip or trip.get(\'finish_stage\') != \'done\'):\n        return\n    now = time.monotonic()\n    loop_pending = {\'kind\': \'hunter\' if config[\'hunter\'] else \'merchant\',\n                    \'owner\': identity, \'at\': now+2, \'deadline\': now+60}\n    loop_return = None\n    set_state(\'Lap BAT: da ve thanh, cho 2s de chay tiep\')\n\n\nrecent_party_control = {}\n\n\ndef control_party(message):\n    # Suppress duplicate callbacks only, not distinct commands or scheduled retries.\n    if not message.startswith((\'!CR1 \', \'!CR2 \', \'!CRB \', \'!CRF \', \'!CRSTOP \', \'!CRW \')):\n        return phBotChat.Party(message)\n    now = time.monotonic()\n    for key, sent_at in list(recent_party_control.items()):\n        if now-sent_at >= 1:\n            recent_party_control.pop(key, None)\n    key = (identity, message)\n    if key in recent_party_control:\n        return True\n    sent = phBotChat.Party(message)\n    if sent:\n        recent_party_control[key] = now\n    return sent\n\n\ndef handle_joymax(opcode, data):\n    global selected_npc, last_trade_shop\n    if opcode == 0xB046 and data[:1] == b\'\\x01\':\n        uid = npc_session.get(\'uid\') if npc_session.get(\'state\') == \'opening\' else (selected_npc or last_trade_shop or owned_native_npc())\n        npc_session.update(owner=identity, uid=uid, state=\'open\', closed_at=None,\n                           generation=npc_session[\'generation\']+1)\n    if opcode == 0xB04B:\n        if data[:1] == b\'\\x01\':\n            uid = trade_npc_close[\'uid\'] if trade_npc_close else npc_session.get(\'uid\') or last_trade_shop or selected_npc or owned_native_npc()\n            npc_session.update(owner=identity, uid=uid, state=\'closed\', closed_at=time.monotonic())\n            if trade_npc_close is not None:\n                trade_npc_close[\'ack\'] = True\n            selected_npc = None\n            last_trade_shop = None\n        elif trade_npc_close is not None:\n            trade_npc_close[\'rejected\'] = bytes(data).hex(\' \')\n    # Do not suppress the server packet: phBot must dispatch Party fallback commands.\n    # Selection acknowledgement includes the selected entity UID after success.\n    if opcode == 0xB045 and len(data) >= 5 and data[0] == 1:\n        uid = struct.unpack_from(\'<I\', data, 1)[0]\n        npcs = getattr(bot, \'get_npcs\', lambda: {})() or {}\n        if uid in npcs or uid==owned_native_npc():\n            selected_npc = uid\n    return True\n\n\ndef handle_silkroad(opcode, data):\n    global selected_npc, last_trade_shop\n    if opcode == 0x7046 and len(data) >= 4:\n        npc_session.update(owner=identity, uid=struct.unpack_from(\'<I\',data)[0],\n                           state=\'opening\', closed_at=None, generation=npc_session[\'generation\']+1)\n        if trade_npc_close is not None:\n            trade_npc_close[\'reopened\'] = True\n    if opcode in (0x7045, 0x7046) and len(data) >= 4:\n        uid = struct.unpack_from(\'<I\', data)[0]\n        if uid in (getattr(bot, \'get_npcs\', lambda: {})() or {}):\n            selected_npc = uid\n    if opcode==0x7046 and len(data)>=5 and data[4]==0x0C:\n        last_trade_shop=struct.unpack_from(\'<I\',data)[0]\n    return True\n\n\ndef bind_native_trade(context):\n    global native_trade_context\n    character=bot.get_character_data() or {}\n    uid=context.get(\'chat_npc_uid\')\n    npcs=getattr(bot,\'get_npcs\',lambda:{})() or {}\n    npc=npcs.get(uid) or npcs.get(str(uid)) if uid else None\n    if uid and npc and npc.get(\'region\',character.get(\'region\'))==character.get(\'region\'):\n        try:\n            if math.hypot(float(npc[\'x\'])-float(character[\'x\']),float(npc[\'y\'])-float(character[\'y\']))<=TRADE_NPC_APPROACH_RADIUS:\n                context[\'native_npc_uid\']=int(uid)\n        except (KeyError,ValueError,TypeError):pass\n    context[\'native_owner\']=identity\n    context[\'native_region\']=character.get(\'region\')\n    native_trade_context=context\n\n\ndef owned_native_npc():\n    context=native_trade_context\n    if not context or context.get(\'native_owner\')!=identity:return None\n    character=bot.get_character_data() or {}\n    if character.get(\'region\')!=context.get(\'native_region\'):return None\n    uid=context.get(\'native_npc_uid\')\n    return uid if isinstance(uid,int) and 0<uid<2**32 else None\n\n\ndef clear_trade_fault():\n    global trade_fault\n    if trade_fault:\n        trade_fault = None\n        say(\'Da bo giu loi giao dich theo lenh tiep tuc thu cong.\')\n\n\ndef raise_trade_fault(message):\n    global trade_fault, follow_blocked\n    if trade_fault is None:\n        batch = (local_sale or {}).get(\'batch\')\n        trade_fault = {\'owner\': identity, \'reason\': message,\n                       \'notified\': {batch} if batch else set()}\n        follow_blocked = True\n        if \'af_party_state\' in globals():\n            af_party_state[\'paused\'] = True\n        set_loop(False)\n        if batch:\n            try:convoy_wire(batch, \'FAIL\')\n            except Exception:pass\n    raise ValueError(message+\'; giu dung, kiem tra NPC roi bam Tiep tuc. Khong tu theo/SELL lai.\')\n\n\ndef native_trade_idle_complete(context, now):\n    """Native engine idle + verified stable goods, not a fabricated NPC-close ack."""\n    character=bot.get_character_data() or {}\n    if character.get(\'trading\') is not False:\n        context.pop(\'native_idle_since\',None)\n        return False\n    # Never release a different NPC interaction opened after this transaction stopped.\n    if npc_session.get(\'generation\')!=context.get(\'native_stop_generation\'):\n        raise_trade_fault(\'NPC: co phien mo NPC moi sau khi dung giao dich; chua tu bat theo\')\n    selling=context.get(\'stage\')==\'sold\'\n    pet=finish_transport() if selling else alive_transport()\n    if pet is None:\n        context.pop(\'native_idle_since\',None)\n        return False\n    goods=transport_goods(pet)\n    target=int((config or {}).get(\'buy_goods\',280))\n    ready=goods==0 if selling else goods>=target\n    if not ready:\n        context.pop(\'native_idle_since\',None)\n        context.pop(\'native_idle_goods\',None)\n        return False\n    if context.get(\'native_idle_goods\')!=goods or \'native_idle_since\' not in context:\n        context[\'native_idle_goods\']=goods\n        context[\'native_idle_since\']=now\n    if now-context.get(\'native_idle_since\',now)<2:\n        return False\n    context[\'shop_close_done\']=True\n    context[\'shop_completion\']=\'native_idle\'\n    # Retain the distinction: engine-idle is not a server NPC-close acknowledgement.\n    if npc_session.get(\'owner\')==identity:\n        npc_session[\'state\']=\'native_idle\'\n    say(\'NPC: phBot da ngung giao dich, hang on dinh 2s; tiep tuc, khong bat buoc goi dong NPC.\')\n    return True\n\n\ndef ensure_trade_npc_closed(context, now):\n    """Finish confirmed buy/sell only; no movement/ESC/client response fabrication."""\n    global trade_npc_close\n    if trade_fault:\n        raise_trade_fault(\'Giao dich dang tam dung do loi; kiem tra NPC roi bam Tiep tuc thu cong.\')\n    if context.get(\'shop_close_done\'):\n        return True\n    request = context.get(\'shop_close\')\n    if request is None:\n        closed_at = npc_session.get(\'closed_at\')\n        started_at = context.get(\'npc_trade_started_at\')\n        native_closed = (npc_session.get(\'owner\') == identity and npc_session.get(\'state\') == \'closed\'\n                         and closed_at is not None and npc_session.get(\'uid\') is not None\n                         and (closed_at >= started_at if started_at is not None else closed_at <= now))\n        if native_closed:\n            if not context.get(\'native_stopped\'):\n                context[\'native_stopped\']=True\n                bot.stop_script()  # Server already closed the shop; no extra stop_trade.\n            if now-closed_at < 1:\n                return False\n            context[\'shop_close_done\'] = True\n            say(\'NPC: phBot da dong phien va server da xac nhan; khong gui dong lap.\')\n            return True\n        if not context.get(\'native_stopped\'):\n            context[\'native_stopped\']=True\n            context[\'native_stop_at\']=now\n            context[\'native_stop_generation\']=npc_session.get(\'generation\')\n            bot.stop_script()\n            stopper = getattr(bot, \'stop_trade\', None)\n            if callable(stopper): stopper()\n            set_state(\'Da du hang/ban het; cho phBot dong giao dich truoc\')\n            return False\n        if now-context.get(\'native_stop_at\',now)<1:\n            return False\n        if not NPC_PACKET_CLOSE_ENABLED:\n            if native_trade_idle_complete(context,now):\n                return True\n            if now-context.get(\'native_stop_at\',now)<12:\n                set_state(\'Cho phBot ngung giao dich va xac nhan hang on dinh\')\n                return False\n            status=(bot.get_character_data() or {}).get(\'trading\')\n            raise_trade_fault(\'NPC: chua xac minh duoc giao dich da dung va hang da on dinh (trading=\'+repr(status)+\'); khong tu chay tiep\')\n        npcs = getattr(bot, \'get_npcs\', lambda: {})() or {}\n        uid = None\n        for candidate in (npc_session.get(\'uid\') if npc_session.get(\'state\') in (\'open\',\'opening\') else None, last_trade_shop, selected_npc):\n            if candidate is not None and (candidate in npcs or str(candidate) in npcs or (npc_session.get(\'state\')==\'open\' and candidate==owned_native_npc())):\n                uid = int(candidate)\n                break\n        if uid is None:\n            raise_trade_fault(\'Dong NPC: chua biet UID NPC giao dich; da dung, khong tu chon NPC gan nhat.\')\n        request = {\'owner\': identity, \'uid\': uid, \'attempts\': 0,\n                   \'next\': now, \'ack\': False, \'ack_at\': None}\n        context[\'shop_close\'] = request\n        trade_npc_close = request\n    if trade_npc_close is not request or request[\'owner\'] != identity:\n        raise_trade_fault(\'Dong NPC: phien giao dich da thay doi; khong tu di tiep.\')\n    if request.get(\'reopened\'):\n        raise_trade_fault(\'Dong NPC: co yeu cau mo NPC moi trong luc dong; da dung de tranh chong cheo.\')\n    if request.get(\'rejected\'):\n        raise_trade_fault(\'Dong NPC: server da tu choi \'+request[\'rejected\']+\'; khong gui lap lai.\')\n    if request[\'ack\']:\n        if request[\'ack_at\'] is None:\n            request[\'ack_at\'] = now\n            say(\'NPC: server da xac nhan dong UID={}; doi 1 giay truoc khi di tiep.\'.format(request[\'uid\']))\n        if now-request[\'ack_at\'] < 1:\n            return False\n        trade_npc_close = None\n        context[\'shop_close_done\'] = True\n        return True\n    if now >= request[\'next\']:\n        if request[\'attempts\'] >= 3:\n            raise_trade_fault(\'Dong NPC: sau 3 lan van chua co xac nhan server; da dung, kiem tra cua so NPC. Phan hoi=\'+request.get(\'rejected\',\'chua co\'))\n        request[\'attempts\'] += 1\n        request[\'next\'] = now+2\n        if bot.inject_joymax(0x704B, struct.pack(\'<I\', request[\'uid\']), False) is False:\n            raise_trade_fault(\'Dong NPC: phBot tu choi gui yeu cau; da dung.\')\n        if request[\'attempts\'] == 1:\n            say(\'NPC: dang doi server xac nhan dong phien; chua di tiep.\')\n    set_state(\'Cho server xac nhan dong NPC ({}/3)\'.format(request[\'attempts\']))\n    return False\n\n\ndef close_npc_session():\n    """Exit the server-side NPC session, even when its client window is hidden."""\n    global selected_npc\n    if not NPC_PACKET_CLOSE_ENABLED:\n        stopper=getattr(bot,\'stop_trade\',None)\n        if callable(stopper):stopper()\n        return\n    npcs = getattr(bot, \'get_npcs\', lambda: {})() or {}\n    uid = selected_npc if selected_npc in npcs else None\n    if uid is None:\n        c = bot.get_character_data() or {}\n        candidates = []\n        for entity, npc in npcs.items():\n            try:\n                distance = math.hypot(float(npc[\'x\'])-c[\'x\'], float(npc[\'y\'])-c[\'y\'])\n                if distance <= 15 and npc.get(\'region\', c.get(\'region\')) == c.get(\'region\'):\n                    candidates.append((distance, int(entity)))\n            except (KeyError, TypeError, ValueError):\n                continue\n        if candidates:\n            uid = min(candidates)[1]\n    if uid is not None:\n        injector = getattr(bot, \'inject_joymax\', None)\n        if not callable(injector) or injector(0x704B, struct.pack(\'<I\', int(uid)), False) is False:\n            raise ValueError(\'Khong gui duoc lenh dong hoi thoai NPC; chua dung bua\')\n        selected_npc = None\n        say(\'Da gui dong phien NPC UID={}; cho truoc khi dung bua.\'.format(uid))\n\n\ndef queue_return():\n    global return_request\n    clear_trade_fault()\n    if return_request:\n        say_throttled(\'return_pending\',\'Dang doi dong NPC/dung bua ve thanh; khong gui trung.\',10)\n        return\n    if time.monotonic()-last_return < 30:\n        say(\'Return Scroll: cho 30 giay.\')\n        return\n    retained=dict(follow_intent) if follow_intent and not follow_blocked else None\n    stop_owned()\n    globals()[\'follow_intent\']=retained\n    close_npc_session()\n    return_request = {\'owner\': identity, \'due\': time.monotonic()+1, \'attempts\': 0}\n    set_state(\'Dong NPC - cho 1 giay roi dung bua ve thanh\')\n\n\ndef return_tick():\n    global return_request, last_return, loop_return\n    context = return_request\n    if not context:\n        return\n    if context[\'owner\'] != identity or not config:\n        return_request = None\n        return\n    if time.monotonic() < context[\'due\']:\n        return\n    c = bot.get_character_data() or {}\n    if not c or c.get(\'dead\'):\n        return_request = None\n        say(\'Dung ve thanh: nhan vat offline/chet.\')\n        return\n    context[\'attempts\'] += 1\n    if bot.use_return_scroll():\n        return_request = None\n        last_return = time.monotonic()\n        if loop_enabled and not recovery and (config[\'hunter\'] or (trip and trip.get(\'finish_stage\') in (\'return_pending\', \'return_wait\', \'done\'))):\n            loop_return = {\'owner\': identity, \'origin\': dict(c)}\n        if trip and trip.get(\'finish_stage\') in (\'return_pending\', \'return_wait\'):\n            trip[\'finish_stage\'] = \'return_wait\'\n            trip[\'return_origin\'] = {key: c.get(key) for key in (\'region\', \'x\', \'y\')}\n            persist_trip()\n        set_state(\'Da yeu cau ve thanh - cho server xac nhan\')\n    elif context[\'attempts\'] < 3:\n        close_npc_session()\n        context[\'due\'] = time.monotonic()+2\n        say(\'Bua chua duoc chap nhan; dong NPC va thu lai ({}/3).\'.format(context[\'attempts\']))\n    else:\n        return_request = None\n        set_state(\'Khong dung duoc bua sau 3 lan - kiem tra cuon\')\n        say(\'Chua ve thanh. Kiem tra bua/dieu kien server; khong tu mua hang hay lap tuyen.\')\n        if follow_intent and not follow_blocked:\n            pause_trace_for_rejoin(\'bua ve thanh khong thanh cong\')\n\n\ndef refresh_party_list():\n    load_identity()\n    party_rows.clear()\n    QtBind.clear(gui, party_list)\n    party = bot.get_party() or {}\n    members = set()\n    for pid, member in sorted(party.items(), key=lambda item: norm(item[1].get(\'name\'))):\n        name = member.get(\'name\') or member.get(\'job_name\')\n        if not name or norm(name) in own_names():\n            continue\n        label = \'[PT] \' + name\n        party_rows[label] = name\n        members.add(norm(name))\n        QtBind.append(gui, party_list, label)\n    for uid, player in sorted((bot.get_players() or {}).items(), key=lambda item: norm(item[1].get(\'name\'))):\n        name = player.get(\'name\') or player.get(\'job_name\')\n        if not name or norm(name) in own_names() or norm(name) in members:\n            continue\n        label = \'[Gan] \' + name\n        party_rows[label] = name\n        members.add(norm(name))\n        QtBind.append(gui, party_list, label)\n    say(\'Danh sach: {} nhan vat. [PT]=trong nhom; [Gan]=co the moi.\'.format(len(party_rows)))\n\n\ndef selected_party_name():\n    name = party_rows.get(QtBind.text(gui, party_list))\n    if not name:\n        raise ValueError(\'Bam Cap nhat ten va chon mot nhan vat trong danh sach\')\n    if norm(name) in own_names():\n        raise ValueError(\'Khong thuc hien lenh nhom voi chinh minh\')\n    return name\n\n\ndef invite_selected():\n    try:\n        name = selected_party_name()\n        if party_member(name):\n            raise ValueError(name+\' da o trong nhom\')\n        matches = [(uid,p) for uid,p in (bot.get_players() or {}).items()\n                   if norm(name) in {norm(p.get(\'name\')), norm(p.get(\'job_name\'))}]\n        if len(matches) != 1:\n            raise ValueError(\'Nhan vat khong con o gan; bam Cap nhat ten\')\n        uid = int(matches[0][0])\n        # Existing-party invitation uses the nearby world UID.\n        if bot.get_party():\n            opcode, payload = 0x7062, struct.pack(\'<I\', uid)\n        else:\n            # Standard 8-person party: shared EXP and items.\n            opcode, payload = 0x7060, struct.pack(\'<IB\', uid, 7)\n        if bot.inject_joymax(opcode, payload, False) is False:\n            raise ValueError(\'Khong gui duoc loi moi\')\n        say(\'Da gui loi moi nhom cho \'+name+\'. Doi nguoi choi chap nhan/server xac nhan.\')\n    except Exception as error:\n        say(\'Moi nhom: \'+str(error))\n\n\ndef kick_selected():\n    try:\n        name = selected_party_name()\n        matches = [(pid,m) for pid,m in (bot.get_party() or {}).items()\n                   if norm(name) in {norm(m.get(\'name\')), norm(m.get(\'job_name\'))}]\n        if len(matches) != 1:\n            raise ValueError(\'Nhan vat khong con trong nhom; bam Cap nhat ten\')\n        # Kick requires the party member ID (not the nearby world UID).\n        pid = int(matches[0][0])\n        if bot.inject_joymax(0x7063, struct.pack(\'<I\', pid), False) is False:\n            raise ValueError(\'Khong gui duoc lenh kich\')\n        say(\'Da yeu cau kich \'+name+\'. Chi chu Party co quyen; doi server xac nhan.\')\n    except Exception as error:\n        say(\'Kich nhom: \'+str(error))\n\n\ndef handle_follower_wait_chat(player, msg):\n    parts = party_command_parts(msg, \'!CRW\')\n    if not parts or parts[0] != \'!CRW\':\n        return False\n    if len(parts) != 4 or not party_member(player):\n        return True\n    token, action = parts[2:]\n    if len(token)!=16 or any(c not in \'0123456789abcdef\' for c in token):\n        return True\n    if norm(player) in own_names():\n        return True\n    if action == \'QUERY\':\n        if not trusted_leader(player) or not (config[\'hunter\'] or config.get(\'follower\')):\n            return True\n        target = current_follow_target()\n        if target and convoy_name(target) != convoy_name(player):\n            return True\n        role = \'HUNTER\' if config[\'hunter\'] else \'FOLLOWER\'\n        control_party(\'!CRW {} {}\'.format(token, role))\n    elif action in (\'FOLLOWER\', \'HUNTER\') and follower_probe and follower_probe[\'token\']==token and time.monotonic()<=follower_probe[\'deadline\']:\n        name = convoy_name(player)\n        if action == \'HUNTER\':\n            trade_followers.pop(name, None)\n            party_hunters.add(name)\n        else:\n            party_hunters.discard(name)\n            trade_followers[name] = {\'name\': player, \'seen\': time.monotonic()}\n    return True\n\n\ndef resume_waited_walk():\n    set_state(\'Dang tiep tuc moc tuyen\')\n    if merchant_step and merchant_step.get(\'direct\'):\n        # Dispatch the same waypoint immediately after a hold; never advance its cursor.\n        merchant_step[\'last_move\'] = float(\'-inf\')\n\n\ndef probe_party_followers():\n    global follower_probe, last_follower_probe\n    now = time.monotonic()\n    if now - last_follower_probe >= 30 and own_names() & names(config[\'leaders\']):\n        last_follower_probe = now\n        token = uuid.uuid4().hex[:16]\n        follower_probe = {\'token\': token, \'deadline\': now+5}\n        control_party(\'!CRW {} QUERY\'.format(token))\n\n\ndef measured_follower_distance(member, character, visible_players):\n    if not member or member.get(\'dead\') or member.get(\'hp_percent\') == 0:\n        return None\n    visible = visible_players.get(member.get(\'player_id\'))\n    if not visible:\n        aliases = {norm(member.get(\'name\')), norm(member.get(\'job_name\'))} - {\'\'}\n        matches = [player for player in visible_players.values()\n                   if aliases & {norm(player.get(\'name\')), norm(player.get(\'job_name\'))}]\n        visible = matches[0] if len(matches) == 1 else None\n    if visible and position_usable(dict(visible, player_id=1), character):\n        return math.hypot(float(visible[\'x\'])-float(character[\'x\']),\n                          float(visible[\'y\'])-float(character[\'y\']))\n    if position_usable(member, character) or (member.get(\'player_id\') and\n            nearby_outdoor_position(character, member, 20)):\n        return math.hypot(float(member[\'x\'])-float(character[\'x\']),\n                          float(member[\'y\'])-float(character[\'y\']))\n    return None\n\n\ndef follower_distance_gate():\n    global follower_wait\n    if not config or config[\'hunter\'] or config.get(\'follower\') or standalone_follow or recovery or not own_names() & names(config[\'leaders\']):\n        return True\n    now = time.monotonic()\n    if merchant_step and not merchant_step.get(\'direct\'):\n        return True\n    # A waypoint can ask twice in the same event-loop tick: reuse one sample.\n    if now-follower_monitor.get(\'sampled\',float(\'-inf\'))<0.45:\n        return follower_monitor.get(\'result\',True)\n    follower_monitor[\'sampled\']=now\n    entries=follower_monitor.setdefault(\'entries\',{})\n    character=bot.get_character_data() or {}\n    outside=set()\n    visible_players = (getattr(bot, \'get_players\', lambda: {})() or {}) if trade_followers else {}\n    for key,data in list(trade_followers.items()):\n        entry=entries.setdefault(key,{\'outside\':False,\'outside_since\':None,\'inside_since\':None})\n        member=resolve_follow_target(data[\'name\'])\n        distance = measured_follower_distance(member, character, visible_players)\n        near=None\n        entry[\'measurement\'] = distance\n        if distance is not None:\n            entry[\'last_valid\']=now\n            entry[\'distance\']=distance\n            near=distance<=(5 if entry[\'outside\'] or key in follower_bypass else 20)\n            origin=entry.get(\'departure_origin\')\n            if near and origin and character.get(\'region\')==origin[\'region\']:\n                near=math.hypot(float(character[\'x\'])-origin[\'x\'], float(character[\'y\'])-origin[\'y\'])>10\n        elif now-entry.get(\'last_valid\',float(\'-inf\'))>2:\n            near=False  # Treat prolonged missing coordinates as outside, never as arrived.\n        if near is True:\n            entry[\'outside_since\']=None\n            if entry[\'inside_since\'] is None:\n                entry[\'inside_since\']=now\n            if now-entry[\'inside_since\']>=1.5:\n                entry[\'outside\']=False\n            if now-entry[\'inside_since\']>=2:\n                follower_bypass.discard(key)\n                entry.pop(\'departure_origin\',None)\n        elif near is False:\n            entry[\'inside_since\']=None\n            if entry[\'outside_since\'] is None:\n                entry[\'outside_since\']=now\n            if now-entry[\'outside_since\']>=2:\n                entry[\'outside\']=True\n        else:\n            # A transient player_id=0 must not toggle the gate, or count as a stable arrival.\n            entry[\'inside_since\']=None\n            if not entry[\'outside\']:\n                entry[\'outside_since\']=None\n        tracked=now-data[\'seen\']<=65 or bool(follower_wait and key in follower_wait[\'names\'])\n        if tracked and entry[\'outside\'] and key not in follower_bypass:\n            outside.add(key)\n    if not outside:\n        if follower_wait:\n            follower_wait=None\n            resume_waited_walk()\n            say_throttled(\'follower_wait\',\'Buon phu da vao trong 5m on dinh 1.5s; Leader tiep tuc dung moc tuyen.\')\n        result=True\n    else:\n        if follower_wait is None:\n            follower_wait={\'since\':now,\'names\':set(outside)}\n            stop_at_current_position()\n            details = []\n            for key in sorted(outside):\n                distance = entries[key][\'measurement\']\n                detail = \'chua co toa do hop le\' if distance is None else \'{:.1f}m\'.format(distance)\n                details.append(\'{} ({})\'.format(key, detail))\n            say_throttled(\'follower_wait\', \'Leader cho Buon phu toi da 10s. \'+\', \'.join(details))\n        follower_wait[\'names\'].update(outside)\n        remaining=10-(now-follower_wait[\'since\'])\n        if remaining<=0:\n            follower_bypass.update(outside)\n            follower_wait=None\n            resume_waited_walk()\n            say_throttled(\'follower_wait\',\'Da cho du 10s; Leader tiep tuc. Chi cho lai acc nay sau khi no quay vao 5m on dinh 2s.\')\n            result=True\n        else:\n            set_state(\'Cho Buon phu vao 5m: con {}s\'.format(int(math.ceil(remaining))))\n            result=False\n    follower_monitor[\'result\']=result\n    return result\n\n\ndef clear_convoy():\n    global convoy_controller, local_sale, follower_state\n    convoy_controller, local_sale, follower_state = None, None, None\n\n\ndef convoy_name(player):\n    if norm(player) in own_names():\n        return norm((bot.get_character_data() or {}).get(\'name\'))\n    context = convoy_controller\n    if context:\n        for pid, entry in context.get(\'roster\', {}).items():\n            current = (bot.get_party() or {}).get(pid) or {}\n            aliases = entry[\'aliases\'] | {norm(current.get(\'name\')), norm(current.get(\'job_name\'))}\n            if norm(player) and norm(player) in aliases:\n                return entry[\'canonical\']\n    member = resolve_follow_target(player)\n    return norm(member.get(\'name\') or player) if member else norm(player)\n\n\ndef convoy_wire(batch, action):\n    if not control_party(\'!CR2 {} {}\'.format(batch, action)):\n        raise ValueError(\'Khong gui duoc chat dieu phoi ban hang\')\n\n\ndef sale_reply(action):\n    global completed_sale\n    if not local_sale:\n        return\n    batch = local_sale[\'batch\']\n    if action == \'SOLD\':\n        completed_sale = dict(local_sale)\n    if action == \'SOLD\' and convoy_controller and convoy_controller[\'batch\'] == batch:\n        convoy_controller[\'sold\'].add(convoy_name((bot.get_character_data() or {}).get(\'name\', \'\')))\n    convoy_wire(batch, action)\n\n\ndef sell_team(turnaround=None):\n    global convoy_controller\n    load_identity()\n    if not config or config[\'hunter\'] or config.get(\'follower\') or not own_names() & names(config[\'leaders\']):\n        say(\'Chi Leader buon chinh duoc ra lenh Ban ca doi.\')\n        return\n    if convoy_controller:\n        say(\'Dang cho ca doi ban xong; khong phat lai lenh ban.\')\n        return\n    if not bot.get_party():\n        raise ValueError(\'Can trong Party de ban ca doi\')\n    prepare_sale_trip()\n    stop_owned()\n    me = convoy_name((bot.get_character_data() or {}).get(\'name\', \'\'))\n    roster = {}\n    for pid, member in (bot.get_party() or {}).items():\n        name = member.get(\'name\') or member.get(\'job_name\')\n        if name:\n            roster[pid] = {\'canonical\': convoy_name(name),\n                           \'aliases\': {norm(member.get(\'name\')), norm(member.get(\'job_name\'))}}\n    members = {entry[\'canonical\'] for entry in roster.values()}\n    members.discard(\'\')\n    members.add(me)\n    batch = uuid.uuid4().hex[:16]\n    convoy_controller = {\'batch\': batch, \'members\': members, \'roster\': roster, \'roles\': {me: \'trader\'},\n                         \'sold\': set(), \'phase\': \'roles\', \'deadline\': time.monotonic()+30,\n                         \'query_at\': time.monotonic(), \'retry\': time.monotonic()+15}\n    if turnaround is not None:\n        convoy_controller[\'turnaround\'] = turnaround\n        convoy_wire(batch, \'QUERY\')\n        return\n    convoy_wire(batch, \'QUERY\')\n    convoy_wire(batch, \'SELL\')\n    try:\n        start_local_sale(batch, (bot.get_character_data() or {}).get(\'name\', \'\'))\n    except Exception as error:\n        if convoy_controller:\n            convoy_controller[\'error\'] = \'Leader chua ban duoc: \'+str(error)\n        say(\'Leader ban that bai: \'+str(error))\n    set_state(\'Ban ca doi: cho xac nhan vai tro Party\')\n    say(\'Da gui SELL va Leader cung ban ngay. Dang thu xac nhan vai tro/ban xong; chua gui VE.\')\n\n\ndef prepare_sale_trip():\n    global trip, trip_lines\n    if trip is not None:\n        return\n    try:\n        prepare_trip()\n    except (OSError, ValueError) as error:\n        path = path_for(identity)[:-5]+\'.sale-only\'\n        trip = {\'path\': path, \'digest\': hashlib.sha256(b\'sale-only\').hexdigest(),\n                \'cursor\': 0, \'uncertain\': None, \'sale_only\': True}\n        trip_lines = [\'oldtrade,sell\']\n        say(\'Ban doc lap: khong can TXT/tuyen tren acc nay. \'+str(error))\n\n\ndef start_local_sale(batch, player, keep=False):\n    global local_sale, convoy_controller, active\n    if trade_fault:\n        notified = trade_fault.setdefault(\'notified\', set())\n        if batch not in notified:\n            if len(notified) < 32:\n                notified.add(batch)\n                convoy_wire(batch, \'FAIL\')\n        return\n    if config[\'hunter\']:\n        return\n    if completed_sale and completed_sale[\'batch\'] == batch:\n        convoy_wire(batch, \'SOLD\')\n        return\n    if local_sale and local_sale[\'batch\'] == batch:\n        if completed_sale and completed_sale[\'batch\'] == batch:\n            sale_reply(\'SOLD\')\n        return\n    saved_controller = convoy_controller\n    stop_owned()\n    convoy_controller = saved_controller\n    local_sale = {\'batch\': batch, \'leader\': convoy_name(player), \'keep\': keep}\n    try:\n        prepare_sale_trip()\n        active = True\n        say(\'Da nhan SELL tu \'+player+\'; dung theo va bat dau ban hang tren acc nay.\')\n        begin_finish(coordinated=True)\n    except Exception:\n        active = False\n        sale_reply(\'FAIL\')\n        raise\n\n\ndef handle_convoy(player, msg):\n    parts = party_command_parts(msg, \'!CR2\')\n    if not parts or parts[0] != \'!CR2\':\n        return False\n    if len(parts) != 4 or not party_member(player):\n        return True\n    batch, action = parts[2:]\n    if len(batch) != 16 or any(c not in \'0123456789abcdef\' for c in batch):\n        return True\n    trusted = trusted_leader(player)\n    me = convoy_name((bot.get_character_data() or {}).get(\'name\', \'\'))\n    sender = convoy_name(player)\n    if sender == me:\n        return True\n    if action in (\'QUERY\',\'SELL\',\'SELL_KEEP\',\'BUY_KEEP\') and not trusted:\n        say(\'Bo qua \'+action+\' tu \'+player+\': chua co ten that/ten nghe nay trong Leader duoc phep.\')\n        return True\n    if action == \'QUERY\' and trusted:\n        role = \'hunter\' if config[\'hunter\'] else (\'follower\' if config.get(\'follower\') else \'trader\')\n        convoy_wire(batch, \'ROLE_\' + role)\n    elif action == \'BUY_KEEP\' and trusted:\n        if config.get(\'follower\') and local_sale and completed_sale and local_sale.get(\'keep\') and local_sale[\'batch\'] == completed_sale[\'batch\'] == batch and local_sale[\'leader\'] == sender:\n            try:\n                start_return_follower_buy(player)\n            except Exception as error:\n                say(\'Mua lai that bai: \'+str(error))\n    elif action in (\'SELL\', \'SELL_KEEP\') and trusted:\n        try:\n            start_local_sale(batch, player, keep=action == \'SELL_KEEP\')\n        except Exception as error:\n            say(\'Ban theo Leader that bai: \' + str(error))\n    elif convoy_controller and convoy_controller[\'batch\'] == batch and sender in convoy_controller[\'members\']:\n        if action in (\'ROLE_hunter\', \'ROLE_follower\', \'ROLE_trader\') and convoy_controller[\'phase\'] == \'roles\':\n            convoy_controller[\'roles\'][sender] = action[5:]\n        elif action == \'SOLD\' and sender in convoy_controller[\'members\']:\n            convoy_controller[\'sold\'].add(sender)\n        elif action == \'FAIL\':\n            convoy_controller[\'error\'] = \'Acc {} bao ban that bai\'.format(player)\n    return True\n\n\ndef convoy_tick():\n    global convoy_controller, local_sale, completed_sale\n    context = convoy_controller\n    if not context:\n        return\n    now = time.monotonic()\n    current_party = bot.get_party() or {}\n    present = {convoy_name((bot.get_character_data() or {}).get(\'name\', \'\'))}\n    for pid, entry in context.get(\'roster\', {}).items():\n        if pid in current_party:\n            present.add(entry[\'canonical\'])\n    missing = context[\'members\'] - present\n    if context.get(\'error\') or now > context[\'deadline\']:\n        missing_roles = context[\'members\'] - set(context[\'roles\'])\n        missing_sold = context.get(\'sellers\', set()) - context[\'sold\']\n        reason = context.get(\'error\') or (\'Qua thoi gian cho: \'+\', \'.join(sorted(missing_roles or missing_sold or missing)))\n        convoy_controller = None\n        say(\'Dung dieu phoi ban: {}. Chua gui VE; kiem tra plugin/vai tro tren cac acc, roi thu lai.\'.format(reason))\n        return\n    if missing:\n        if \'missing_since\' not in context:\n            context[\'missing_since\'] = now\n            say(\'Dang doi du lieu Party (toi da 5s): \'+\', \'.join(sorted(missing)))\n        if now-context[\'missing_since\'] >= 5:\n            convoy_controller = None\n            say(\'Dung dieu phoi ban: khong con trong Party lien tuc 5s: {}. Chua gui VE.\'.format(\', \'.join(sorted(missing))))\n        return  # Never dispatch SELL/COME from a temporarily incomplete roster.\n    context.pop(\'missing_since\', None)\n    if context[\'phase\'] == \'roles\':\n        if context[\'members\'] <= set(context[\'roles\']):\n            context[\'sellers\'] = {name for name, role in context[\'roles\'].items() if role != \'hunter\'}\n            context.update(phase=\'selling\', deadline=now+180, retry=now+15)\n            keep = \'turnaround\' in context\n            convoy_wire(context[\'batch\'], \'SELL_KEEP\' if keep else \'SELL\')\n            start_local_sale(context[\'batch\'], (bot.get_character_data() or {}).get(\'name\', \'\'), keep=keep)\n        elif now >= context[\'retry\']:\n            context[\'retry\'] = now+15\n            convoy_wire(context[\'batch\'], \'QUERY\')\n    elif context[\'phase\'] == \'selling\':\n        if context[\'sellers\'] <= context[\'sold\']:\n            if \'turnaround\' in context:\n                if not loop_enabled:\n                    park_after_turnaround_sale()\n                    return\n                try:\n                    launch_return_route(context)\n                except (OSError, ValueError) as error:\n                    context[\'error\'] = str(error)\n                return\n            context.update(phase=\'delay\', ready_at=now+2)\n            say(\'Tat ca acc buon da ban het va huy thu. Cho 2 giay roi Party VE.\')\n        elif now >= context[\'retry\']:\n            context[\'retry\'] = now+15\n            convoy_wire(context[\'batch\'], \'SELL_KEEP\' if \'turnaround\' in context else \'SELL\')\n    elif context[\'phase\'] == \'delay\' and now >= context[\'ready_at\']:\n        if not phBotChat.Party(\'VE\'):\n            context[\'error\'] = \'Khong gui duoc Party VE\'\n            return\n        convoy_controller = None\n        local_sale = None\n        completed_sale = None\n        persist_finish(\'return_pending\')\n        say(\'Da cho 2 giay; Party VE cho ca hunter va buon. Ve thanh lap/cho theo tuy chon.\')\n        execute(\'RETURN\')\n\n\ndef follower_ready():\n    global follower_state, active\n    prepare_trip()\n    if trip.get(\'finish_stage\') in (\'return_pending\',\'return_wait\'):\n        execute(\'RETURN\')\n        return False\n    if trip.get(\'finish_stage\')==\'sold_wait\':\n        say(\'Buon phu da ban; cho Leader VE.\')\n        return False\n    pet=alive_transport()\n    loaded=bool(pet and transport_goods(pet)>0)\n    if loaded and pet.get(\'mounted\'):\n        return True\n    target=current_follow_target()\n    if not loaded and target and norm(target) not in own_names() and party_member(target):\n        try:\n            npc = party_trade_npc(target)\n        except (ValueError, KeyError, TypeError) as error:\n            say(\'Buon phu GO: \'+str(error)+\' Dung diem mua trong TXT da chon.\')\n        else:\n            start_party_trade(\'MUA\', target, npc=npc)\n            return False\n    buy=next((i for i,line in enumerate(trip_lines) if line.casefold().replace(\' \',\'\').startswith(\'oldtrade,buy\')),None)\n    if buy is None and not loaded:\n        raise ValueError(\'TXT can co oldtrade,buy truoc khi Buon phu tu mua\')\n    if hasattr(bot,\'stop_bot\'):\n        bot.stop_bot()\n    bot.stop_script()\n    prefix=[] if loaded else [line for line in trip_lines[:buy]\n        if not line.casefold().replace(\' \',\'\').startswith((\'oldtrade,spawn\',\'mount,transport\',\'dismount\'))]\n    follower_state={\'phase\':\'approach\' if prefix else \'spawn\',\'prefix\':prefix,\'index\':0,\n        \'buy_command\':trip_lines[buy] if buy is not None else None,\'purchased\':loaded,\n        \'nonce\':uuid.uuid4().hex[:16],\'ready\':False,\'deadline\':time.monotonic()+180,\n        \'next_at\':time.monotonic()+1,\'last_move\':float(\'-inf\'),\'mount_tries\':0}\n    active=True\n    say(\'Buon phu: den diem mua > goi thu > xac nhan mounted > mua > theo Leader.\')\n    return False\n\n\ndef CaravanRoutesFollowerLoaded(args):\n    if follower_state and follower_state[\'nonce\'] in [str(value).strip() for value in (args or [])]:\n        follower_state[\'ready\']=True\n    return 0\n\n\ndef follower_transport_entry():\n    entries=[(int(uid),pet) for uid,pet in (bot.get_pets() or {}).items()\n             if pet.get(\'type\')==\'transport\' and float(pet.get(\'hp\',0))>0]\n    if len(entries)>1:\n        raise ValueError(\'Co nhieu thu van tai; khong chon UID tuy y\')\n    return entries[0] if entries else (None,None)\n\n\ndef summon_follower_transport():\n    # Same item models/type codes as the user\'s supplied HoangHiep v3.9.\n    inventory=getattr(bot,\'get_inventory\',lambda:None)() or {}\n    codes={19647:4588,2134:4588,22934:4589,22935:4589}\n    for slot,item in enumerate(inventory.get(\'items\') or []):\n        if slot>=13 and item and item.get(\'model\') in codes:\n            result=bot.inject_joymax(0x704C,struct.pack(\'<BH\',slot,codes[item[\'model\']]),False)\n            if result is False:\n                raise ValueError(\'Khong gui duoc lenh dung cuon thu\')\n            say(\'Buon phu: da dung cuon thu slot={} model={}; doi thu xuat hien.\'.format(slot,item[\'model\']))\n            return\n    result=bot.start_script(\'oldtrade,spawn\\nwait,45000\\n\')\n    say(\'Buon phu: khong co cuon model quen thuoc; gui oldtrade,spawn mot lan, API=\'+repr(result)+\'. Doi get_pets.\')\n\n\ndef follower_goods_stable(context, goods, target, now):\n    if context.get(\'full_goods_count\') != goods:\n        context[\'full_goods_count\']=goods\n        context[\'full_goods_at\']=now\n    if goods < target:\n        return False\n    if now-context.get(\'full_goods_at\',now)<3:\n        set_state(\'Buon phu da du hang; cho on dinh 3s, chua cat giao dich\')\n        return False\n    return True\n\n\ndef defer_follower_follow(target):\n    if not config or not config.get(\'follower\'):\n        return False\n    if follower_state:\n        if follower_state.get(\'after_trade_target\')!=target:\n            follower_state[\'after_trade_target\']=target\n            say(\'Buon phu: giu lenh theo \'+str(target)+\'; mua va dong NPC xong moi bat Trace.\')\n        return True\n    if finish_context or trade_npc_close:\n        set_state(\'Buon phu dang ban/dong NPC; chua chuyen sang theo\')\n        return True\n    return False\n\n\ndef follower_native_buy_tick(context, uid, pet, now):\n    target = int(config.get(\'buy_goods\', 280))\n    goods = transport_goods(pet)\n    if goods >= target:\n        if not follower_goods_stable(context,goods,target,now):\n            return\n        if not ensure_trade_npc_closed(context, now):\n            return\n        context.update(purchased=True, phase=\'mount\', deadline=now+45,\n                       next_at=now+0.5, mount_tries=0)\n        say(\'Buon phu: da mua du {}/{} hang; tiep tuc tren thu.\'.format(goods, target))\n        return\n    context.pop(\'full_goods_at\',None)\n    context.pop(\'full_goods_count\',None)\n    if context[\'buy_sent\']:\n        # A delayed mounted flag must not interrupt an in-flight native NPC purchase.\n        set_state(\'Buon phu cho mua: {}/{} hang\'.format(goods, target))\n        return\n    if not pet.get(\'mounted\'):\n        bot.stop_script()\n        context.update(phase=\'mount\', deadline=now+45, next_at=now+0.5, mount_tries=0)\n        return\n    remaining = target - goods\n    context[\'buy_sent\'] = True\n    if remaining <= 5:\n        say(\'Buon phu: con thieu {} hang. Mua tay so con thieu de tiep tuc.\'.format(remaining))\n        return\n    context[\'npc_trade_started_at\'] = now\n    bind_native_trade(context)\n    if bot.start_script(\'oldtrade,buy,{}\\nwait,90000\\n\'.format(remaining)) is False:\n        say(\'phBot tu choi lenh mua. Mua tay {} hang; plugin se cho xac nhan.\'.format(remaining))\n        return\n    say(\'Buon phu: phBot tu mo NPC va mua {} hang; doi tui thu du {}.\'.format(remaining, target))\n\n\nTRADE_NPC_APPROACH_RADIUS = 25.0\n\n\ndef follower_tick():\n    global follower_state, active\n    context=follower_state\n    if not context or not config or not (config.get(\'follower\') or context.get(\'chat_trade\')):\n        return\n    now=time.monotonic()\n    if now>context[\'deadline\']:\n        phase=context[\'phase\']\n        stop_owned()\n        say(\'Buon phu dung: qua thoi gian buoc \'+phase+\'. Chua tu mua/theo khi chua xac minh xong.\')\n        return\n    if now<context.get(\'next_at\',0):\n        return\n    phase=context[\'phase\']\n    if phase == \'chat_npc\':\n        buying = context[\'chat_trade\'] == \'MUA\'\n        if buying:\n            character = bot.get_character_data() or {}\n            if character.get(\'region\') is None:\n                return\n            if character.get(\'region\') != context[\'chat_npc_region\']:\n                raise ValueError(\'Da roi khu cua NPC mua hang.\')\n            point = context[\'chat_npc_point\']\n            position = snapshot_position(character)\n            if position is None:\n                return\n            distance = math.hypot(position[\'x\'] - point[0], position[\'y\'] - point[1])\n            approach_radius = TRADE_NPC_APPROACH_RADIUS\n            at_npc = distance <= approach_radius\n        else:\n            _, point = party_trade_npc(context[\'chat_leader\'], context[\'chat_npc_uid\'])\n            character = bot.get_character_data() or {}\n            position = snapshot_position(character)\n            if position is None:\n                return\n            distance = math.hypot(position[\'x\'] - point[0], position[\'y\'] - point[1])\n            approach_radius = TRADE_NPC_APPROACH_RADIUS\n            at_npc = distance <= approach_radius\n        if at_npc:\n            if not buying:\n                say(\'BAN: da toi NPC (cach {:.1f}m, nguong {}m).\'.format(distance, approach_radius))\n                begin_finish(coordinated=True, wait_for_ve=True)\n                follower_state = None\n            else:\n                if context[\'chat_npc_uid\'] not in (bot.get_npcs() or {}):\n                    set_state(\'Buon phu: doi thay lai NPC mua hang\')\n                    return\n                context.update(phase=\'spawn\', deadline=now+45)\n                say(\'MUA: da toi NPC (cach {:.1f}m, nguong {}m); kiem tra thu van tai.\'.format(distance, approach_radius))\n        elif now >= context.get(\'move_at\', 0):\n            say_throttled(\'trade_npc_distance\', \'{}: con cach NPC {:.1f}m (nguong {}m).\'.format(context[\'chat_trade\'], distance, approach_radius), 8)\n            bot.move_to(*point)\n            context[\'move_at\'] = now + 3\n        return\n    if phase==\'approach\':\n        if context[\'index\']>=len(context[\'prefix\']):\n            context.update(phase=\'spawn\',deadline=now+45,next_at=now+0.5)\n            return\n        line=context[\'prefix\'][context[\'index\']]\n        point=walk_point(line)\n        if point is not None:\n            if reached(point):\n                context[\'index\']+=1\n                context[\'last_move\']=float(\'-inf\')\n            elif now-context[\'last_move\']>=3:\n                bot.move_to(*point)\n                context[\'last_move\']=now\n                set_state(\'Buon phu: den diem mua {},{}\'.format(point[0],point[1]))\n            return\n        if not context.get(\'native_sent\'):\n            context.update(native_sent=True,ready=False)\n            result=bot.start_script(line+\'\\nCaravanRoutesFollowerLoaded,\'+context[\'nonce\']+\'\\n\')\n            say(\'Buon phu lenh truoc mua \'+line+\'; API=\'+repr(result))\n        if context[\'ready\']:\n            bot.stop_script()\n            context[\'index\']+=1\n            context.update(native_sent=False,ready=False)\n        return\n    uid,pet=follower_transport_entry()\n    if phase==\'spawn\':\n        if pet:\n            bot.stop_script()\n            context.update(phase=\'mount\',deadline=now+45,next_at=now+0.5,mount_tries=0)\n            return\n        if not context.get(\'spawn_sent\'):\n            context[\'spawn_sent\']=True\n            summon_follower_transport()\n        set_state(\'Buon phu: doi thu van tai xuat hien\')\n        return\n    if phase==\'mount\':\n        if not pet:\n            raise ValueError(\'Thu van tai bien mat khi dang cho len thu\')\n        if pet.get(\'mounted\'):\n            say(\'Buon phu: da xac nhan len thu UID=\'+str(uid))\n            if context[\'purchased\']:\n                bot.stop_script()\n                follower_state,active=None,False\n                if context.get(\'after_trade_target\'):\n                    globals()[\'standalone_follow\']=True\n                    start_follow_target(context[\'after_trade_target\'])\n                elif context.get(\'chat_trade\'):\n                    target = context[\'chat_leader\']\n                    if norm(target) not in own_names():\n                        globals()[\'standalone_follow\'] = True\n                        start_follow_target(target)\n                    else:\n                        say(\'Leader da mua du va len thu; cho Party theo.\')\n                elif context.get(\'turn_follow\'):\n                    start_follow_target(context[\'turn_follow\'])\n                else:\n                    run_go()\n            else:\n                context.update(phase=\'buy\',deadline=now+90,next_at=now+1,ready=False,\n                               buy_sent=False,last_goods=None,stable_at=now)\n            return\n        if context[\'mount_tries\']<3:\n            result=bot.inject_joymax(0x70CB,b\'\\x01\'+struct.pack(\'<I\',uid),False)\n            context[\'mount_tries\']+=1\n            context[\'next_at\']=now+5\n            say(\'Buon phu: gui len thu UID={} lan {}/3; doi mounted thuc te.\'.format(uid,context[\'mount_tries\']))\n            if result is False:\n                raise ValueError(\'Khong gui duoc lenh mount UID=\'+str(uid))\n        set_state(\'Buon phu: doi xac nhan da len thu\')\n        return\n    if phase==\'buy\':\n        if not pet:\n            raise ValueError(\'Thu van tai bien mat trong luc mua\')\n        follower_native_buy_tick(context,uid,pet,now)\n\n\n\ndef event_loop():\n    load_identity()\n    try:\n        follow_stop_tick()\n        return_tick()\n        remember_transports()\n        recovery_tick()\n        loop_tick()\n        follow_request_tick()\n        follower_tick()\n        convoy_tick()\n    except Exception as error:\n        if recovery:\n            recovery_failed(str(error))\n        elif follower_state:\n            stop_owned()\n            say(\'Buon phu da dung: \'+str(error))\n        else:\n            say(\'Theo doi thu: \' + str(error))\n    if active:\n        c = bot.get_character_data() or {}\n        if c.get(\'dead\') or not bot.get_party():\n            if follow_intent and not follow_blocked:\n                pause_trace_for_rejoin(\'cho nhan vat/Party san sang\')\n                return\n            stop_owned()\n            say(\'Da dung: nhan vat chet hoac khong con Party. Khong tu chay lai.\')\n            return\n        try:\n            trace_follow_watchdog()\n            if not active:\n                return\n            maintain_trace_transport()\n            update_escort_combat()\n            if finish_context and (config.get(\'follower\') or finish_context.get(\'wait_for_ve\')):\n                finish_tick()\n            else:\n                merchant_tick()\n        except Exception as error:\n            stop_owned()\n            say(\'Da tam dung do loi: \' + str(error))\n\n\ndef disconnected():\n    globals()[\'follow_intent\']=None\n    globals()[\'buy_departure\']=None\n    global identity, config, active, seen, follow_mode, merchant_step, trip, trip_lines, finish_context, follow_override, follow_request\n    clear_convoy()\n    globals()[\'return_request\'] = None\n    globals()[\'selected_npc\'] = None\n    globals()[\'last_trade_shop\'] = None\n    globals()[\'trade_npc_close\'] = None\n    globals()[\'native_trade_context\'] = None\n    npc_session.update(owner=identity, generation=npc_session[\'generation\']+1, uid=None, state=\'unknown\', closed_at=None)\n    set_loop(False)\n    restore_escort_combat()\n    cancel_recovery(restore=True)\n    finish_context = None\n    follow_override, follow_request = None, None\n    identity, config, active, seen = None, None, False, {}\n    follow_mode = None\n    merchant_step, trip, trip_lines = None, None, []\n    set_state(\'Mat ket noi - khong tu chay lai\')\n\n\ndef teleported():\n    globals()[\'return_request\'] = None\n    globals()[\'selected_npc\'] = None\n    globals()[\'last_trade_shop\'] = None\n    globals()[\'trade_npc_close\'] = None\n    globals()[\'native_trade_context\'] = None\n    npc_session.update(owner=identity, generation=npc_session[\'generation\']+1, uid=None, state=\'unknown\', closed_at=None)\n    # Teleports do not prove a trade script has finished; retain ownership until STOP.\n    load_identity()\n    if trip and trip.get(\'finish_stage\') == \'return_wait\':\n        origin = trip.get(\'return_origin\') or {}\n        c = bot.get_character_data() or {}\n        moved = c.get(\'region\') != origin.get(\'region\')\n        if not moved:\n            try:\n                moved = math.hypot(c[\'x\']-origin[\'x\'], c[\'y\']-origin[\'y\']) > 30\n            except (KeyError, TypeError):\n                moved = False\n        if moved:\n            persist_finish(\'done\')\n            set_state(\'Da ve thanh sau ban/huy/VE\')\n        else:\n            say(\'Co spawn nhung chua thay roi diem cuoi; chua danh dau hoan tat ve thanh.\')\n    if recovery:\n        if recovery[\'stage\'] == \'return\':\n            if recovery[\'mode\'] == 2:\n                cancel_recovery(restore=True)\n                set_state(\'Thu chet: da ve thanh, dung tai day\')\n            elif recovery_near_origin(recovery):\n                recovery_failed(\'Spawn van o diem cu; chua xac nhan da ve thanh\')\n            else:\n                recovery[\'stage\'] = \'reverse_ready\'\n                recovery[\'reverse_at\'] = time.monotonic()+5\n                recovery[\'deadline\'] = time.monotonic()+95\n                say(\'Da ve thanh; cho 5s roi moi dung Reverse Return type 0. STOP de huy.\')\n        elif recovery[\'stage\'] == \'reverse\':\n            if recovery_near_origin(recovery):\n                recovery[\'stage\'] = \'spawn_ready\'\n                say(\'Da nhan spawn sau Reverse; kiem tra toa do roi goi/len thu moi.\')\n            else:\n                say(\'Bo qua spawn trung/chua ve diem Reverse; van cho dich chuyen nguoc.\')\n        return\n    if follow_intent and not follow_blocked:\n        # A portal/Return can unsummon transport. Preserve follow on foot too.\n        follow_intent[\'needs_transport\']=False\n        pause_trace_for_rejoin(\'da spawn sau dich chuyen\')\n    schedule_loop_after_return()\n\n\nload_identity()\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n\n# Integrated COME/Ferry view. Existing per-character settings remain compatible.\nferry_widgets=[]\ncontrol_view=\'caravan\'\n\ndef ferry_control(kind,x,y,*args):\n    widget=readable_label(*args) if kind==\'createLabel\' else getattr(QtBind,kind)(*args)\n    view=\'shared\' if y<60 or y>=300 else (\'ferry\' if x>=300 else \'chat\')\n    ferry_widgets.append((widget,x,y,view))\n    QtBind.move(gui,widget,-2000,y)\n    return widget\n\n\nfrom phBot import *\nimport phBotChat\nimport QtBind\nimport time\nimport os\nimport json\nimport hashlib\nimport tempfile\n\ncome_pName = \'CaravanRoutes/PartyCome\'\ncome_pVersion = \'1.2\'\n\n\n\nferry_control(\'createLabel\', 10, 72, gui, \'<span style="color:#63d9df;font-size:13px;"><b>Cấu hình lệnh về thành</b></span>\', 10, 72)\nferry_control(\'createLabel\', 10, 100, gui, \'Leaders rieng (cach nhau dau ,):\', 10, 100)\ncome_leader_box = ferry_control(\'createLineEdit\', 10, 120, gui, \'\', 10, 120, 270, 20)\nferry_control(\'createButton\', 10, 148, gui, \'come_save_clicked\', \'Luu Leaders VE\', 10, 148)\nferry_control(\'createButton\', 10, 185, gui, \'come_come_clicked\', \'VE Party\', 10, 185)\nferry_control(\'createButton\', 145, 185, gui, \'come_come_all_clicked\', \'VE All\', 145, 185)\nferry_control(\'createLabel\', 10, 225, gui, \'Nhan lenh VE tu Leader qua All / Party.\', 10, 225)\nferry_control(\'createLabel\', 10, 247, gui, \'Dung Return Scroll. Cho giua 2 lan: 30 giay.\', 10, 247)\nferry_control(\'createLabel\', 10, 280, gui, \'Tat Leader chung = dung 2 o Leader rieng.\', 10, 280)\n\ncome_loaded_identity = None\ncome_last_action = 0\ncome_COOLDOWN = 30\n\ndef come_normalize_leaders(text):\n    names = []\n    seen = set()\n    for value in text.replace(\';\', \',\').split(\',\'):\n        value = value.strip()\n        if value and value.lower() not in seen:\n            names.append(value)\n            seen.add(value.lower())\n    return names\n\n\ndef come_get_leaders():\n    return names(shared_leader_text())\n\n\n\ndef come_config_identity():\n    char = get_character_data() or {}\n    if not char.get(\'name\') or not char.get(\'server\'):\n        return None\n    return (char[\'server\'], char[\'name\'])\n\n\ndef come_config_file(identity):\n    key = hashlib.sha256(json.dumps(identity, ensure_ascii=False).encode(\'utf-8\')).hexdigest()\n    return os.path.join(get_config_dir(), \'CaravanRoutes\', \'PartyCome\', key + \'.json\')\n\n\ndef come_load_leaders():\n    global come_loaded_identity\n    identity = come_config_identity()\n    if identity is None or identity == come_loaded_identity:\n        return\n    # Clear the previous character\'s authorization before loading another.\n    readable_set_text(gui, come_leader_box, \'\')\n    come_loaded_identity = identity\n    try:\n        with open(come_config_file(identity), \'r\', encoding=\'utf-8\') as stream:\n            data = json.load(stream)\n        names = data.get(\'leaders\')\n        if not isinstance(names, list) or not all(isinstance(n, str) for n in names):\n            raise ValueError(\'Invalid leaders list\')\n        readable_set_text(gui, come_leader_box, \', \'.join(come_normalize_leaders(\',\'.join(names))))\n        pass  # Startup notice intentionally silenced; runtime logging is unchanged.\n    except FileNotFoundError:\n        pass\n    except (OSError, ValueError, TypeError, AttributeError) as error:\n        log(\'[CaravanRoutes/PartyCome] Khong doc duoc Leaders: \' + str(error))\n\n\ndef come_save_clicked():\n    say(\'Lưu Leader(s) một lần ở Chạy buôn để dùng cho tất cả lệnh.\')\n\n\n\ndef come_event_loop():\n    come_load_leaders()\n\n\ndef come_teleported():\n    come_load_leaders()\n\n\ndef come_disconnected():\n    global come_loaded_identity\n    come_loaded_identity = None\n    readable_set_text(gui, come_leader_box, \'\')\n\n\ndef come_execute_return():\n    load_identity()\n    if not config:\n        say(\'Luu cau hinh CaravanRoutes truoc khi dung VE.\')\n        return\n    execute(\'RETURN\')\n\n\ndef merged_come_send(channel):\n    load_identity()\n    if not config or not bot.get_party() or not (own_names() & come_get_leaders()):\n        say(\'VE: can o Party va ten acc nay nam trong Leaders VE da luu.\')\n        return\n    pet=alive_transport()\n    if not config[\'hunter\'] and pet and transport_goods(pet)>0:\n        say(\'Acc buon con hang; ban hang truoc khi VE.\')\n        return\n    if time.monotonic()-last_return<30 or return_request:\n        say(\'VE dang cho/cooldown; khong gui lap.\')\n        return\n    sender=phBotChat.Party if channel==4 else phBotChat.All\n    if sender(\'VE\'):\n        come_execute_return()\n\n\ndef come_come_clicked():\n    merged_come_send(4)\n\n\ndef come_come_all_clicked():\n    merged_come_send(1)\n\n\ndef come_handle_chat(t, player, msg):\n    if not isinstance(msg,str) or msg.strip().upper()!=\'VE\' or t not in (1,4):\n        return False\n    if not config:\n        say_throttled(\'ve_no_config\',\'Nhan VE nhung acc nay chua Luu cau hinh Leader/vai tro.\',15)\n        return True\n    if not isinstance(player,str) or not player.strip():\n        say_throttled(\'ve_no_sender\',\'Nhan VE nhung thieu ten nguoi gui; doi du lieu Party/server.\',15)\n        return True\n    is_self=norm(player) in own_names()\n    allowed=come_get_leaders()\n    member=resolve_follow_target(player)\n    aliases={norm(player)}\n    if isinstance(member,dict):\n        aliases|={norm(member.get(\'name\')),norm(member.get(\'job_name\'))}\n    if is_self:\n        aliases|=own_names()\n    if not (member or is_self):\n        say_throttled(\'ve_not_party\',\'Tu choi VE tu \'+player+\': chua tim thay nguoi gui trong Party.\',15)\n        return True\n    if not aliases & allowed:\n        say_throttled(\'ve_not_leader\',\'Tu choi VE tu \'+player+\': Leaders VE dang cho phep \'+(\', \'.join(sorted(allowed)) or \'(trong)\')+\'. Kiem tra Leader chung/Leader VE tren acc nay.\',15)\n        return True\n    # A leader typing All VE relays to Party, so trader and hunter both receive it.\n    if is_self and t==1:\n        now=time.monotonic()\n        if now>=ve_relay_guard.get(identity,float(\'-inf\')):\n            ve_relay_guard[identity]=now+30\n            if phBotChat.Party(\'VE\'):\n                say(\'Da chuyen VE sang chat Party de goi ca bao tieu va buon.\')\n            else:\n                ve_relay_guard[identity]=now+3\n                say(\'Khong gui duoc VE Party; kiem tra Party roi gui lai.\')\n    if t==1 and not config[\'hunter\'] and not is_self:\n        return True\n    pet=alive_transport()\n    if not config[\'hunter\'] and pet and transport_goods(pet)>0:\n        say_throttled(\'ve_has_goods\',\'Nhan VE nhung acc buon con hang; can ban truoc.\',15)\n        return True\n    if trip and trip.get(\'finish_stage\')==\'sold_wait\':\n        persist_finish(\'return_pending\')\n    say_throttled(\'ve_received\',\'Nhan VE tu \'+player+\' qua \'+(\'Party\' if t==4 else \'All\')+\'; dong NPC va dung bua ve thanh.\',10)\n    come_execute_return()\n    return True\n\n\ncome_load_leaders()\n\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n"""phBot: leader chat -> nearby ferry request.\n\nPacket assumption for this custom server: <NPC UID:uint32><02><destination:uint32>.\nMultiple routes, each with source NPC name/model and destination ID.\nNPC model IDs are stable selectors; runtime NPC UIDs are resolved nearby.\nInstall on every character. Configure/save the same trusted leader per character.\n"""\nfrom phBot import get_character_data, get_config_dir, get_npcs, get_party, inject_joymax, log\nimport phBotChat\nimport QtBind\nimport base64\nimport hashlib\nimport json\nimport math\nimport os\nimport struct\nimport time\n\n\nferry_control(\'createLabel\', 310, 72, gui, \'FERRY - Qua pha\', 310, 72)\nferry_control(\'createLabel\', 310, 100, gui, \'Leader rieng:\', 310, 100)\nferry_leader_box = ferry_control(\'createLineEdit\', 400, 96, gui, \'\', 400, 96, 175, 20)\nferry_control(\'createButton\', 590, 94, gui, \'ferry_save_leader_only\', \'Luu Leader\', 590, 94)\nferry_control(\'createButton\', 590, 122, gui, \'ferry_use_current_leader\', \'Lay ten nhan vat\', 590, 122)\nferry_control(\'createLabel\', 310, 130, gui, \'Lenh chat:\', 310, 130)\nferry_command_box = ferry_control(\'createLineEdit\', 400, 126, gui, \'!pha 1\', 400, 126, 175, 20)\nferry_control(\'createLabel\', 310, 160, gui, \'Tuyen:\', 310, 160)\nferry_route_box = ferry_control(\'createLineEdit\', 360, 156, gui, \'1\', 360, 156, 45, 20)\nferry_control(\'createButton\', 415, 154, gui, \'ferry_previous_route\', \'<\', 415, 154)\nferry_control(\'createButton\', 455, 154, gui, \'ferry_next_route\', \'>\', 455, 154)\nferry_route_status = ferry_control(\'createLabel\', 505, 160, gui, \'Saved: none\', 505, 160)\nferry_control(\'createLabel\', 310, 190, gui, \'NPC:\', 310, 190)\nferry_npc_box = ferry_control(\'createLineEdit\', 360, 186, gui, \'La Han - Nguoi ban ve do\', 360, 186, 350, 20)\nferry_control(\'createLabel\', 310, 220, gui, \'Model ID:\', 310, 220)\nferry_model_box = ferry_control(\'createLineEdit\', 375, 216, gui, \'\', 375, 216, 100, 20)\nferry_control(\'createLabel\', 495, 220, gui, \'Dich ID:\', 495, 220)\nferry_dest_box = ferry_control(\'createLineEdit\', 555, 216, gui, \'12\', 555, 216, 75, 20)\nferry_control(\'createButton\', 310, 246, gui, \'ferry_save_settings\', \'Luu tuyen / Bat\', 310, 246)\nferry_control(\'createButton\', 455, 246, gui, \'ferry_reload_all\', \'Nạp đủ phà\', 455, 246)\nferry_control(\'createButton\', 565, 246, gui, \'ferry_delete_route\', \'Xoa tuyen\', 565, 246)\nferry_control(\'createButton\', 310, 279, gui, \'ferry_scan_npcs\', \'NPC gan day\', 310, 279)\nferry_control(\'createButton\', 445, 279, gui, \'ferry_arm_capture\', \'Ghi qua pha\', 445, 279)\nferry_control(\'createButton\', 570, 279, gui, \'ferry_apply_capture\', \'Dung ban ghi\', 570, 279)\nferry_control(\'createButton\', 310, 312, gui, \'ferry_import_old_routes\', \'Nhap pha tu Leader cu\', 310, 312)\nferry_identity_label = ferry_control(\'createLabel\', 10, 315, gui, \'Current character: waiting...\', 10, 315)\n\nferry_settings = None\nferry_identity = None\nferry_last_request = float(\'-inf\')\nferry_pending = None\nferry_last_broadcast = float(\'-inf\')\nferry_WIRE_PREFIX = \'!CRP \'\nferry_capture_armed = False\nferry_capture_owner = None\nferry_capture_npcs = {}\nferry_captured_packet = None\n\nFERRY_DEFAULT_SLOTS = 8\nFERRY_DEFAULT_NPC = \'La Han - Nguoi ban ve do\'\nFERRY_DEFAULT_DESTINATION = 12\n\n\ndef ferry_default_command(key):\n    return \'!pha \' + str(key)\n\n\ndef ferry_ensure_default_slots(routes):\n    """Guarantee shared ferry slots 1..8 with chat commands !pha 1 .. !pha 8."""\n    merged = dict(routes or {})\n    commands = set()\n    template = None\n    for key, route in merged.items():\n        if not isinstance(route, dict):\n            continue\n        if isinstance(route.get(\'command\'), str) and route[\'command\'].strip():\n            commands.add(route[\'command\'].strip().casefold())\n        if template is None and (route.get(\'npc\') or route.get(\'model\') is not None):\n            template = route\n    base_npc = (template or {}).get(\'npc\') or FERRY_DEFAULT_NPC\n    base_model = (template or {}).get(\'model\')\n    base_dest = (template or {}).get(\'destination\', FERRY_DEFAULT_DESTINATION)\n    for number in range(1, FERRY_DEFAULT_SLOTS + 1):\n        key = str(number)\n        command = ferry_default_command(key)\n        if key in merged and isinstance(merged[key], dict):\n            route = dict(merged[key])\n            route.setdefault(\'command\', command)\n            if not isinstance(route.get(\'npc\'), str):\n                route[\'npc\'] = base_npc\n            if route.get(\'model\') is None and not route.get(\'npc\'):\n                route[\'model\'] = base_model\n            if route.get(\'destination\') is None:\n                route[\'destination\'] = base_dest\n            try:\n                ferry_validate_route(key, route)\n            except (ValueError, TypeError, AttributeError):\n                continue\n            commands.add(route[\'command\'].strip().casefold())\n            merged[key] = route\n            continue\n        if command.casefold() in commands:\n            log(\'[CaravanRoutes/PartyFerry] Bo qua slot pha \' + key + \': lenh chat \' + command + \' da dung.\')\n            continue\n        route = {\n            \'npc\': base_npc if isinstance(base_npc, str) else FERRY_DEFAULT_NPC,\n            \'model\': base_model,\n            \'destination\': base_dest if base_dest is not None else FERRY_DEFAULT_DESTINATION,\n            \'command\': command,\n        }\n        try:\n            ferry_validate_route(key, route)\n        except (ValueError, TypeError, AttributeError) as error:\n            log(\'[CaravanRoutes/PartyFerry] Bo qua slot pha \' + key + \': \' + str(error))\n            continue\n        merged[key] = route\n        commands.add(command.casefold())\n    return merged\n\n\ndef ferry_normalize_name(value):\n    return str(value or \'\').strip().lstrip(\'*\').casefold()\n\n\ndef ferry_own_names():\n    character = get_character_data() or {}\n    return {ferry_normalize_name(character.get(key)) for key in (\'name\', \'job_name\')\n            if character.get(key)}\n\n\ndef ferry_is_own_name(value):\n    return bool(ferry_normalize_name(value)) and ferry_normalize_name(value) in ferry_own_names()\n\n\ndef ferry_leader_names(value):\n    return {ferry_normalize_name(name) for name in value.replace(\';\', \',\').split(\',\')} - {\'\'}\n\n\ndef ferry_owns_leader_field(value):\n    return bool(ferry_own_names() & ferry_leader_names(value))\n\n\ndef ferry_show_identity():\n    character = get_character_data() or {}\n    text = \'Current: {} | Job name: {}\'.format(character.get(\'name\', \'?\'), character.get(\'job_name\') or \'-\')\n    readable_set_text(gui, ferry_identity_label, text)\n    return text\n\n\ndef ferry_use_current_leader():\n    show_caravan_view()\n    use_me()\n    say(\'Đã điền tên vào Leader(s). Bấm Lưu cấu hình để áp dụng cho mọi mục.\')\n\n\n\ndef ferry_config_identity():\n    character = get_character_data()\n    if not character or not character.get(\'name\'):\n        return None\n    return (character.get(\'server\', \'\'), character[\'name\'])\n\n\ndef ferry_config_path(key):\n    digest = hashlib.sha256(json.dumps(key).encode(\'utf-8\')).hexdigest()\n    return os.path.join(get_config_dir(), \'CaravanRoutes\', \'PartyFerry\', digest + \'.json\')\n\n\ndef ferry_shared_path():\n    return ferry_config_path((ferry_identity[0],))[:-5] + \'.routes.json\'\n\n\ndef ferry_shared_routes(fallback):\n    try:\n        with open(ferry_shared_path(), encoding=\'utf-8\') as stream:\n            routes = json.load(stream)\n    except FileNotFoundError:\n        return dict(fallback)\n    for key, route in routes.items():\n        ferry_validate_route(key, route)\n    ferry_validate_commands(routes)\n    return routes\n\n\ndef ferry_write_shared_routes(routes):\n    path = ferry_shared_path()\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    with tempfile.NamedTemporaryFile(mode=\'w\', encoding=\'utf-8\', dir=os.path.dirname(path),\n                                     delete=False) as stream:\n        temporary = stream.name\n        try:\n            json.dump(routes, stream, ensure_ascii=False)\n            stream.close()\n            os.replace(temporary, path)\n        finally:\n            if os.path.exists(temporary):\n                os.remove(temporary)\n\n\ndef ferry_event_loop():\n    global ferry_identity, ferry_settings, ferry_last_request, ferry_pending, ferry_capture_armed, ferry_capture_owner, ferry_capture_npcs, ferry_captured_packet\n    ferry_show_identity()\n    key = ferry_config_identity()\n    if key is None and ferry_identity is not None and follow_intent:\n        return\n    if key == ferry_identity:\n        if ferry_capture_armed:\n            ferry_capture_npcs.update(get_npcs() or {})\n        ferry_process_pending()\n        return\n    ferry_identity, ferry_settings = key, None\n    ferry_pending = None\n    ferry_capture_armed, ferry_capture_owner, ferry_capture_npcs, ferry_captured_packet = False, None, {}, None\n    ferry_update_route_status()\n    ferry_last_request = float(\'-inf\')\n    readable_set_text(gui, ferry_leader_box, \'\')\n    readable_set_text(gui, member_ferry_leaders, \'\')\n    readable_set_text(gui, ferry_command_box, \'!pha 1\')\n    readable_set_text(gui, ferry_npc_box, \'La Han - Nguoi ban ve do\')\n    readable_set_text(gui, ferry_route_box, \'1\')\n    readable_set_text(gui, ferry_model_box, \'\')\n    readable_set_text(gui, ferry_dest_box, \'12\')\n    if key:\n        try:\n            try:\n                with open(ferry_config_path(key), encoding=\'utf-8\') as stream:\n                    data = json.load(stream)\n            except FileNotFoundError:\n                data = {\'leader\': \'\', \'routes\': {}}\n            if not all(isinstance(data.get(k), str)\n                       for k in (\'leader\',)):\n                raise ValueError(\'Invalid settings\')\n            if \'routes\' not in data:  # migrate version 1\n                data[\'routes\'] = {\'1\': {\'npc\': data.get(\'npc\', \'La Han - Nguoi ban ve do\'), \'model\': None, \'destination\': 12}}\n            for key, route in data[\'routes\'].items():\n                route.setdefault(\'command\', data.get(\'command\', \'!pha\') + \' \' + key)\n                ferry_validate_route(key, route)\n            ferry_validate_commands(data[\'routes\'])\n            legacy_routes = data[\'routes\']\n            data[\'routes\'] = ferry_shared_routes(legacy_routes)\n            if not os.path.exists(ferry_shared_path()):\n                data[\'routes\'] = ferry_merge_saved_routes(data[\'routes\'])\n            data[\'routes\'] = ferry_ensure_default_slots(data[\'routes\'])\n            ferry_write_shared_routes(data[\'routes\'])\n            ferry_settings = data\n            readable_set_text(gui, ferry_leader_box, data[\'leader\'])\n            readable_set_text(gui, member_ferry_leaders, data[\'leader\'])\n            if data[\'routes\']:\n                readable_set_text(gui, ferry_route_box, ferry_sorted_route_keys()[0])\n                ferry_load_route()\n            ferry_update_route_status()\n        except FileNotFoundError:\n            pass\n        except Exception as error:\n            log(\'[CaravanRoutes/PartyFerry] Cannot load settings: \' + str(error))\n\n\ndef ferry_uint32(text):\n    text = str(text).strip()\n    value = int(text, 16 if text.lower().startswith(\'0x\') else 10)\n    if not 0 <= value <= 0xFFFFFFFF:\n        raise ValueError(\'ID must be 0..4294967295\')\n    return value\n\n\ndef ferry_validate_route(key, route):\n    if not key or len(key.split()) != 1:\n        raise ValueError(\'Route key must be one word or number\')\n    if not isinstance(route.get(\'npc\'), str):\n        raise ValueError(\'Invalid NPC name\')\n    if not route[\'npc\'] and route.get(\'model\') is None:\n        raise ValueError(\'Enter NPC name or model ID\')\n    if not isinstance(route.get(\'command\'), str) or not route[\'command\'].strip():\n        raise ValueError(\'Enter a chat command for this route\')\n    if route[\'command\'].strip().casefold() == \'ve\':\n        raise ValueError(\'VE is reserved for Return Scroll\')\n    if route[\'command\'].casefold().startswith(ferry_WIRE_PREFIX.casefold()):\n        raise ValueError(\'Command prefix !CRP is reserved\')\n    ferry_uint32(route[\'destination\'])\n    if route.get(\'model\') is not None:\n        ferry_uint32(route[\'model\'])\n\n\ndef ferry_validate_commands(routes):\n    commands = [r[\'command\'].strip().casefold() for r in routes.values()]\n    if len(commands) != len(set(commands)):\n        raise ValueError(\'Each route must have a different chat command\')\n\n\ndef ferry_persist(data):\n    global ferry_settings\n    path = ferry_config_path(ferry_identity)\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    with open(path + \'.tmp\', \'w\', encoding=\'utf-8\') as stream:\n        json.dump(data, stream, ensure_ascii=False)\n    os.replace(path + \'.tmp\', path)\n    ferry_settings = data\n    ferry_update_route_status()\n\n\ndef ferry_import_old_routes():\n    ferry_event_loop()\n    if not ferry_identity:\n        return\n    source = next(iter(come_normalize_leaders(shared_leader_text())), \'\')\n    if not source:\n        say(\'Lưu Leader(s) ở Chạy buôn trước khi nhập tuyến phà.\')\n        return\n    try:\n        with open(ferry_config_path((ferry_identity[0], source)), encoding=\'utf-8\') as stream:\n            old = json.load(stream)\n        routes = ferry_shared_routes((ferry_settings or {}).get(\'routes\', {}))\n        added = []\n        for key, route in old.get(\'routes\', {}).items():\n            if key not in routes:\n                ferry_validate_route(key, route)\n                routes[key] = route\n                added.append(key)\n        if not added:\n            say(\'Khong co ma pha moi trong cau hinh cua \' + source + \'.\')\n            return\n        ferry_validate_commands(routes)\n        ferry_write_shared_routes(routes)\n        data = dict(ferry_settings or {})\n        data.setdefault(\'leader\', \'\')\n        data[\'routes\'] = routes\n        ferry_persist(data)\n        readable_set_text(gui, ferry_route_box, ferry_sorted_route_keys()[0])\n        ferry_load_route()\n        say(\'Da nhap ma pha: {}. Tong so ma pha dung chung: {}.\'.format(\', \'.join(added), len(routes)))\n    except FileNotFoundError:\n        say(\'Khong tim thay cau hinh Leader cu. Nhap dung ten nhan vat (ca chu hoa/thuong) tren cung server.\')\n    except (OSError, ValueError, TypeError, AttributeError) as error:\n        say(\'Nhap ma pha that bai: \' + str(error))\n\n\n\ndef ferry_save_leader_only():\n    say(\'Lưu Leader(s) một lần ở Chạy buôn để dùng cho tất cả lệnh.\')\n\n\n\ndef ferry_save_settings():\n    ferry_event_loop()\n    if not ferry_identity:\n        log(\'[CaravanRoutes/PartyFerry] Login before saving.\')\n        return\n    if not ferry_owns_leader_field(ferry_leader_text()):\n        log(\'[CaravanRoutes/PartyFerry] Route NOT saved: Leader field does not match this character. \' + ferry_show_identity())\n        log(\'[CaravanRoutes/PartyFerry] On leader: click Leader: Use current character. On members: click Member: Save leader.\')\n        return\n    try:\n        key = QtBind.text(gui, ferry_route_box).strip().casefold()\n        route = {\'command\': QtBind.text(gui, ferry_command_box).strip(),\n                 \'npc\': QtBind.text(gui, ferry_npc_box).strip(),\n                 \'model\': ferry_uint32(QtBind.text(gui, ferry_model_box)) if QtBind.text(gui, ferry_model_box).strip() else None,\n                 \'destination\': ferry_uint32(QtBind.text(gui, ferry_dest_box))}\n        ferry_validate_route(key, route)\n        data = {\'leader\': ferry_stored_leader(),\n                \'routes\': ferry_shared_routes((ferry_settings or {}).get(\'routes\', {}))}\n        if not data[\'leader\']:\n            raise ValueError(\'Enter leader name\')\n        data[\'routes\'][key] = route\n        ferry_validate_commands(data[\'routes\'])\n        ferry_write_shared_routes(data[\'routes\'])\n        ferry_persist(data)\n        log(\'[CaravanRoutes/PartyFerry] Saved route \' + key + \'. Routes: \' + \', \'.join(data[\'routes\']))\n    except Exception as error:\n        log(\'[CaravanRoutes/PartyFerry] Save failed: \' + str(error))\n\n\ndef ferry_merge_saved_routes(routes):\n    """Fill missing slots from this server\'s character and saved Leader profiles."""\n    merged = dict(routes)\n    names_to_read = [ferry_identity[1], *come_normalize_leaders(ferry_stored_leader())]\n    commands = {route[\'command\'].strip().casefold() for route in merged.values()}\n    for name in dict.fromkeys(names_to_read):\n        try:\n            path = ferry_config_path((ferry_identity[0], name))\n            with open(path, encoding=\'utf-8\') as stream:\n                profile = json.load(stream)\n            saved = profile.get(\'routes\', {})\n            if not isinstance(saved, dict):\n                continue\n        except FileNotFoundError:\n            continue\n        except (OSError, ValueError, TypeError, AttributeError) as error:\n            log(\'[CaravanRoutes/PartyFerry] Không đọc được phà của \' + name + \': \' + str(error))\n            continue\n        for key, route in saved.items():\n            key = key.strip().casefold()\n            if key in merged or not isinstance(route, dict):\n                continue\n            route = dict(route)\n            route.setdefault(\'command\', str(profile.get(\'command\') or \'!pha\') + \' \' + key)\n            try:\n                ferry_validate_route(key, route)\n            except (ValueError, TypeError, AttributeError) as error:\n                log(\'[CaravanRoutes/PartyFerry] Bỏ tuyến phà \' + key + \': \' + str(error))\n                continue\n            command = route[\'command\'].strip().casefold()\n            if command in commands:\n                log(\'[CaravanRoutes/PartyFerry] Bỏ tuyến phà \' + key + \' vì trùng lệnh chat.\')\n                continue\n            merged[key] = route\n            commands.add(command)\n    return merged\n\n\ndef ferry_reload_all():\n    ferry_event_loop()\n    if not ferry_identity or ferry_settings is None:\n        say(\'Vào game trước khi nạp các chuyến phà.\')\n        return\n    try:\n        routes = ferry_shared_routes(ferry_settings.get(\'routes\', {}))\n        merged = ferry_ensure_default_slots(ferry_merge_saved_routes(routes))\n        ferry_write_shared_routes(merged)\n        ferry_settings[\'routes\'] = merged\n        keys = ferry_sorted_route_keys()\n        if not keys:\n            ferry_update_route_status()\n            say(\'Chưa có chuyến phà đã lưu trên server này.\')\n            return\n        selected_key = QtBind.text(gui, ferry_route_box).strip().casefold()\n        if selected_key not in merged:\n            readable_set_text(gui, ferry_route_box, keys[0])\n        ferry_load_route()\n        commands = [merged[k][\'command\'] for k in keys]\n        say(\'Đã nạp {} chuyến phà: {}.\'.format(len(keys), \', \'.join(commands)))\n    except (OSError, ValueError, TypeError, AttributeError) as error:\n        say(\'Nạp phà thất bại: \' + str(error))\n\n\ndef ferry_load_route():\n    if not ferry_settings:\n        return\n    key = QtBind.text(gui, ferry_route_box).strip().casefold()\n    route = ferry_settings[\'routes\'].get(key)\n    if not route:\n        log(\'[CaravanRoutes/PartyFerry] Unknown route. Saved: \' + \', \'.join(ferry_settings[\'routes\']))\n        return\n    readable_set_text(gui, ferry_command_box, route[\'command\'])\n    readable_set_text(gui, ferry_npc_box, route[\'npc\'])\n    readable_set_text(gui, ferry_model_box, \'\' if route.get(\'model\') is None else str(route[\'model\']))\n    readable_set_text(gui, ferry_dest_box, str(route[\'destination\']))\n    ferry_update_route_status()\n\n\ndef ferry_delete_route():\n    ferry_event_loop()\n    if not ferry_settings:\n        return\n    key = QtBind.text(gui, ferry_route_box).strip().casefold()\n    data = dict(ferry_settings)\n    data[\'routes\'] = ferry_shared_routes(ferry_settings[\'routes\'])\n    if key in data[\'routes\']:\n        del data[\'routes\'][key]\n        try:\n            ferry_write_shared_routes(data[\'routes\'])\n            ferry_persist(data)\n            log(\'[CaravanRoutes/PartyFerry] Deleted route \' + key)\n        except Exception as error:\n            log(\'[CaravanRoutes/PartyFerry] Delete failed: \' + str(error))\n\n\ndef ferry_sorted_route_keys():\n    keys = list((ferry_settings or {}).get(\'routes\', {}))\n    return sorted(keys, key=lambda key: (0, int(key), key) if key.isdigit() else (1, 0, key))\n\n\ndef ferry_update_route_status():\n    keys = ferry_sorted_route_keys()\n    key = QtBind.text(gui, ferry_route_box).strip().casefold()\n    index = str(keys.index(key) + 1) if key in keys else \'-\'\n    readable_set_text(gui, ferry_route_status, \'Saved: {}/{} ({})\'.format(index, len(keys), key))\n\n\ndef ferry_browse_route(step):\n    ferry_event_loop()\n    keys = ferry_sorted_route_keys()\n    if not keys:\n        log(\'[CaravanRoutes/PartyFerry] No saved routes.\')\n        return\n    key = QtBind.text(gui, ferry_route_box).strip().casefold()\n    index = (keys.index(key) + step) % len(keys) if key in keys else (0 if step > 0 else len(keys) - 1)\n    readable_set_text(gui, ferry_route_box, keys[index])\n    ferry_load_route()\n\n\ndef ferry_previous_route():\n    ferry_browse_route(-1)\n\n\ndef ferry_next_route():\n    ferry_browse_route(1)\n\n\ndef ferry_arm_capture():\n    global ferry_capture_armed, ferry_capture_owner, ferry_capture_npcs, ferry_captured_packet\n    ferry_event_loop()\n    if not ferry_identity:\n        log(\'[CaravanRoutes/PartyFerry] Login first.\')\n        return\n    if ferry_pending:\n        log(\'[CaravanRoutes/PartyFerry] Wait for the current plugin teleport to finish.\')\n        return\n    ferry_capture_owner = ferry_identity\n    ferry_capture_npcs = dict(get_npcs() or {})\n    ferry_captured_packet = None\n    ferry_capture_armed = True\n    log(\'[CaravanRoutes/PartyFerry] Recording ON. Manually select the ferry destination and cross once.\')\n\n\ndef ferry_parse_ferry_packet(data):\n    data = bytes(data)\n    if len(data) != 9:\n        raise ValueError(\'Expected exactly 9 data bytes for opcode 0x705A\')\n    uid, action, destination = struct.unpack(\'<IBI\', data)\n    if action != 2:\n        raise ValueError(\'Expected teleport action 02\')\n    return uid, destination\n\n\ndef ferry_fill_packet(data, npcs):\n    uid, destination = ferry_parse_ferry_packet(data)\n    npc = npcs.get(uid)\n    readable_set_text(gui, ferry_dest_box, str(destination))\n    # Never interpret a runtime UID as a model ID, or keep an unrelated old source.\n    readable_set_text(gui, ferry_npc_box, \'\')\n    readable_set_text(gui, ferry_model_box, \'\')\n    if npc:\n        readable_set_text(gui, ferry_npc_box, npc.get(\'name\', \'\'))\n        if npc.get(\'model\') is not None:\n            readable_set_text(gui, ferry_model_box, str(npc[\'model\']))\n        log(\'[CaravanRoutes/PartyFerry] Packet read: source={} model={} UID={} destination={}. Save route to keep.\'.format(\n            npc.get(\'name\'), npc.get(\'model\'), uid, destination))\n    else:\n        log(\'[CaravanRoutes/PartyFerry] Destination={} read exactly. Source UID={} is not known; fill the correct source NPC/model before saving.\'.format(destination, uid))\n\n\ndef ferry_apply_capture():\n    ferry_event_loop()\n    if not ferry_captured_packet or ferry_capture_owner != ferry_identity:\n        log(\'[CaravanRoutes/PartyFerry] Record a manual ferry trip first.\')\n        return\n    ferry_fill_packet(ferry_captured_packet, ferry_capture_npcs)\n\n\nFERRY_NPC_RANGE = 30\n\n\ndef ferry_scan_npcs():\n    import unicodedata\n\n    character = get_character_data() or {}\n    origin = snapshot_position(character)\n    if not origin or character.get(\'dead\'):\n        log(\'[CaravanRoutes/PartyFerry] Dang nhap va dung canh NPC truoc khi quet.\')\n        return\n\n    candidates = []\n    for uid, npc in (get_npcs() or {}).items():\n        name = npc.get(\'name\')\n        if not isinstance(name, str) or not name.strip() or npc.get(\'region\') != origin[\'region\']:\n            continue\n        try:\n            model = ferry_uint32(npc.get(\'model\'))\n            distance = math.hypot(float(npc[\'x\'])-origin[\'x\'], float(npc[\'y\'])-origin[\'y\'])\n        except (KeyError, TypeError, ValueError):\n            continue\n        if not model or not math.isfinite(distance) or distance > FERRY_NPC_RANGE:\n            continue\n        normalized = unicodedata.normalize(\'NFKD\', name.casefold().replace(\'đ\', \'d\'))\n        normalized = \' \'.join(\'\'.join(c for c in normalized if not unicodedata.combining(c)).split())\n        is_ferry = any(word in normalized for word in (\'ban ve\', \'ferry\'))\n        candidates.append((not is_ferry, distance, name, model, uid))\n\n    if not candidates:\n        log(\'[CaravanRoutes/PartyFerry] Khong tim thay NPC trong {}m. Den gan ben pha roi bam lai.\'.format(FERRY_NPC_RANGE))\n        return\n\n    _, distance, name, model, uid = min(candidates, key=lambda item: item[:2])\n    readable_set_text(gui, ferry_npc_box, name)\n    readable_set_text(gui, ferry_model_box, str(model))\n    log(\'[CaravanRoutes/PartyFerry] Da dien NPC={} | model={} | UID={} | {:.1f}m. Kiem tra ID dich roi luu tuyen.\'.format(\n        name, model, uid, distance))\n\n\ndef ferry_source_uid(route, character):\n    candidates = []\n    for uid, npc in (get_npcs() or {}).items():\n        if route.get(\'model\') is not None:\n            if npc.get(\'model\') != route[\'model\']:\n                continue\n        elif npc.get(\'name\', \'\').casefold() != route[\'npc\'].casefold():\n            continue\n        if npc.get(\'region\') != character.get(\'region\'):\n            continue\n        try:\n            distance = math.hypot(npc[\'x\'] - character[\'x\'], npc[\'y\'] - character[\'y\'])\n            if distance <= FERRY_NPC_RANGE:\n                candidates.append((distance, int(uid)))\n        except (KeyError, TypeError, ValueError):\n            continue\n    return min(candidates)[1] if candidates else None\n\n\ndef ferry_request_crossing(route_key=None, route_data=None, trip_token=None):\n    global ferry_last_request, ferry_pending\n    character = get_character_data()\n    if ferry_capture_armed:\n        log(\'[CaravanRoutes/PartyFerry] Manual recording active; finish the manual trip first.\')\n        return\n    if (not ferry_settings and not trip_token) or not character or character.get(\'dead\'):\n        log(\'[CaravanRoutes/PartyFerry] Cannot teleport: not configured, offline or dead.\')\n        return\n    if time.monotonic() - ferry_last_request < 10:\n        say_throttled(\'ferry_request_cooldown\', \'Qua pha dang cho hoi, doi du 10 giay.\', 10)\n        return\n    route = route_data if route_data is not None else ferry_settings[\'routes\'].get(route_key)\n    if not route:\n        log(\'[CaravanRoutes/PartyFerry] Unknown route: \' + str(route_key))\n        return\n    uid = ferry_source_uid(route, character)\n    if uid is None:\n        say_throttled(\'ferry_no_npc\', \'Khong thay NPC nguon trong {}m. Kiem tra ben pha.\'.format(FERRY_NPC_RANGE), 15)\n        return\n    ferry_last_request = time.monotonic()\n    if follow_intent and not follow_blocked:\n        pause_trace_for_rejoin(\'dang qua pha\',delay=10,hold=True)\n    try:\n        inject_joymax(0x7045, struct.pack(\'<I\', uid), False)\n        ferry_pending = (time.monotonic() + 2.0, ferry_config_identity(), uid, route[\'destination\'], trip_token)\n        log(\'[CaravanRoutes/PartyFerry] NPC selected UID={}; teleport scheduled in 2s.\'.format(uid))\n    except Exception as error:\n        log(\'[CaravanRoutes/PartyFerry] NPC selection failed: \' + str(error))\n\n\ndef ferry_process_pending():\n    global ferry_pending\n    if not ferry_pending or time.monotonic() < ferry_pending[0]:\n        return\n    _, owner, uid, destination, trip_token = ferry_pending\n    ferry_pending = None\n    character = get_character_data()\n    if owner != ferry_config_identity() or not character or character.get(\'dead\') or not get_party():\n        log(\'[CaravanRoutes/PartyFerry] Cancelled: character/party changed or character died.\')\n        return\n    npc = (get_npcs() or {}).get(uid)\n    if not npc or npc.get(\'region\') != character.get(\'region\'):\n        log(\'[CaravanRoutes/PartyFerry] Cancelled: NPC no longer nearby.\')\n        return\n    if math.hypot(npc.get(\'x\', float(\'inf\')) - character[\'x\'],\n                  npc.get(\'y\', float(\'inf\')) - character[\'y\']) > FERRY_NPC_RANGE:\n        log(\'[CaravanRoutes/PartyFerry] Cancelled: moved too far from NPC.\')\n        return\n    try:\n        packet = struct.pack(\'<IBI\', uid, 2, destination)\n        origin = snapshot_position(character)\n        if trip_token and not origin:\n            return\n        if trip_token:\n            route_requests[trip_token].update(sent=True, origin=origin)\n        # Arm before injection because phBot may publish the transport event immediately.\n        previous_grace = ferry_transport_grace\n        globals()[\'ferry_transport_grace\'] = time.monotonic() + 3\n        if inject_joymax(0x705A, packet, False) is False:\n            globals()[\'ferry_transport_grace\'] = previous_grace\n            if trip_token:\n                route_requests[trip_token][\'sent\'] = False\n            return\n        log(\'[CaravanRoutes/PartyFerry] Teleport request sent: destination={}. Awaiting server.\'.format(destination))\n    except Exception as error:\n        log(\'[CaravanRoutes/PartyFerry] Teleport send failed: \' + str(error))\n\n\ndef ferry_teleported():\n    global ferry_pending\n    ferry_pending = None\n\n\ndef ferry_disconnected():\n    global ferry_pending\n    ferry_pending = None\n\n\n\ndef ferry_broadcast_route(channel, route):\n    global ferry_last_broadcast\n    if time.monotonic() - ferry_last_broadcast < 10:\n        say_throttled(\'ferry_call_cooldown\', \'Da gui lenh qua pha, doi du 10 giay truoc khi goi lai.\', 10)\n        return\n    # Short ASCII transport for ordinary Party/All chat. No follower configuration.\n    payload = [route.get(\'model\'), \'\' if route.get(\'model\') is not None else route[\'npc\'],\n               route[\'destination\']]\n    message = ferry_WIRE_PREFIX + base64.b64encode(\n        json.dumps(payload, ensure_ascii=False, separators=(\',\', \':\')).encode(\'utf-8\')).decode(\'ascii\')\n    if len(message) > 120:\n        log(\'[CaravanRoutes/PartyFerry] Route message too long. Use NPC model ID instead of name.\')\n        return\n    ferry_last_broadcast = time.monotonic()\n    send = phBotChat.Party if channel == 4 else phBotChat.All\n    if send(message):\n        log(\'[CaravanRoutes/PartyFerry] Leader broadcast route to party members.\')\n        if channel == 4:\n            ferry_request_crossing(route_data=route)\n    else:\n        ferry_last_broadcast = float(\'-inf\')\n        log(\'[CaravanRoutes/PartyFerry] Route broadcast failed.\')\n\n\ndef ferry_sender_allowed(player, value):\n    is_self = ferry_is_own_name(player)\n    allowed = ferry_leader_names(value)\n    sender_names = {ferry_normalize_name(player)}\n    if is_self:\n        sender_names.update(ferry_own_names())\n    else:\n        member = resolve_follow_target(player)\n        if member:\n            sender_names.update(ferry_normalize_name(member.get(key)) for key in (\'name\', \'job_name\'))\n    return bool(allowed & sender_names)\n\n\ndef ferry_handle_chat(t, player, msg):\n    ferry_event_loop()\n    if not ferry_settings or not ferry_identity or t not in (1, 4):\n        return\n    if not isinstance(msg, str) or not isinstance(player, str):\n        return\n    is_self = ferry_is_own_name(player)\n    if not ferry_sender_allowed(player, ferry_effective_leader()):\n        return\n    party = get_party() or {}\n    if not party:\n        return\n    if not is_self and not any(ferry_normalize_name(member.get(\'name\')) == ferry_normalize_name(player)\n                               or ferry_normalize_name(member.get(\'job_name\')) == ferry_normalize_name(player)\n                               for member in party.values()):\n        return\n    if msg.startswith(ferry_WIRE_PREFIX):\n        # Leader handles its own local crossing in broadcast_route, avoiding echoes.\n        if is_self:\n            return\n        try:\n            if len(msg) > 120:\n                raise ValueError(\'Route message too long\')\n            payload = json.loads(base64.b64decode(msg[len(ferry_WIRE_PREFIX):], validate=True).decode(\'utf-8\'))\n            if not isinstance(payload, list) or len(payload) != 3:\n                raise ValueError(\'Invalid route data\')\n            model, npc, destination = payload\n            route = {\'model\': None if model is None else ferry_uint32(model),\n                     \'npc\': npc, \'destination\': ferry_uint32(destination), \'command\': \'received\'}\n            ferry_validate_route(\'received\', route)\n            log(\'[CaravanRoutes/PartyFerry] Received route from leader; destination=\' + str(destination))\n            ferry_request_crossing(route_data=route)\n        except (ValueError, TypeError, UnicodeError) as error:\n            log(\'[CaravanRoutes/PartyFerry] Invalid route message: \' + str(error))\n        return\n    # Only the leader interprets human-readable commands and knows the routes.\n    if not is_self:\n        return\n    text = msg.strip().casefold()\n    matches = [route for route in ferry_settings[\'routes\'].values()\n               if text == route[\'command\'].strip().casefold()]\n    if len(matches) == 1:\n        ferry_broadcast_route(t, matches[0])\n\n\ndef ferry_decode_chat_string(data, offset):\n    if len(data) < offset + 2:\n        raise ValueError(\'Short chat packet\')\n    size = struct.unpack_from(\'<H\', data, offset)[0]\n    start = offset + 2\n    if len(data) != start + size:\n        raise ValueError(\'Unsupported chat packet layout\')\n    raw = data[start:start + size]\n    try:\n        return raw.decode(\'utf-8\')\n    except UnicodeDecodeError:\n        return raw.decode(\'cp1258\')\n\n\ndef ferry_handle_silkroad(opcode, data):\n    global ferry_captured_packet, ferry_capture_armed\n    if opcode == 0x705A and ferry_capture_armed and ferry_capture_owner == ferry_config_identity():\n        try:\n            uid, destination = ferry_parse_ferry_packet(data)\n            ferry_capture_npcs.update(get_npcs() or {})\n            ferry_captured_packet = bytes(data)\n            ferry_capture_armed = False\n            log(\'[CaravanRoutes/PartyFerry] Recorded request UID={} destination={}. After confirming arrival, click Use recorded packet.\'.format(uid, destination))\n        except (ValueError, TypeError) as error:\n            log(\'[CaravanRoutes/PartyFerry] Cannot record packet: \' + str(error))\n    # Standard SRO outgoing chat: type:u8, sequence:u8, message:string16.\n    # The leader may not receive a handle_chat echo for its own typed message.\n    if opcode == 0x7025 and len(data) >= 4 and data[0] in (1, 4):\n        ferry_event_loop()\n        if ferry_settings and ferry_identity and ferry_owns_leader_field(ferry_effective_leader()):\n            try:\n                ferry_handle_chat(data[0], (get_character_data() or {}).get(\'name\', \'\'), ferry_decode_chat_string(data, 2))\n            except (ValueError, UnicodeError):\n                log(\'[CaravanRoutes/PartyFerry] Unsupported outgoing chat format; send the configured command through phBot Party chat.\')\n    return True\n\n\ndef ferry_handle_joymax(opcode, data):\n    # Standard received chat fallback when handle_chat omits the sender name.\n    # Party carries sender:string16; All carries sender UID:u32.\n    if opcode != 0x3026 or not data or data[0] not in (1, 4):\n        return True\n    try:\n        t = data[0]\n        if t == 4:\n            size = struct.unpack_from(\'<H\', data, 1)[0]\n            end = 3 + size\n            player = bytes(data[3:end]).decode(\'ascii\')\n            msg = ferry_decode_chat_string(data, end)\n        else:\n            uid = struct.unpack_from(\'<I\', data, 1)[0]\n            character = get_character_data() or {}\n            player = character.get(\'name\') if character.get(\'player_id\') == uid else None\n            if not player:\n                player = next((m.get(\'name\') for m in (get_party() or {}).values()\n                               if m.get(\'player_id\') == uid and uid != 0), None)\n            msg = ferry_decode_chat_string(data, 5)\n        if player:\n            ferry_handle_chat(t, player, msg)\n    except (ValueError, UnicodeError, struct.error):\n        pass  # Custom packet layout: retain normal phBot callback handling.\n    return True\n\n\n\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n\n# Shared leader is an optional override; independent settings remain intact.\nshared_identity = None\nshared_check = ferry_control(\'createCheckBox\', 10, 40, gui, \'shared_mode_changed\', \'Dung chung Leader\', 10, 12)\nferry_control(\'createLabel\', 210, 43, gui, \'Leader chung (1 ten):\', 210, 15)\nshared_box = ferry_control(\'createLineEdit\', 350, 38, gui, \'\', 350, 10, 200, 20)\nferry_control(\'createButton\', 570, 36, gui, \'shared_save\', \'Luu Leader chung\', 570, 8)\n\ndef shared_enabled():\n    return True\n\n\ndef shared_leader_text():\n    # Authorization changes only after the main configuration is saved.\n    return (config or {}).get(\'leaders\', \'\')\n\n\ndef ferry_leader_text():\n    return shared_leader_text()\n\n\ndef ferry_stored_leader():\n    return shared_leader_text()\n\n\ndef ferry_effective_leader():\n    # Old member_independent/leader files must never override the main leader.\n    return shared_leader_text()\n\n\ndef shared_path(key):\n    digest = hashlib.sha256(json.dumps(key).encode(\'utf-8\')).hexdigest()\n    return os.path.join(get_config_dir(), \'CaravanRoutes\', \'PartyComeFerry\', digest + \'.json\')\n\ndef shared_load():\n    global shared_identity, ferry_pending, hh_last_leaders\n    shared_identity = come_config_identity()\n    current = (shared_identity, shared_leader_text())\n    if current != globals().get(\'hh_last_leaders\'):\n        ferry_pending = None\n        hh_last_leaders = current\n    if \'hh_leader_notice\' in globals():\n        readable_set_text(gui, hh_leader_notice, \'Leader dùng chung: \' + (shared_leader_text() or \'Chưa lưu ở Chạy buôn\'))\n\n\ndef shared_mode_changed(checked):\n    shared_load()\n\n\ndef shared_save():\n    save_settings()\n    shared_load()\n\n\n\n_caravan_refresh=refresh_optional_controls\n_caravan_event=event_loop\n_caravan_teleported=teleported\n_caravan_disconnected=disconnected\n_caravan_chat=handle_chat\n_caravan_silkroad=handle_silkroad\n_caravan_joymax=handle_joymax\n\ndef save_member_ferry_leaders():\n    say(\'Leader chat và qua phà dùng Leader(s) đã lưu ở Chạy buôn.\')\n\n\n\ndef route_tab_visible():\n    return not (QtBind.isChecked(gui, hunter_check) or QtBind.isChecked(gui, follower_check))\n\n\ndef refresh_optional_controls():\n    # Move widgets only: hidden controls retain their values and saved route selection.\n    global control_view\n    control_view = \'caravan\'\n    hunter = bool(QtBind.isChecked(gui, hunter_check))\n    follower = bool(QtBind.isChecked(gui, follower_check)) and not hunter\n    if hunter or follower:\n        positions = {\n            \'leaders_label\': (8, 51), \'leaders_box\': (100, 48),\n            \'role_label\': (8, 79), \'hunter_check\': (100, 76), \'follower_check\': (210, 76),\n            \'follow_label\': (8, 107), \'follow_box\': (100, 104),\n            \'btn_save_settings\': (100, 168), \'status_label\': (8, 224),\n            \'auto_party_check\': (100, 192),\n            \'btn_activate_follow\': (390, 57), \'btn_stop_following\': (520, 57),\n            \'btn_diagnose_follow\': (390, 95),\n            \'party_list\': (390, 150), \'btn_invite_selected\': (484, 149),\n            \'btn_kick_selected\': (484, 174), \'btn_refresh_party_list\': (484, 199),\n        }\n        if hunter:\n            positions.update(radius_label=(8, 137), escort_20_check=(100, 134),\n                             escort_30_check=(164, 134), escort_50_check=(228, 134))\n        else:\n            positions.update(purchase_label=(8, 135), buy_goods_box=(100, 132),\n                script_check=(8, 158), script_box=(8, 182), btn_choose_script=(179, 181),\n                btn_save_settings=(8, 220), auto_party_check=(125, 220), status_label=(8, 260),\n                transport_stop_check=(390, 50), transport_return_check=(390, 72),\n                transport_recover_check=(390, 94),\n                btn_local_go=(390, 150), btn_local_stop=(470, 150),\n                btn_activate_follow=(390, 177), btn_stop_following=(390, 201),\n                btn_diagnose_follow=(390, 226),\n                party_list=(548, 150), btn_invite_selected=(636, 149),\n                btn_kick_selected=(636, 174), btn_refresh_party_list=(636, 199))\n        for name, (widget, x, y) in ui_registry.items():\n            px, py = positions.get(name, (-2000, y))\n            QtBind.move(gui, widget, px, py)\n    else:\n        for widget, x, y in ui_registry.values():\n            QtBind.move(gui, widget, x, y)\n    readable_set_text(gui, setup_heading,\n        \'<span style="color:#8be9ed;font-size:13px;"><b>\' +\n        (\'Cấu hình bảo tiêu\' if hunter else \'Cấu hình buôn phụ\' if follower else \'Cấu hình Party\') + \'</b></span>\')\n    readable_set_text(gui, hh_controls_heading,\n        \'<span style="color:#8be9ed;font-size:13px;"><b>\' +\n        (\'Theo dõi\' if hunter else \'Điều khiển\' if follower else \'Điều khiển chung\') + \'</b></span>\')\n    QtBind.move(gui, setup_heading, 8, 27)\n    QtBind.move(gui, party_heading, 390 if hunter else 548, 128 if hunter or follower else 27)\n    QtBind.move(gui, transport_heading, 390 if follower else -2000 if hunter else 548, 27 if follower else 137)\n    QtBind.move(gui, hh_controls_heading, 390 if hunter or follower else 8,\n                27 if hunter else 127 if follower else 212)\n    for widget, x, y in globals().get(\'route_widgets\', []):\n        QtBind.move(gui, widget, -2000 if hunter or follower else x, y)\n    for widget, x, y, view in globals().get(\'ferry_widgets\', []):\n        QtBind.move(gui, widget, -2000, y)\n    for view, button, x in globals().get(\'navigation_tabs\', []):\n        QtBind.move(gui, button, -2000, 0)\n    for name in (\'member_ferry_label\', \'member_ferry_leaders\', \'member_ferry_save\'):\n        widget = globals().get(name)\n        if widget is not None:\n            QtBind.move(gui, widget, -2000, 0)\n\n\n\n\ndef show_caravan_view():\n    global control_view\n    control_view=\'caravan\'\n    refresh_optional_controls()\n\n\ndef show_chat_view():\n    global control_view\n    if not route_tab_visible():\n        return\n    control_view=\'chat\'\n    shared_load()\n    come_event_loop()\n    refresh_optional_controls()\n\n\ndef show_ferry_view():\n    global control_view\n    if not route_tab_visible():\n        return\n    control_view=\'ferry\'\n    shared_load()\n    ferry_event_loop()\n    refresh_optional_controls()\n\n\ndef event_loop():\n    route_ferry_arrivals()\n    _caravan_event()\n    load_route_profiles()\n    auto_save_route_profiles()\n    shared_load()\n    come_event_loop()\n    ferry_event_loop()\n\n\ndef teleported():\n    for record in list(route_requests.values()):\n        if record[\'owner\'] == (ferry_config_identity() or ferry_identity) and record[\'sent\'] and not record[\'arrived\']:\n            record[\'spawn\'] = True\n    _caravan_teleported()\n    come_teleported()\n    ferry_teleported()\n\n\ndef disconnected():\n    global shared_identity,ferry_identity,ferry_settings,ferry_capture_armed,ferry_captured_packet\n    global route_crossing\n    route_crossing = None\n    route_requests.clear()\n    _caravan_disconnected()\n    come_disconnected()\n    ferry_disconnected()\n    ferry_identity,ferry_settings=None,None\n    ferry_capture_armed=False\n    ferry_captured_packet=None\n    shared_identity=None\n\n\n# Human-readable reverse commands. Both receive and outgoing hooks may fire.\nreverse_chat_guard={}\nve_relay_guard={}\n\n\ndef handle_reverse_chat(t,player,msg):\n    if t not in (1,4) or not isinstance(msg,str) or msg.strip().upper() not in (\'CHET\',\'CUOI\'):\n        return False\n    if not config or not isinstance(player,str) or not bot.get_party():\n        return True\n    member=resolve_follow_target(player)\n    is_self=norm(player) in own_names()\n    aliases={norm(player)}\n    if isinstance(member,dict):\n        aliases|={norm(member.get(\'name\')),norm(member.get(\'job_name\'))}\n    if is_self:\n        aliases|=own_names()\n    if not (member or is_self) or not aliases & come_get_leaders():\n        return True\n    now=time.monotonic()\n    if now<reverse_chat_guard.get(identity,float(\'-inf\')):\n        return True\n    command=msg.strip().upper()\n    character=bot.get_character_data() or {}\n    if not character or character.get(\'dead\'):\n        say(command+\': nhan vat phai online va con song de dung cuon nguoc.\')\n        return True\n    if return_request or recovery:\n        say(command+\': dang ve thanh/khoi phuc; doi hoan tat roi gui lai.\')\n        return True\n    if not callable(getattr(bot,\'reverse_return\',None)):\n        say(command+\': phBot thieu API reverse_return.\')\n        return True\n    # Reserve before invoking the API to block synchronous own-chat echoes.\n    reverse_chat_guard[identity]=now+30\n    try:\n        accepted=bot.reverse_return(1 if command==\'CHET\' else 0,\'\')\n    except Exception as error:\n        accepted=False\n        say(command+\': loi dung cuon nguoc: \'+str(error))\n    if accepted:\n        pause_trace_for_rejoin(\'lenh \'+command,delay=30,hold=True)\n        say(command+\': da yeu cau dung cuon nguoc ve \'+(\'diem chet\' if command==\'CHET\' else \'diem dung bua ve thanh gan nhat\')+\' cua acc nay; cho server xac nhan.\')\n    else:\n        reverse_chat_guard[identity]=now+3\n        say(command+\': khong dung duoc cuon nguoc; kiem tra cuon va dieu kien server.\')\n    return True\n\n\nPARTY_ACTIONS = {\'MUA\', \'BAN\', \'BÁN\', \'THEO\', \'DUNG\', \'DỪNG\'}\nparty_action_recent = {}\n\n\ndef party_trade_npc(leader, required_uid=None):\n    character = bot.get_character_data() or {}\n    member = character if norm(leader) in own_names() else resolve_follow_target(leader)\n    if not member or (member is not character and not position_usable(member, character)):\n        raise ValueError(\'Chua thay Leader gan acc nay.\')\n    if math.hypot(float(member[\'x\'])-character[\'x\'], float(member[\'y\'])-character[\'y\']) > 40:\n        raise ValueError(\'Can dung trong 40m quanh Leader.\')\n    candidates = []\n    for uid, npc in (bot.get_npcs() or {}).items():\n        if required_uid is not None and uid != required_uid:\n            continue\n        name = (str(npc.get(\'servername\', \'\')) + \' \' + str(npc.get(\'name\', \'\'))).casefold()\n        if not any(word in name for word in (\'_special\', \'_trade\', \'specialty\', \'đặc sản\', \'dac san\', \'thương nhân\', \'thuong nhan\')):\n            continue\n        if npc.get(\'region\', character.get(\'region\')) != character.get(\'region\'):\n            continue\n        try:\n            point = (float(npc[\'x\']), float(npc[\'y\']), float(npc.get(\'z\') or 0))\n            distance = math.hypot(point[0]-character[\'x\'], point[1]-character[\'y\'])\n            leader_distance = math.hypot(point[0]-float(member[\'x\']), point[1]-float(member[\'y\']))\n        except (KeyError, TypeError, ValueError):\n            continue\n        if distance <= 40 and leader_distance <= 40:\n            candidates.append((distance, uid, point))\n    if not candidates:\n        raise ValueError(\'Khong thay NPC thuong nhan trong 40m quanh acc va Leader.\')\n    _, uid, point = min(candidates)\n    return uid, point\n\n\ndef start_party_trade(command, player, npc=None):\n    global active, follower_state\n    npc_uid, point = npc if npc is not None else party_trade_npc(player)\n    region = (bot.get_character_data() or {}).get(\'region\')\n    if command == \'MUA\' and region is None:\n        raise ValueError(\'Chua doc duoc khu cua NPC mua hang.\')\n    stop_owned()\n    enable_following()\n    follower_state = {\'phase\': \'chat_npc\', \'chat_trade\': command, \'chat_leader\': player,\n                      \'chat_npc_uid\': npc_uid, \'chat_npc_point\': point, \'chat_npc_region\': region,\n                      \'purchased\': False, \'mount_tries\': 0,\n                      \'deadline\': time.monotonic() + 45}\n    active = True\n    say(command + \': dang den NPC gan Leader.\')\n\n\ndef handle_party_action(channel, player, message):\n    global standalone_follow\n    command = message.strip().upper()\n    if command not in PARTY_ACTIONS:\n        return False\n    trade_command = command in (\'MUA\', \'BAN\', \'BÁN\')\n    if channel != 4:\n        if trade_command:\n            say_throttled(\'trade_chat_channel\', \'{}: nhan chat tu {} tren kenh {}; hay dung chat Party.\'.format(command, player, channel), 5)\n        return False\n    if not config or not bot.get_party() or not party_member(player) or not trusted_leader(player):\n        if trade_command:\n            if not config:\n                reason = \'acc nay chua Luu cau hinh\'\n            elif not bot.get_party() or not party_member(player):\n                reason = \'phBot chua xac nhan nguoi gui cung Party\'\n            else:\n                reason = \'nguoi gui chua co trong danh sach Leader da luu\'\n            say_throttled(\'trade_chat_auth\', \'{} tu {}: {}.\'.format(command, player, reason), 5)\n        return True\n    if trade_command and config[\'hunter\']:\n        say_throttled(\'trade_chat_hunter\', \'{} tu {}: acc dang luu vai tro Bao tieu.\'.format(command, player), 5)\n        return True\n    command = {\'BÁN\': \'BAN\', \'DỪNG\': \'DUNG\'}.get(command, command)\n    key = (identity, command)\n    now = time.monotonic()\n    if now - party_action_recent.get(key, float(\'-inf\')) < 3:\n        return True\n    party_action_recent[key] = now\n    try:\n        if command == \'DUNG\':\n            execute(\'STOP\')\n            stop_following()\n        elif command == \'THEO\':\n            if norm(player) not in own_names():\n                if follower_state or finish_context or recovery or route_crossing:\n                    raise ValueError(\'Acc dang mua, ban, qua pha hoac cuu hang.\')\n                stop_owned()\n                enable_following()\n                standalone_follow = True\n                start_follow_target(player)\n        elif not config[\'hunter\']:\n            if (follower_state or finish_context or recovery or convoy_controller or route_crossing\n                    or (merchant_step and not merchant_step.get(\'direct\'))):\n                raise ValueError(\'Acc dang xu ly giao dich, lenh tuyen, pha hoac cuu hang.\')\n            if command == \'BAN\' and not finish_transport():\n                raise ValueError(\'Khong thay thu van tai de ban hang.\')\n            start_party_trade(command, player)\n    except (ValueError, OSError, KeyError, TypeError) as error:\n        say(command + \': \' + str(error))\n    return True\n\n\ndef handle_chat(t,player,msg):\n    load_identity()\n    shared_load()\n    come_event_loop()\n    if handle_party_action(t,player,msg) or route_ferry_chat(t,player,msg) or handle_reverse_chat(t,player,msg):\n        return\n    _caravan_chat(t,player,msg)\n    ferry_handle_chat(t,player,msg)\n\n\ndef handle_silkroad(opcode,data):\n    _caravan_silkroad(opcode,data)\n    if opcode==0x7025 and len(data)>=4 and data[0] in (1,4):\n        try:\n            message=ferry_decode_chat_string(data,2)\n            if \' \'.join(message.upper().split()) in PARTY_ACTIONS | {\'VE\',\'CHET\',\'CUOI\',\'VE BT\',\'CUOI BT\'}:\n                load_identity()\n                shared_load()\n                come_event_loop()\n                player=(bot.get_character_data() or {}).get(\'name\',\'\')\n                if not handle_party_action(data[0],player,message) and not handle_reverse_chat(data[0],player,message):\n                    come_handle_chat(data[0],player,message)\n        except (ValueError,UnicodeError,struct.error):\n            pass\n    return ferry_handle_silkroad(opcode,data)\n\n\ndef handle_joymax(opcode,data):\n    _caravan_joymax(opcode,data)\n    if opcode==0x3026 and data and data[0] in (1,2,4):\n        try:\n            channel=data[0]\n            if channel in (2,4):\n                player,end=decode_control_chat_string(data,1)\n                message,_=decode_control_chat_string(data,end)\n            else:\n                uid=struct.unpack_from(\'<I\',data,1)[0]\n                character=bot.get_character_data() or {}\n                player=character.get(\'name\') if uid and character.get(\'player_id\')==uid else None\n                if not player:\n                    player=next((m.get(\'name\') or m.get(\'job_name\') for m in (bot.get_party() or {}).values() if uid and m.get(\'player_id\')==uid),None)\n                message,_=decode_control_chat_string(data,5)\n            if player and (\' \'.join(message.upper().split()) in PARTY_ACTIONS | {\'VE\',\'CHET\',\'CUOI\',\'VE BT\',\'CUOI BT\',\'GOI BT\'} or message.startswith((\'!CRB \', \'!CRF \', \'!CRW \', \'!CRPT \', \'!CRPOS \', \'!CRCALL \'))):\n                handle_chat(channel,player,message)\n        except (ValueError,UnicodeError,struct.error,TypeError):\n            pass  # Unknown server layout: retain normal callback, never hide chat.\n    return ferry_handle_joymax(opcode,data)\n\n\ndef decode_control_chat_string(data,offset):\n    if offset+2>len(data):\n        raise ValueError(\'short chat header\')\n    length=struct.unpack_from(\'<H\',data,offset)[0]\n    end=offset+2+length\n    if end>len(data):\n        raise ValueError(\'short chat string\')\n    value=bytes(data[offset+2:end]).decode(\'utf-8\')\n    if \'\\x00\' in value:\n        raise ValueError(\'unsupported chat encoding\')\n    return value,end\n\n\n# Visible command reference and direct controls; reuse existing command handlers.\ndef chat_panel_control(kind,x,y,*args):\n    widget=readable_label(*args) if kind==\'createLabel\' else getattr(QtBind,kind)(*args)\n    ferry_widgets.append((widget,x,y,\'chat\'))\n    QtBind.move(gui,widget,-2000,y)\n    return widget\n\nchat_panel_control(\'createLabel\',305,137,gui,\'VE: dung bua ve thanh (Party: ca nhom).\',305,137)\nchat_panel_control(\'createLabel\',305,162,gui,\'CHET: cuon nguoc ve diem chet cua moi acc.\',305,162)\nchat_panel_control(\'createLabel\',305,197,gui,\'CUOI: cuon nguoc ve diem dung bua ve gan nhat.\',305,197)\nchat_panel_control(\'createLabel\',305,222,gui,\'Pha: !pha 1 .. !pha 8 (mục Dịch Chuyển / Nạp đủ phà).\',305,222)\nchat_panel_control(\'createLabel\',305,247,gui,\'CHET / CUOI: Leader chat Party; moi acc can cuon.\',305,247)\nchat_panel_control(\'createLabel\',305,272,gui,\'Party MUA / BAN: Leader va NPC trong 40m.\',305,272)\nchat_panel_control(\'createLabel\',305,297,gui,\'Party THEO / DUNG: bat Trace / dung ca doi.\',305,297)\n\nchat_panel_control(\'createLabel\',305,104,gui,\'<span style="color:#63d9df;font-size:13px;"><b>Lệnh dùng trong Party</b></span>\',305,104)\nferry_control(\'createLabel\', 714, 72, gui, \'<span style="color:#63d9df;font-size:13px;"><b>Thiết lập tuyến phà</b></span>\', 714, 72)\nferry_control(\'createLabel\', 714, 105, gui, \'1. Chọn số tuyến và kiểm tra NPC.\', 714, 105)\nferry_control(\'createLabel\', 714, 132, gui, \'2. Kiểm tra mã đích, rồi Lưu tuyến.\', 714, 132)\nferry_control(\'createLabel\', 714, 159, gui, \'3. Leader chat !pha 1 .. !pha 8 trong Party.\', 714, 159)\n\n# Route presets and synchronized ferry steps.\nroute_slots = {}\nroute_widgets = []\nroute_owner = None\nroute_backups = {}\nroute_saved_form = None\nroute_save_after = 0\nroute_selected = None\nroute_switch_requested = False\nroute_ui_busy = False\nroute_crossing = None\nroute_requests = {}\nROUTE_FERRY_PREFIX = \'!CRF \'\n\n\ndef route_profile_path():\n    return path_for(identity)[:-5] + \'.routes.json\'\n\n\ndef load_route_profiles():\n    global route_owner, route_selected, route_ui_busy, route_backups, route_saved_form, route_switch_requested\n    if route_owner == identity:\n        return\n    route_switch_requested = False\n    route_owner, route_selected, route_ui_busy = identity, None, True\n    data = {}\n    try:\n        if identity:\n            with open(route_profile_path(), encoding=\'utf-8\') as stream:\n                data = json.load(stream)\n        if not isinstance(data, dict):\n            data = {}\n    except (OSError, ValueError):\n        pass\n    backups = data.get(\'backups\', {})\n    route_backups = backups if isinstance(backups, dict) else {}\n    try:\n        for key, (check, field) in route_slots.items():\n            value = data.get(key, \'\')\n            readable_set_text(gui, field, script_display_name(value) if isinstance(value, str) else \'\')\n            QtBind.setChecked(gui, check, False)\n        # Older profiles used null (or no profile) to select the main script.\n        key = data.get(\'selected\')\n        if key is None or key == \'main\':\n            route_selected = \'main\'\n        if key in route_slots and QtBind.text(gui, route_slots[key][1]).strip():\n            route_selected = key\n            QtBind.setChecked(gui, route_slots[key][0], True)\n        QtBind.setChecked(gui, script_check, route_selected == \'main\')\n    finally:\n        route_ui_busy = False\n    route_saved_form = route_form()\n\n\ndef select_main_script(checked):\n    select_route_profile(\'main\', checked)\n\n\ndef select_route_profile(key, checked):\n    global route_selected, route_ui_busy, route_switch_requested\n    if route_ui_busy:\n        return\n    load_route_profiles()\n    if active or recovery or loop_pending or loop_return:\n        route_ui_busy = True\n        try:\n            check = script_check if key == \'main\' else route_slots[key][0]\n            QtBind.setChecked(gui, check, key == route_selected)\n        finally:\n            route_ui_busy = False\n        say(\'Tam dung chuyen truoc khi doi huong.\')\n        return\n    if not checked and key != route_selected:\n        return\n    if checked and key != route_selected:\n        route_switch_requested = True\n    route_selected = key if checked else None\n    route_ui_busy = True\n    try:\n        QtBind.setChecked(gui, script_check, route_selected == \'main\')\n        for slot, (check, _) in route_slots.items():\n            QtBind.setChecked(gui, check, slot == route_selected)\n    finally:\n        route_ui_busy = False\n    readable_set_text(gui, step_box, \'0\')\n\n\ndef choose_route_profile_file():\n    if route_selected is None or active or recovery or loop_pending or loop_return:\n        say(\'Tam dung va tich mot huong truoc khi chon TXT.\')\n        return\n    if route_selected == \'main\':\n        choose_script()\n        return\n    selected = pick_script_file(next((d for d in script_directories() if os.path.isdir(d)), BASE))\n    if selected:\n        readable_set_text(gui, route_slots[route_selected][1], short_script_name(selected))\n        save_route_profiles()\n\n\ndef resolve_route_script(key):\n    value = QtBind.text(gui, route_slots[key][1]).strip()\n    try:\n        return resolve_script_text(value)\n    except ValueError:\n        backup = route_backups.get(key)\n        if isinstance(backup, dict) and script_display_name(backup.get(\'source\')) == script_display_name(value):\n            filename = backup.get(\'file\', \'\')\n            if isinstance(filename, str) and len(filename) == 68 and filename.endswith(\'.txt\') and all(c in \'0123456789abcdef\' for c in filename[:-4]):\n                path = os.path.join(route_profile_path()[:-5] + \'-scripts\', filename)\n                if os.path.isfile(path):\n                    return path\n        raise\n\n\ndef route_form():\n    data = {key: QtBind.text(gui, field).strip() for key, (_, field) in route_slots.items()}\n    data[\'selected\'] = route_selected or \'\'\n    return data\n\n\ndef auto_save_route_profiles():\n    global route_save_after\n    if not identity or route_owner != identity or route_ui_busy or active or recovery or loop_pending or loop_return:\n        return\n    now = time.monotonic()\n    if now < route_save_after:\n        return\n    route_save_after = now + 2\n    if route_form() != route_saved_form:\n        save_route_profiles(automatic=True)\n\n\ndef save_route_profiles(automatic=False):\n    global route_backups, route_saved_form\n    load_identity()\n    load_route_profiles()\n    if not identity or active or recovery or loop_pending or loop_return:\n        if not automatic:\n            say(\'Dang nhap va tam dung chuyen truoc khi luu script.\')\n        return\n    data = route_form()\n    backups = {}\n    missing = []\n    path = route_profile_path()\n    folder = path[:-5] + \'-scripts\'\n    try:\n        os.makedirs(folder, exist_ok=True)\n        for key in route_slots:\n            if not data[key]:\n                continue\n            try:\n                with open(resolve_route_script(key), \'rb\') as stream:\n                    content = stream.read()\n            except (OSError, ValueError):\n                missing.append(key)\n                continue\n            filename = hashlib.sha256(content).hexdigest()+\'.txt\'\n            backup_path = os.path.join(folder, filename)\n            if not os.path.isfile(backup_path):\n                with open(backup_path+\'.tmp\', \'wb\') as stream:\n                    stream.write(content)\n                os.replace(backup_path+\'.tmp\', backup_path)\n            backups[key] = {\'source\': data[key], \'file\': filename}\n        with open(path+\'.tmp\', \'w\', encoding=\'utf-8\') as stream:\n            json.dump(dict(data, backups=backups), stream, ensure_ascii=False, indent=2)\n        os.replace(path+\'.tmp\', path)\n        route_backups = backups\n        route_saved_form = data\n        if not automatic:\n            say(\'Da luu {} script va huong dang tich cho nhan vat nay.\'.format(len(backups)))\n        if missing:\n            say(\'Da luu ten file, chua sao luu duoc TXT o o: \'+\', \'.join(missing))\n    except (OSError, ValueError) as error:\n        say_throttled(\'route_save_error\', \'Luu script that bai: \'+str(error))\n\n\ndef show_route_view():\n    global control_view\n    load_identity()\n    if not route_tab_visible():\n        return\n    load_route_profiles()\n    control_view = \'routes\'\n    refresh_optional_controls()\n\n\ndef ferry_step(line):\n    command, sep, key = line.partition(\',\')\n    if command.strip().casefold() != \'ferry\':\n        return None\n    key = key.strip()\n    if not sep or not key or \',\' in key or len(key.split()) != 1:\n        raise ValueError(\'Dung cu phap ferry,<ma pha da luu>\')\n    return key\n\n\ndef validate_route_ferry_steps(lines):\n    if config and (config.get(\'hunter\') or config.get(\'follower\')):\n        return\n    routes = (ferry_settings or {}).get(\'routes\', {})\n    if ferry_identity and ferry_settings is not None:\n        routes = ferry_shared_routes(routes)\n        ferry_settings[\'routes\'] = routes\n    for number, line in enumerate(lines, 1):\n        key = ferry_step(line)\n        if key and key not in routes:\n            raise ValueError(\'Buoc {}: chua luu ma pha {} trong Dich Chuyen.\'.format(number, key))\n        if route_selected in route_slots and line.partition(\',\')[0].strip().casefold() == \'teleport\':\n            raise ValueError(\'Buoc {}: doi teleport qua pha thanh ferry,<ma pha da luu>.\'.format(number))\n\n\ndef route_party_names():\n    return {norm(member.get(\'name\') or member.get(\'job_name\'))\n            for member in (bot.get_party() or {}).values()} - own_names() - {\'\'}\n\n\ndef route_ferry_request(token, route, leader):\n    record = route_requests.setdefault(token, {\n        \'owner\': ferry_config_identity(), \'leader\': leader, \'sent\': False, \'arrived\': False,\n    })\n    if record[\'owner\'] != ferry_config_identity() or record[\'leader\'] != leader:\n        return\n    if record[\'arrived\']:\n        if leader:\n            control_party(ROUTE_FERRY_PREFIX+token+\' OK\')\n        return\n    if not record[\'sent\'] and not ferry_pending:\n        ferry_request_crossing(route_data=route, trip_token=token)\n\n\ndef route_ferry_chat(channel, player, message):\n    if not isinstance(message, str) or not message.startswith(ROUTE_FERRY_PREFIX):\n        return False\n    if channel != 4 or not config or not party_member(player) or norm(player) in own_names():\n        return True\n    fields = message.split()\n    if len(fields) != 3 or len(fields[1]) != 12 or any(c not in \'0123456789abcdef\' for c in fields[1]):\n        return True\n    _, token, payload = fields\n    if payload == \'OK\':\n        if route_crossing and route_crossing[\'owner\'] == identity and token == route_crossing[\'token\']:\n            route_crossing[\'arrived\'].add(convoy_name(player))\n        return True\n    if config and (config[\'hunter\'] or config.get(\'follower\')) and (ferry_settings or {}).get(\'member_independent\'):\n        allowed = ferry_sender_allowed(player, ferry_effective_leader())\n    else:\n        allowed = trusted_leader(player)\n    if not allowed or len(message) > 120:\n        return True\n    try:\n        model, npc, destination = json.loads(base64.b64decode(payload, validate=True).decode(\'utf-8\'))\n        route = {\'model\': None if model is None else ferry_uint32(model), \'npc\': npc,\n                 \'destination\': ferry_uint32(destination), \'command\': \'route\'}\n        ferry_validate_route(\'route\', route)\n        route_ferry_request(token, route, convoy_name(player))\n    except (ValueError, TypeError, UnicodeError):\n        say_throttled(\'route_ferry_invalid\', \'Lenh pha tu Leader khong hop le.\')\n    return True\n\n\ndef route_ferry_arrivals():\n    current = snapshot_position(bot.get_character_data() or {})\n    if not current:\n        return\n    for token, record in list(route_requests.items()):\n        if record[\'owner\'] != ferry_config_identity() or not record.get(\'spawn\') or record[\'arrived\']:\n            continue\n        origin = record[\'origin\']\n        if current[\'region\'] != origin[\'region\'] or math.hypot(current[\'x\']-origin[\'x\'], current[\'y\']-origin[\'y\']) > 10:\n            record[\'arrived\'] = True\n            if record[\'leader\']:\n                control_party(ROUTE_FERRY_PREFIX+token+\' OK\')\n\n\ndef route_crossing_matches():\n    return (route_crossing is not None\n            and route_crossing[\'owner\'] == identity\n            and route_crossing[\'index\'] == trip[\'cursor\']\n            and route_crossing[\'path\'] == trip[\'path\']\n            and route_crossing.get(\'digest\') == trip[\'digest\'])\n\n\ndef route_ferry_tick(key):\n    global route_crossing, active\n    now = time.monotonic()\n    if not route_crossing_matches():\n        route = (ferry_settings or {}).get(\'routes\', {}).get(key)\n        if not route or not own_names() & names(config[\'leaders\']) or not bot.get_party():\n            active = False\n            say(\'Dung tai pha \'+key+\': can Leader trong Party va ma pha da luu o Dich Chuyen. Sua xong bam GO.\')\n            return\n        if ferry_pending:\n            return\n        if ferry_source_uid(route, bot.get_character_data() or {}) is None:\n            active = False\n            say(\'Dung tai pha \'+key+\': den dung NPC ben xuat phat trong {}m roi bam Tiep Tuc.\'.format(FERRY_NPC_RANGE))\n            return\n        token = uuid.uuid4().hex[:12]\n        payload = [route.get(\'model\'), \'\' if route.get(\'model\') is not None else route[\'npc\'], route[\'destination\']]\n        message = ROUTE_FERRY_PREFIX+token+\' \'+base64.b64encode(json.dumps(payload, separators=(\',\', \':\')).encode()).decode()\n        if len(message) > 120:\n            active = False\n            say(\'Lenh pha qua dai. Luu pha bang Model ID cua NPC.\')\n            return\n        route_crossing = {\'owner\': identity, \'index\': trip[\'cursor\'], \'path\': trip[\'path\'],\n                          \'digest\': trip[\'digest\'], \'token\': token, \'route\': route,\n                          \'message\': message, \'members\': route_party_names(), \'arrived\': set(),\n                          \'next\': now, \'deadline\': now+45}\n        trip[\'uncertain\'] = trip[\'cursor\']+1\n        trip[\'route_ferry_pending\'] = True\n        persist_trip()\n        stop_at_current_position()\n        route_crossing[\'next\'] = now+0.5\n    state = route_crossing\n    waiting = state[\'members\'] - state[\'arrived\']\n    local = route_requests.get(state[\'token\'], {})\n    if local.get(\'arrived\'):\n        state.setdefault(\'leader_arrived_at\', now)\n    wait_expired = local.get(\'arrived\') and now - state[\'leader_arrived_at\'] >= 10\n    if local.get(\'arrived\') and (not waiting or wait_expired):\n        trip[\'cursor\'] += 1\n        trip[\'uncertain\'] = None\n        trip.pop(\'route_ferry_pending\', None)\n        persist_trip()\n        route_crossing = None\n        if waiting:\n            say(\'Leader da qua pha \'+key+\'. Het 10s cho: \'+\', \'.join(sorted(waiting))+\'. Tiep tuc script.\')\n        else:\n            say(\'Ca doi da qua pha \'+key+\'. Tiep tuc script.\')\n        return\n    if not local.get(\'arrived\') and now >= state[\'deadline\']:\n        active = False\n        say(\'Het 45s cho pha \'+key+\'. Con cho: \'+\', \'.join(sorted(waiting | ({\'Leader\'} if not local.get(\'arrived\') else set())))+\'. Kiem tra roi bam GO.\')\n        return\n    set_state(\'Qua pha \'+key+\' | con cho \'+str(len(waiting))+\' thanh vien\')\n    if now >= state[\'next\']:\n        state[\'next\'] = now+5\n        if control_party(state[\'message\']):\n            route_ferry_request(state[\'token\'], state[\'route\'], None)\n\n\ndef selected_has_turnaround():\n    try:\n        with open(selected_script_path(), encoding=\'utf-8-sig\') as stream:\n            lines = [line.strip() for line in stream\n                     if line.strip() and not line.lstrip().startswith((\'#\', \'//\'))]\n    except (OSError, ValueError):\n        return False\n    return bool(lines and lines[-1].casefold().startswith(\'turnaround,\'))\n\n\ndef park_after_turnaround_sale():\n    global convoy_controller, local_sale, completed_sale, active\n    trip[\'cursor\'], trip[\'uncertain\'] = len(trip_lines), None\n    trip.pop(\'turnaround_pending\', None)\n    trip[\'turnaround_parked\'] = True\n    persist_finish(\'done\')\n    convoy_controller = local_sale = completed_sale = None\n    active = False\n    set_state(\'Da ban het - Lap TAT, dung tai diem ban\')\n    say(\'Ca doi da ban het, giu thu. Lap TAT: dung tai diem ban.\')\n\n\ndef route_filename_key(value):\n    value=str(value or \'\').strip().strip(chr(34)).replace(chr(92),\'/\').rsplit(\'/\',1)[-1]\n    return script_display_name(value).casefold()\n\n\ndef resolve_turnaround_target(filename):\n    wanted=route_filename_key(filename)\n    matches = [key for key, (_, field) in route_slots.items()\n               if wanted and route_filename_key(QtBind.text(gui, field)) == wanted]\n    if not matches:\n        raise ValueError(\'Chua gan TXT chieu ve \'+str(filename)+\' vao o Huong 1/2/3. Gan file va Luu tuyen; co hoac khong duoi .txt deu duoc.\')\n    if len(matches) != 1:\n        raise ValueError(\'TXT chieu ve \'+str(filename)+\' bi gan trung o \'+\', \'.join(matches)+\'. Chi giu file nay trong mot o huong.\')\n    slot = matches[0]\n    path = resolve_route_script(slot)\n    with open(path, encoding=\'utf-8-sig\') as stream:\n        lines = [line.strip() for line in stream if line.strip() and not line.lstrip().startswith((\'#\', \'//\'))]\n    validate_route_ferry_steps(lines)\n    if len(lines) < 4 or not walk_point(lines[0]) or lines[1].casefold() != \'oldtrade,spawn\' or not lines[2].casefold().startswith(\'oldtrade,buy,\'):\n        raise ValueError(\'TXT chieu ve can mo dau bang walk, oldtrade,spawn, oldtrade,buy.\')\n    if not reached(walk_point(lines[0])):\n        raise ValueError(\'Chua dung diem mua cua chieu ve; kiem tra hai TXT.\')\n    return {\'slot\': slot, \'path\': path, \'buy\': lines[2]}\n\n\ndef interrupted_turnaround():\n    # prepare_trip has already matched the checkpoint to the selected TXT.\n    # The final uncertain marker also identifies older checkpoints.\n    return (trip[\'cursor\'] == len(trip_lines)-1\n            and trip_lines[-1].casefold().startswith(\'turnaround,\')\n            and (trip.get(\'turnaround_pending\') or trip.get(\'uncertain\') == len(trip_lines)))\n\n\ndef resume_turnaround():\n    if convoy_controller:\n        say(\'Dang cho ca doi ban xong; khong phat lai lenh ban.\')\n        return\n    cursor = trip[\'cursor\']\n    if cursor != len(trip_lines)-1 or not trip_lines[cursor].casefold().startswith(\'turnaround,\'):\n        raise ValueError(\'Moc ban doi chieu khong khop TXT hien tai.\')\n    points = map(walk_point, reversed(trip_lines[:cursor]))\n    endpoint = next((point for point in points if point is not None), None)\n    if endpoint is None or not reached(endpoint):\n        raise ValueError(\'Quay lai diem ban cuoi tuyen, len thu roi bam Tiep Tuc.\')\n    begin_turnaround(trip_lines[cursor].split(\',\', 1)[1].strip())\n\n\ndef begin_turnaround(filename):\n    if not config or not own_names() & names(config[\'leaders\']) or not bot.get_party():\n        raise ValueError(\'Can Leader buon chinh trong Party de ban va doi chieu.\')\n    if trip[\'cursor\'] != len(trip_lines)-1:\n        raise ValueError(\'Dat turnaround o cuoi script.\')\n    if loop_enabled:\n        resolve_turnaround_target(filename)\n    pet = finish_transport()\n    if not pet or not pet.get(\'mounted\'):\n        raise ValueError(\'Can len thu hien tai truoc khi ban doi chieu.\')\n    trip[\'turnaround_pending\'] = True\n    trip[\'uncertain\'] = trip[\'cursor\']+1\n    persist_trip()\n    sell_team(turnaround={\'filename\': filename})\n\n\ndef start_return_follower_buy(player):\n    global local_sale, follower_state, active, follow_override\n    pet = finish_transport()\n    if not pet or transport_goods(pet):\n        raise ValueError(\'Can thu hien tai da ban het hang.\')\n    follow_override = player\n    enable_following()\n    follower_state = {\'phase\': \'mount\', \'purchased\': False, \'mount_tries\': 0,\n                      \'turn_follow\': player, \'deadline\': time.monotonic()+45, \'next_at\': time.monotonic()}\n    local_sale = None\n    active = True\n\n\ndef launch_return_route(context):\n    global convoy_controller, local_sale, completed_sale, trip, merchant_step, active, route_switch_requested\n    target = resolve_turnaround_target(context[\'turnaround\'][\'filename\'])\n    pet = finish_transport()\n    if not pet or not pet.get(\'mounted\') or transport_goods(pet):\n        raise ValueError(\'Leader can thu hien tai da ban het hang va dang cuoi.\')\n    if resolve_route_script(target[\'slot\']) != target[\'path\']:\n        raise ValueError(\'TXT chieu ve da thay doi; kiem tra lai.\')\n    old_trip = trip\n    old_trip[\'cursor\'], old_trip[\'uncertain\'] = len(trip_lines), None\n    old_trip[\'finish_stage\'] = \'done\'\n    old_trip.pop(\'turnaround_pending\', None)\n    persist_trip()\n    select_route_profile(target[\'slot\'], True)\n    route_switch_requested = False\n    if route_selected != target[\'slot\']:\n        raise ValueError(\'Khong chon duoc huong ve; kiem tra trang thai lap.\')\n    save_route_profiles(automatic=True)\n    trip = None\n    prepare_trip()\n    if len(trip_lines) < 3 or trip_lines[2] != target[\'buy\'] or not reached(walk_point(trip_lines[0])):\n        raise ValueError(\'TXT chieu ve da thay doi hoac lech diem mua.\')\n    trip = {key: trip[key] for key in (\'path\', \'digest\')}\n    trip.update(cursor=2, uncertain=3, buy_wait_pending={\'after\': 3})\n    persist_trip()\n    if bot.start_script(target[\'buy\']+\'\\n\') is False:\n        raise ValueError(\'phBot tu choi mua tren thu hien tai.\')\n    convoy_controller = local_sale = completed_sale = None\n    begin_buy_departure()\n    buy_departure[\'expected\'].update(context[\'sellers\']-own_names())\n    buy_departure[\'turn_batch\'] = context[\'batch\']\n    merchant_step = {\'point\': None, \'after\': 3, \'buy_wait\': True}\n    active = True\n    say(\'Da ban ca doi, giu thu, dang mua va doi sang TXT chieu ve.\')\n\n\ndef route_new_start():\n    new_start_changed(True)\n\n\ndef setup_route_view():\n    def widget(kind, x, y, *args):\n        handle = readable_label(gui, args[0], x, y) if kind == \'createLabel\' else getattr(QtBind, kind)(gui, *args, x, y)\n        route_widgets.append((handle, x, y))\n        return handle\n    route_widgets.append((panel_heading(\'Tuyến buôn\', 248, 27), 248, 27))\n    # Three compact columns retain all nine route slots and the same saved keys.\n    # Native fields form each row; no HTML grid that can collapse under phBot.\n    for direction in range(3):\n        widget(\'createLabel\', 350 + direction * 140, 48, \'Hướng \' + str(direction + 1))\n    for city_index, city in enumerate((\'Trường An\', \'Đôn Hoàng\', \'Hoàng Điền\')):\n        y = 69 + city_index * 28\n        widget(\'createLabel\', 248, y + 3, city)\n        for direction in range(3):\n            key = str(city_index * 3 + direction + 1)\n            x = 318 + direction * 140\n            callback = \'route_select_\' + key\n            globals()[callback] = lambda checked, slot=key: select_route_profile(slot, checked)\n            check = widget(\'createCheckBox\', x, y, callback, \'\')\n            field = QtBind.createLineEdit(gui, \'\', x + 18, y, 112, 18)\n            route_widgets.append((field, x + 18, y))\n            route_slots[key] = (check, field)\n    widget(\'createButton\', 318, 151, \'choose_route_profile_file\', \'Chọn TXT\')\n    widget(\'createButton\', 408, 151, \'save_route_profiles\', \'Lưu tuyến\')\n    widget(\'createLabel\', 500, 155, \'Tích ô để chọn hướng chạy.\')\n\n\n\n\nmember_ferry_label = readable_label(gui, \'Leader phà riêng:\', -2000, 260)\nmember_ferry_leaders = QtBind.createLineEdit(gui, \'\', -2000, 257, 183, 20)\nmember_ferry_save = QtBind.createButton(gui, \'save_member_ferry_leaders\', \'Lưu Leader phà\', -2000, 257)\nsetup_route_view()\nsync_loop_checks()\n\nnavigation_tabs = []\nfor view, callback, title, x in (\n    (\'caravan\', \'show_caravan_view\', \'Buôn Theo Party\', 12),\n    (\'routes\', \'show_route_view\', \'Tuyến buôn\', 134),\n    (\'ferry\', \'show_ferry_view\', \'Dịch Chuyển\', 232),\n    (\'chat\', \'show_chat_view\', \'Lệnh Gọi\', 340),\n):\n    button = QtBind.createButton(gui, callback, \'\\u00a0\'+title+\'\\u00a0\', x, 0)\n    navigation_tabs.append((view, button, x))\n\n\ndef apply_button_colors():\n    # The public QtBind API does not guarantee a widget stylesheet setter.\n    colors = [(button, \'#68ADFF\') for _, button, _ in navigation_tabs]\n    colors.extend(((btn_local_stop, \'#FF6565\'), (btn_local_go, \'#FFD453\')))\n    for name in (\'setStyleSheet\', \'setStylesheet\', \'setStyle\'):\n        setter = getattr(QtBind, name, None)\n        if not callable(setter):\n            continue\n        try:\n            for button, color in colors:\n                if setter(gui, button, \'QPushButton { color: \'+color+\'; }\') is False:\n                    raise RuntimeError(\'QtBind rejected the button color\')\n        except Exception:\n            continue\n        return\n    pass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n\napply_button_colors()\nshared_load()\ncome_event_loop()\nferry_event_loop()\nrefresh_optional_controls()\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\nhh_leader_notice = ferry_control(\'createLabel\', 12, 43, gui, \'\', 12, 43)\nshared_load()\nrefresh_optional_controls()\n\n\n# Manual, role-filtered guard recall. Never reverse automatically without CUOI BT.\nbt_recall = None\nbt_command_times = {}\n_bt_original_chat = handle_chat\n_bt_original_event = event_loop\n_bt_original_teleported = teleported\n_bt_original_disconnected = disconnected\n_bt_original_stop = stop_owned\n\n\ndef stop_owned():\n    global bt_recall\n    bt_recall = None\n    return _bt_original_stop()\n\n\ndef bt_normalize(message):\n    return \' \'.join(str(message).upper().split())\n\n\ndef bt_try_reverse(context):\n    if return_request or context[\'phase\'] != \'returned\':\n        return\n    if time.monotonic() < context[\'cast_at\'] + 20:\n        return\n    if not party_member(context[\'leader\']) or not trusted_leader(context[\'leader\']):\n        context[\'cuoi_requested\'] = False\n        say(\'CUOI BT: Leader khong con trong Party/khong duoc phep; chua dung bua.\')\n        return\n    api = getattr(bot, \'reverse_return\', None)\n    if not callable(api):\n        context[\'cuoi_requested\'] = False\n        say(\'CUOI BT: phBot thieu API reverse_return.\')\n        return\n    context.update(phase=\'reversing\', spawn_seen=False, deadline=time.monotonic()+120,\n                   cuoi_requested=False)\n    try:\n        accepted = api(0, \'\')\n    except Exception as error:\n        accepted = False\n        say(\'CUOI BT: \'+str(error))\n    if not accepted:\n        context.update(phase=\'returned\', deadline=None)\n        say(\'CUOI BT: chua dung duoc bua; kiem tra bua dich chuyen va gui lai lenh.\')\n    else:\n        say(\'CUOI BT: da yeu cau quay lai diem vua VE; cho server xac nhan, khong gui trung.\')\n\n\ndef handle_bt_chat(channel, player, message):\n    global bt_recall\n    command = bt_normalize(message)\n    if command not in (\'VE BT\', \'CUOI BT\'):\n        return False\n    # Only Party, only a saved Hunter, only its trusted Leader in the same party.\n    if channel != 4 or not config or not config.get(\'hunter\'):\n        return True\n    if not isinstance(player, str) or not bot.get_party() or not party_member(player) or not trusted_leader(player):\n        return True\n    character = bot.get_character_data() or {}\n    if not character or character.get(\'dead\'):\n        say(command+\': Bao tieu phai online va con song.\')\n        return True\n    now = time.monotonic()\n    key = (identity, command)\n    if now-bt_command_times.get(key, float(\'-inf\')) < 3:\n        return True\n    bt_command_times[key] = now\n    if command == \'VE BT\':\n        if bt_recall and bt_recall[\'owner\'] == identity:\n            say_throttled(\'bt_busy\', \'VE BT: dang xu ly VE/CUOI, khong dung bua trung.\', 5)\n            return True\n        origin = snapshot_position(character)\n        if origin is None:\n            say(\'VE BT: chua doc duoc vi tri Bao tieu.\')\n            return True\n        target = current_follow_target() or player\n        old_loop = loop_enabled\n        set_loop(False)\n        # Clear follow intent before queue_return so the guard stays in town.\n        stop_owned()\n        stopper = getattr(bot, \'stop_bot\', None)\n        if callable(stopper):\n            stopper()\n        try:\n            queue_return()\n        except Exception as error:\n            say(\'VE BT: \'+str(error))\n            return True\n        if not return_request:\n            say(\'VE BT: chua xep duoc lenh ve thanh; kiem tra hoi bua va gui lai.\')\n            return True\n        bt_recall = {\'owner\': identity, \'leader\': player, \'target\': target,\n                     \'origin\': origin, \'old_loop\': old_loop, \'requested_at\': now,\n                     \'phase\': \'returning\', \'cast_at\': None, \'spawn_seen\': False,\n                     \'cuoi_requested\': False, \'deadline\': now+120}\n        say(\'VE BT: chi Bao tieu ve thanh. Cho dich chuyen xong; Leader gui CUOI BT de quay lai.\')\n    else:\n        context = bt_recall\n        if not context or context[\'owner\'] != identity:\n            say(\'CUOI BT: chua co phien VE BT tren acc nay; gui VE BT truoc.\')\n            return True\n        if context[\'phase\'] == \'reversing\':\n            say(\'CUOI BT: dang dich chuyen nguoc; khong dung bua trung.\')\n            return True\n        context[\'cuoi_requested\'] = True\n        if context[\'phase\'] == \'returned\':\n            bt_try_reverse(context)\n        else:\n            say(\'CUOI BT: da nhan lenh; doi VE hoan tat va du 20s tu luc dung bua, roi moi quay lai.\')\n    return True\n\n\ndef bt_recall_tick():\n    global bt_recall, follow_override\n    context = bt_recall\n    if not context:\n        return\n    now = time.monotonic()\n    owner = current_identity()\n    if (owner is not None and owner != context[\'owner\']) or (config and not config.get(\'hunter\')):\n        bt_recall = None\n        return\n    if context.get(\'deadline\') is not None and now >= context[\'deadline\']:\n        stop_owned()\n        say(\'VE/CUOI BT: qua 120s chua xac nhan dich chuyen; da dung, kiem tra bua va nhan vat.\')\n        return\n    if owner is None or not config:\n        return\n    character = bot.get_character_data() or {}\n    if character.get(\'dead\'):\n        stop_owned()\n        say(\'VE/CUOI BT: Bao tieu da chet; da huy phien.\')\n        return\n    if context[\'phase\'] == \'returning\':\n        if context[\'cast_at\'] is None and last_return >= context[\'requested_at\'] and not return_request:\n            context[\'cast_at\'] = last_return\n        if context[\'cast_at\'] is None:\n            if not return_request:\n                bt_recall = None\n                say(\'VE BT: bua ve thanh chua duoc chap nhan; gui lai sau khi kiem tra.\')\n            return\n        current = snapshot_position(character)\n        origin = context[\'origin\']\n        moved = current and (current[\'region\'] != origin[\'region\'] or\n                            math.hypot(current[\'x\']-origin[\'x\'],current[\'y\']-origin[\'y\']) > 2)\n        if context[\'spawn_seen\'] and moved and now >= context[\'cast_at\']+20:\n            context.update(phase=\'returned\', deadline=None)\n            say(\'VE BT: da xac nhan ve thanh; dung cho lenh CUOI BT cua Leader.\')\n    if context[\'phase\'] == \'returned\' and context[\'cuoi_requested\']:\n        bt_try_reverse(context)\n    if context[\'phase\'] == \'reversing\' and context[\'spawn_seen\']:\n        current = snapshot_position(character)\n        origin = context[\'origin\']\n        if current and current[\'region\'] == origin[\'region\'] and math.hypot(current[\'x\']-origin[\'x\'],current[\'y\']-origin[\'y\']) <= 35:\n            bt_recall = None\n            enable_following()\n            follow_override = context[\'target\']\n            set_loop(context[\'old_loop\'])\n            try:\n                start_follow_target(context[\'target\'])\n                say(\'CUOI BT: da quay lai diem cu; tiep tuc theo \'+context[\'target\']+\'.\')\n            except Exception as error:\n                say(\'CUOI BT: da quay lai, chua bam theo duoc: \'+str(error)+\'. Bam Bat dau theo doi de thu lai.\')\n\n\ndef handle_chat(channel, player, message):\n    load_identity()\n    if handle_bt_chat(channel, player, message):\n        return\n    return _bt_original_chat(channel, player, message)\n\n\ndef event_loop():\n    _bt_original_event()\n    bt_recall_tick()\n\n\ndef teleported():\n    if bt_recall and current_identity() in (None, bt_recall[\'owner\']):\n        bt_recall[\'spawn_seen\'] = True\n    _bt_original_teleported()\n    bt_recall_tick()\n\n\ndef disconnected():\n    global bt_recall\n    bt_recall = None\n    bt_command_times.clear()\n    return _bt_original_disconnected()\n\n\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n\n# Trusted private-message handshake works before a Party exists.\nap_state = {\'owner\': None, \'pending\': None, \'accept\': None, \'allow\': {},\n            \'cooldown\': {}, \'seen_invites\': {}, \'next\': 0.0}\n_ap_base_event = event_loop\n_ap_base_chat = handle_chat\n_ap_base_joymax = handle_joymax\n_ap_base_silkroad = handle_silkroad\n_ap_base_disconnected = disconnected\n\n\ndef ap_reset():\n    globals().get(\'_ap_blocked_private\',set()).clear()\n    globals()[\'_ap_last_private\']=None\n    ap_state.update(owner=current_identity(), pending=None, accept=None, allow={},\n                    cooldown={}, seen_invites={}, next=0.0)\n\n\ndef auto_party_changed(checked):\n    ap_reset()\n    if checked:\n        QtBind.setChecked(gui, auto_party_check, False)\n\n\ndef ap_enabled():\n    # Manual invitations; retain automatic acceptance from saved Leaders only.\n    # The old auto_party setting no longer enables private discovery/inviting.\n    return bool(config)\n\n\ndef ap_visible():\n    getter = getattr(bot, \'get_players\', None)\n    try:\n        value = getter() if callable(getter) else None\n        return value if isinstance(value, dict) else {}\n    except Exception:\n        return {}\n\n\ndef ap_aliases(player):\n    return {norm(player.get(key)) for key in (\'name\', \'job_name\')} - {\'\'}\n\n\ndef ap_sender_allowed(sender):\n    aliases = {norm(sender)}\n    for player in ap_visible().values():\n        if norm(sender) in ap_aliases(player):\n            aliases.update(ap_aliases(player))\n    if not aliases & names(config.get(\'leaders\', \'\')):\n        return False\n    # With a specific follow target saved, do not join another allowed leader first.\n    target = config.get(\'follow\', \'\').strip()\n    return not target or bool(aliases & names(target))\n\n\n_ap_last_private = None\n_ap_blocked_private = set()\n\n\ndef ap_private(name, message):\n    return False  # No private Party discovery or handshake messages.\n\n\ndef ap_handle_chat(channel, sender, message):\n    return isinstance(message, str) and message.startswith((\'!CRPT \', \'!CRPOS \'))\n\n\ndef ap_invite_packet(data):\n    # 0x3080 also carries non-party requests. Any new dialog cancels a queued reply.\n    ap_state[\'accept\'] = None\n    if not ap_enabled():\n        return\n    if bot.get_party() or len(data) not in (5, 6) or data[0] not in (2, 3):\n        return\n    uid = struct.unpack_from(\'<I\', data, 1)[0]\n    if uid == 0 or (data[0] == 2 and len(data) != 6) or (len(data) == 6 and data[5] > 7):\n        return\n    now = time.monotonic()\n    fingerprint = bytes(data)\n    if now-ap_state[\'seen_invites\'].get(fingerprint, float(\'-inf\')) < 10:\n        return\n    allowed = ap_state[\'allow\'].get(uid)\n    sender = allowed[\'name\'] if allowed and allowed[\'until\'] >= now else None\n    visible = ap_visible().get(uid) or ap_visible().get(str(uid))\n    if not sender and visible:\n        sender = visible.get(\'name\') or visible.get(\'job_name\')\n    if not sender or not ap_sender_allowed(sender):\n        return\n    if visible and norm(sender) not in ap_aliases(visible):\n        return\n    ap_state[\'accept\'] = {\'uid\': uid, \'sender\': sender, \'due\': now+1,\n                          \'until\': now+8, \'fingerprint\': fingerprint}\n\n\ndef ap_tick():\n    owner = current_identity()\n    if ap_state[\'owner\'] != owner:\n        ap_reset()\n    if not owner or not ap_enabled():\n        ap_state[\'accept\'] = None\n        ap_state[\'pending\'] = None\n        return\n    character = bot.get_character_data() or {}\n    if character.get(\'dead\'):\n        ap_state[\'accept\'] = None\n        ap_state[\'pending\'] = None\n        return\n    now = time.monotonic()\n    for uid in list(ap_state[\'allow\']):\n        if ap_state[\'allow\'][uid][\'until\'] < now:\n            del ap_state[\'allow\'][uid]\n    for fingerprint in list(ap_state[\'seen_invites\']):\n        if now-ap_state[\'seen_invites\'][fingerprint] >= 30:\n            del ap_state[\'seen_invites\'][fingerprint]\n    invitation = ap_state[\'accept\']\n    if invitation:\n        if bot.get_party() or now > invitation[\'until\'] or not ap_sender_allowed(invitation[\'sender\']):\n            ap_state[\'accept\'] = None\n        elif now >= invitation[\'due\']:\n            ap_state[\'accept\'] = None\n            ap_state[\'seen_invites\'][invitation[\'fingerprint\']] = now\n            if bot.inject_joymax(0x3080, b\'\\x01\\x01\', False) is False:\n                say(\'Nhan PT: chua chap nhan duoc loi moi cua \'+invitation[\'sender\']+\'.\')\n            else:\n                say(\'Nhan PT: da chap nhan loi moi cua \'+invitation[\'sender\']+\'; cho server xac nhan.\')\n    return  # Only accept trusted incoming invites; never initiate an invitation.\n\n\ndef handle_chat(channel, player, message):\n    load_identity()\n    if ap_state[\'owner\'] != current_identity():\n        ap_reset()\n    if ap_handle_chat(channel, player, message):\n        return\n    return _ap_base_chat(channel, player, message)\n\n\ndef event_loop():\n    _ap_base_event()\n    ap_tick()\n\n\ndef handle_joymax(opcode, data):\n    result = _ap_base_joymax(opcode, data)\n    if ap_state[\'owner\'] != current_identity():\n        ap_reset()\n    if opcode == 0x3080:\n        ap_invite_packet(data)\n    elif opcode in (0xB060, 0xB062) and data[:1] == b\'\\x02\' and ap_state[\'pending\']:\n        name = ap_state[\'pending\'][\'name\']\n        ap_state[\'cooldown\'][norm(name)] = time.monotonic()+60\n        ap_state[\'next\'] = time.monotonic()+60\n        ap_state[\'pending\'] = None\n        say(\'Tu lap PT: server tu choi moi \'+name+\'; tam dung moi acc nay 60s.\')\n    return result\n\n\ndef handle_silkroad(opcode, data):\n    if opcode == 0x3080:\n        ap_state[\'accept\'] = None  # Manual accept/decline overrides the scheduled answer.\n    return _ap_base_silkroad(opcode, data)\n\n\ndef disconnected():\n    ap_reset()\n    return _ap_base_disconnected()\n\n\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n\n# Nearby discovery: direct API when available, fresh peer position announcements otherwise.\n# Position announcements are self-reported by the other plugin; server validates invitations.\n_ap40_visible_base = ap_visible\n_ap40_private_base = ap_private\n_ap40_chat_base = ap_handle_chat\n_ap40_event_base = event_loop\n_ap40_reset_base = ap_reset\nap40_peers = {}\nap40_beacons = {}\nAP40_RADIUS = 40.0\n\n\ndef ap_reset():\n    ap40_peers.clear();ap40_beacons.clear()\n    return _ap40_reset_base()\n\n\ndef ap40_near(record):\n    character = bot.get_character_data() or {}\n    if not character or record.get(\'dead\'):return False\n    try:\n        x,y=float(record[\'x\']),float(record[\'y\'])\n        if not all(math.isfinite(v) for v in (x,y,float(character[\'x\']),float(character[\'y\']))):return False\n        region=record.get(\'region\',character.get(\'region\'))\n        if region!=character.get(\'region\') and not nearby_outdoor_position(character,dict(record,region=region),AP40_RADIUS):return False\n        return math.hypot(x-float(character[\'x\']),y-float(character[\'y\']))<=AP40_RADIUS\n    except (ValueError,TypeError,KeyError):return False\n\n\ndef ap_visible():\n    visible=dict(_ap40_visible_base())\n    now=time.monotonic()\n    for name,peer in list(ap40_peers.items()):\n        if now-peer[\'at\']>30:\n            del ap40_peers[name];continue\n        uid=peer[\'uid\']\n        if uid not in visible and str(uid) not in visible:\n            visible[uid]=dict(peer,position_source=\'peer\')\n    return visible\n\n\ndef ap_near_uid(uid):\n    visible=ap_visible();record=visible.get(uid,visible.get(str(uid)))\n    return record if record and ap40_near(record) else None\n\n\ndef ap_candidates():\n    return []  # Automatic discovery/scanning removed.\n\n\ndef ap40_position_message():\n    character=bot.get_character_data() or {}\n    uid=character.get(\'player_id\');region=character.get(\'region\')\n    if not isinstance(uid,int) or not 0<uid<2**32 or not isinstance(region,int):return None\n    try:x,y=float(character[\'x\']),float(character[\'y\'])\n    except (TypeError,ValueError,KeyError):return None\n    if not math.isfinite(x) or not math.isfinite(y):return None\n    role=\'H\' if config.get(\'hunter\') else \'F\' if config.get(\'follower\') else \'L\'\n    return \'!CRPOS {} {} {:.3f} {:.3f} {} {}\'.format(uid,region,x,y,role,1 if bot.get_party() else 0)\n\n\ndef ap_private(name,message):\n    return False  # No private Party discovery or handshake messages.\n\n\ndef ap_handle_chat(channel,sender,message):\n    return isinstance(message, str) and message.startswith((\'!CRPT \', \'!CRPOS \'))\n\n\ndef ap40_announce():\n    return  # No private beacons; party invitations are manual.\n\n\ndef event_loop():\n    _ap40_event_base()\n    ap40_announce()\n\n\n# Start following a saved leader after Party join/reappearance. No route/buy replay.\naf_party_state={\'owner\':None,\'paused\':False,\'next\':0.0}\n_af_party_event=event_loop\n_af_party_stop=local_stop\n_af_party_enable=enable_following\n_af_party_refresh=refresh_optional_controls\n\n\ndef af_party_owner():\n    owner=current_identity()\n    if af_party_state[\'owner\']!=owner:\n        af_party_state.update(owner=owner,paused=False,next=0.0)\n    return owner\n\n\ndef auto_follow_party_changed(checked):\n    af_party_owner()\n    if checked:\n        af_party_state[\'paused\']=False\n        enable_following()\n    say(\'Tu theo khi vao PT: \'+(\'BAT\' if checked else \'TAT\')+\'. Luu cau hinh de giu lua chon.\')\n\n\ndef local_stop():\n    af_party_owner();af_party_state[\'paused\']=True\n    return _af_party_stop()\n\n\ndef enable_following():\n    af_party_owner();af_party_state[\'paused\']=False\n    return _af_party_enable()\n\n\ndef refresh_optional_controls():\n    _af_party_refresh()\n    hunter=bool(QtBind.isChecked(gui,hunter_check));follower=bool(QtBind.isChecked(gui,follower_check)) and not hunter\n    QtBind.move(gui,auto_follow_party_check,230 if hunter else 125 if follower else -2000,192 if hunter else 244)\n\n\ndef af_party_target():\n    character=bot.get_character_data() or {}\n    party=bot.get_party() or {}\n    allowed=names(config.get(\'leaders\',\'\'))\n    preferred=names(config.get(\'follow\',\'\'))\n    candidates=[]\n    for member in party.values():\n        aliases=ap_aliases(member)\n        if not aliases & allowed or aliases & own_names():continue\n        if preferred and not aliases & preferred:continue\n        if not member.get(\'player_id\') or member.get(\'dead\') or member.get(\'hp_percent\')==0:continue\n        if not ap40_near(member) or not trace_region_reachable(character,member):continue\n        name=member.get(\'name\') or member.get(\'job_name\')\n        if name:candidates.append((str(name),member))\n    return sorted(candidates,key=lambda pair:norm(pair[0]))[0] if candidates else (None,None)\n\n\ndef af_party_tick():\n    global follow_request,follow_override,standalone_follow\n    if manual_npc_guard():\n        return\n    if trade_fault:\n        return\n    if not af_party_owner() or not config or not config.get(\'auto_follow_party\',True):return\n    if not QtBind.isChecked(gui,auto_follow_party_check):return\n    if not (config.get(\'hunter\') or config.get(\'follower\')):return\n    if follow_blocked or af_party_state[\'paused\']:return\n    character=bot.get_character_data() or {}\n    if not character or character.get(\'dead\') or not bot.get_party():return\n    # Existing Trace/rejoin logic owns an already requested follow session.\n    if active or follow_request:return\n    for name in (\'follower_state\',\'finish_context\',\'recovery\',\'return_request\',\'local_sale\',\'convoy_controller\',\n                 \'route_crossing\',\'bt_recall\',\'loop_pending\',\'loop_return\'):\n        if globals().get(name):return\n    now=time.monotonic()\n    if now<af_party_state[\'next\']:return\n    af_party_state[\'next\']=now+3\n    target,member=af_party_target()\n    if not target:return\n    pet=alive_transport() if config.get(\'follower\') else None\n    follow_override=target\n    standalone_follow=True\n    follow_request={\'owner\':identity,\'target\':target,\'next\':now,\'deadline\':float(\'inf\'),\n                    \'independent\':True,\'persistent\':True,\'needs_transport\':bool(pet),\'mount_tries\':0}\n    say(\'Tu theo PT: da gap Leader \'+target+\' trong 40m; bat theo, khong mua/ban/chay lai script.\')\n    follow_request_tick()\n\n\ndef event_loop():\n    _af_party_event()\n    af_party_tick()\n\n\nrefresh_optional_controls()\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n# Explicit coordinate recall. Owns caravan movement exclusively until completion/cancel.\nguard_call = None\nguard_call_seen = {}\n_gc_base_chat = handle_chat\n_gc_base_event = event_loop\n_gc_base_stop = stop_owned\n_gc_base_teleported = teleported\n_gc_base_disconnected = disconnected\n_gc_base_go = run_go\n_gc_base_follow = start_follow_target\n_gc_base_stop_follow = stop_following\n_gc_base_silkroad = handle_silkroad\n\n\ndef stop_owned():\n    global guard_call\n    guard_call = None\n    return _gc_base_stop()\n\n\n\ndef run_go(*args, **kwargs):\n    if guard_call:gc_cancel(\'da yeu cau chay tuyen moi\')\n    return _gc_base_go(*args, **kwargs)\n\n\ndef start_follow_target(*args, **kwargs):\n    if guard_call:gc_cancel(\'da yeu cau theo moi\')\n    return _gc_base_follow(*args, **kwargs)\n\n\ndef stop_following(*args, **kwargs):\n    if guard_call:gc_cancel(\'da yeu cau dung theo\')\n    return _gc_base_stop_follow(*args, **kwargs)\n\n\ndef gc_busy():\n    for name in (\'bt_recall\', \'return_request\', \'recovery\', \'route_crossing\',\n                 \'ferry_pending\', \'follower_state\', \'finish_context\', \'local_sale\'):\n        if globals().get(name):\n            return name\n    if merchant_step and not merchant_step.get(\'direct\'):\n        return \'mua/ban NPC\'\n    return None\n\n\ndef gc_cancel(reason):\n    global guard_call\n    guard_call = None\n    local_stop()  # Also blocks auto-follow from restarting the abandoned command.\n    stop_at_current_position()\n    say(\'GOI BT: \'+reason+\'; da dung, khong tu chay tiep.\')\n\n\ndef gc_begin():\n    global guard_call\n    if guard_call:\n        say(\'GOI BT: dang goi; khong gui trung. Tam dung de huy roi goi lai.\')\n        return\n    if not config or config.get(\'hunter\') or config.get(\'follower\') or not (own_names() & names(config.get(\'leaders\',\'\'))):\n        return\n    if not bot.get_party():\n        say(\'GOI BT: can cung Party.\')\n        return\n    busy = gc_busy()\n    if busy:\n        say(\'GOI BT: dang \'+busy+\'; doi xu ly xong roi goi lai.\')\n        return\n    character = bot.get_character_data() or {}\n    point = snapshot_position(character)\n    if not point or character.get(\'dead\'):\n        say(\'GOI BT: chua doc duoc vi tri Leader song.\')\n        return\n    configured = QtBind.text(gui, follow_box).strip() or config.get(\'guards\',\'\')\n    targets = []\n    for name in configured.split(\',\'):\n        name=name.strip()\n        if not name or norm(name) in own_names() or convoy_name(name) in trade_followers:\n            continue\n        member=resolve_follow_target(name)\n        if member and norm(member.get(\'name\') or name) not in {norm(x) for x in targets}:\n            targets.append(member.get(\'name\') or name)\n    if not targets:\n        say(\'GOI BT: nhap ten Bao tieu cung Party vao o nhan lenh; khong nhap acc Buon phu.\')\n        return\n    resume=bool(active and trip)\n    old_loop=loop_enabled\n    local_stop()\n    globals()[\'follow_stop_guard\']=None\n    stop_at_current_position()\n    token=uuid.uuid4().hex[:16]\n    # Split by target to keep Party chat below its length limit.\n    messages=[]\n    for target in targets:\n        data=[target,point[\'region\'],round(point[\'x\'],1),round(point[\'y\'],1),round(point[\'z\'],1)]\n        payload=base64.b64encode(json.dumps(data,separators=(\',\',\':\'),ensure_ascii=False).encode()).decode()\n        message=\'!CRCALL \'+token+\' \'+payload\n        if len(message)>120:\n            say(\'GOI BT: ten/toa do qua dai de gui an toan; Leader van dung.\')\n            return\n        messages.append(message)\n    now=time.monotonic()\n    guard_call={\'role\':\'leader\',\'owner\':identity,\'point\':point,\'targets\':targets,\n                \'deadline\':now+180,\'resume\':resume,\'old_loop\':old_loop,\n                \'found\':{},\'uids\':{},\'messages\':messages,\'sent\':now,\'tries\':1}\n    if not all(control_party(message) for message in messages):\n        gc_cancel(\'khong gui duoc lenh Party\')\n        return\n    say(\'GOI BT: Leader dung cho {}; toa do {:.1f}, {:.1f}. Chi tiep tuc khi thay du Bao tieu trong 15m lien tuc 2s.\'.format(\', \'.join(targets),point[\'x\'],point[\'y\']))\n\n\ndef gc_receive(player, message):\n    global guard_call\n    if not config or not config.get(\'hunter\') or not trusted_leader(player) or not party_member(player):\n        return\n    parts=message.split()\n    if len(parts)!=3 or len(parts[1])!=16 or any(c not in \'0123456789abcdef\' for c in parts[1]):\n        return\n    try:\n        if len(parts[2])>100:\n            return\n        data=json.loads(base64.b64decode(parts[2],validate=True).decode(\'utf-8\'))\n        if not isinstance(data,list) or len(data)!=5:\n            return\n        data=dict(zip((\'n\',\'r\',\'x\',\'y\',\'z\'),data))\n        if norm(data[\'n\']) not in own_names():\n            return\n        region=data[\'r\']\n        if not isinstance(region,int) or isinstance(region,bool):\n            return\n        point=snapshot_position({\'region\':region,\'x\':data[\'x\'],\'y\':data[\'y\'],\'z\':data[\'z\']})\n        if not point or any(abs(point[k])>100000 for k in (\'x\',\'y\',\'z\')):\n            return\n    except (ValueError,KeyError,TypeError,UnicodeError):\n        return\n    key=(identity,norm(player),parts[1])\n    now=time.monotonic()\n    for old,stamp in list(guard_call_seen.items()):\n        if now-stamp>600:guard_call_seen.pop(old,None)\n    if key in guard_call_seen:\n        return\n    guard_call_seen[key]=now\n    if guard_call:\n        say(\'GOI BT: dang chay lenh khac; dung lenh cu truoc khi goi lai.\')\n        return\n    busy=gc_busy()\n    if busy:\n        say(\'GOI BT: dang \'+busy+\'; chua nhan lenh chay toa do.\')\n        return\n    character=bot.get_character_data() or {}\n    current=snapshot_position(character)\n    if not current or character.get(\'dead\'):\n        return\n    # Outdoor adjacent region sectors may share world coordinates; no dungeon/ferry crossing.\n    if current[\'region\']!=region and not nearby_outdoor_position(current,point,500):\n        say(\'GOI BT: khac khu/qua xa de chay truc tiep; khong tu qua pha hay dich chuyen.\')\n        return\n    local_stop()\n    globals()[\'follow_stop_guard\']=None\n    cancel_native_follow(hold=current,stop_botting=True)\n    stopper=getattr(bot,\'stop_bot\',None)\n    if callable(stopper):stopper()\n    bot.stop_trace()\n    bot.stop_script()\n    guard_call={\'role\':\'guard\',\'owner\':identity,\'leader\':player,\'point\':point,\n                \'deadline\':now+180,\'last_move\':float(\'-inf\'),\'progress_at\':now,\n                \'anchor\':current,\'found_since\':None,\'leader_uid\':None}\n    say(\'GOI BT: nhan toa do {:.1f}, {:.1f} tu {}; dang chay ve, khong dung bua.\'.format(point[\'x\'],point[\'y\'],player))\n\n\ndef gc_tick():\n    global guard_call, follow_override, standalone_follow\n    context=guard_call\n    if not context:return\n    if current_identity()!=context[\'owner\'] or not config:\n        gc_cancel(\'nhan vat/cau hinh thay doi\')\n        return\n    character=bot.get_character_data() or {}\n    current=snapshot_position(character)\n    if not current or character.get(\'dead\') or not bot.get_party():\n        gc_cancel(\'nhan vat chet, mat Party hoac chua co vi tri\')\n        return\n    now=time.monotonic()\n    if now>=context[\'deadline\']:\n        gc_cancel(\'het 180s, CHUA xac nhan gap nhau\')\n        return\n    busy=gc_busy()\n    if busy:\n        gc_cancel(\'luong \'+busy+\' da bat dau\')\n        return\n    point=context[\'point\']\n    if current[\'region\']!=point[\'region\'] and not nearby_outdoor_position(current,point,500):\n        gc_cancel(\'khac khu dich den\')\n        return\n    if context[\'role\']==\'leader\':\n        if math.hypot(current[\'x\']-point[\'x\'],current[\'y\']-point[\'y\'])>5:\n            gc_cancel(\'Leader da roi vi tri goi, can goi lai toa do moi\')\n            return\n        ready=True\n        for target in context[\'targets\']:\n            member=resolve_follow_target(target)\n            visible=visible_escort_member(member,current)\n            close=visible and math.hypot(visible[\'x\']-current[\'x\'],visible[\'y\']-current[\'y\'])<=15\n            uid=visible.get(\'player_id\') if close else None\n            if not close:\n                context[\'found\'].pop(target,None);context[\'uids\'].pop(target,None);ready=False\n            else:\n                if context[\'uids\'].get(target)!=uid:\n                    context[\'found\'][target]=now;context[\'uids\'][target]=uid\n                if now-context[\'found\'][target]<2:ready=False\n        if ready:\n            guard_call=None\n            say(\'GOI BT: da thay du Bao tieu hien quanh Leader trong 15m lien tuc 2s.\')\n            if context[\'resume\']:\n                set_loop(context[\'old_loop\'])\n                run_go()\n            return\n        # Repeat the identical token; a receiver never restarts its movement on duplicates.\n        if context[\'tries\']<3 and now-context[\'sent\']>=5:\n            for message in context[\'messages\']:control_party(message)\n            context[\'sent\']=now;context[\'tries\']+=1\n        set_state(\'GOI BT: Leader dung cho Bao tieu (con {}s)\'.format(int(context[\'deadline\']-now)))\n        return\n    leader=context[\'leader\']\n    if not trusted_leader(leader) or not party_member(leader):\n        gc_cancel(\'Leader khong con duoc phep/trong Party\')\n        return\n    member=resolve_follow_target(leader)\n    visible=visible_escort_member(member,current)\n    close=visible and math.hypot(visible[\'x\']-current[\'x\'],visible[\'y\']-current[\'y\'])<=15\n    if close:\n        if context[\'leader_uid\']!=visible[\'player_id\']:\n            context[\'found_since\']=now;context[\'leader_uid\']=visible[\'player_id\']\n        if now-context[\'found_since\']>=2:\n            guard_call=None\n            enable_following()\n            follow_override=member.get(\'name\') or leader\n            standalone_follow=True\n            try:\n                accepted=start_follow_target(follow_override)\n                if accepted is False:\n                    local_stop()\n                    say(\'GOI BT: da gap Leader nhung Trace chua duoc chap nhan; da dung, can goi lai.\')\n                else:\n                    say(\'GOI BT: da gap Leader; chuyen sang theo.\')\n            except Exception as error:\n                local_stop()\n                say(\'GOI BT: da gap nhung chua theo duoc: \'+str(error))\n        else:stop_at_current_position()\n        return\n    context[\'found_since\']=None;context[\'leader_uid\']=None\n    distance=math.hypot(current[\'x\']-point[\'x\'],current[\'y\']-point[\'y\'])\n    if distance<=5:\n        stop_at_current_position()\n        set_state(\'GOI BT: da toi toa do, CHUA thay Leader; dung cho\')\n        return\n    anchor=context[\'anchor\']\n    if math.hypot(current[\'x\']-anchor[\'x\'],current[\'y\']-anchor[\'y\'])>=2:\n        context[\'anchor\']=current;context[\'progress_at\']=now\n    elif now-context[\'progress_at\']>=15:\n        gc_cancel(\'15s khong tien duoc, co the vuong vat can; can go tay/duong vong\')\n        return\n    if now-context[\'last_move\']>=2:\n        result=bot.move_to(point[\'x\'],point[\'y\'],point[\'z\'])\n        context[\'last_move\']=now\n        if result is False:\n            gc_cancel(\'phBot tu choi move_to\')\n            return\n    set_state(\'GOI BT: chay ve Leader, con {:.1f}m\'.format(distance))\n\n\ndef handle_chat(channel, player, message):\n    load_identity()\n    if channel==4 and isinstance(message,str) and isinstance(player,str):\n        if bt_normalize(message)==\'GOI BT\':\n            if norm(player) in own_names():gc_begin()\n            return\n        if message.startswith(\'!CRCALL \'):\n            gc_receive(player,message)\n            return\n        if guard_call and party_member(player) and trusted_leader(player):\n            # Explicit newer commands win; no old coordinate task can restart afterward.\n            command=bt_normalize(message)\n            if command in (\'VE BT\',\'CUOI BT\',\'VE\',\'CUOI\'):\n                gc_cancel(\'nhan lenh moi tu Leader\')\n    return _gc_base_chat(channel,player,message)\n\n\n\ndef handle_silkroad(opcode, data):\n    # Own Party chat is not reported through handle_chat on all phBot builds.\n    if opcode==0x7025 and len(data)>=4 and data[0]==4:\n        try:\n            message=ferry_decode_chat_string(data,2)\n            if bt_normalize(message)==\'GOI BT\':\n                handle_chat(4,(bot.get_character_data() or {}).get(\'name\',\'\'),message)\n        except (ValueError,UnicodeError,struct.error,TypeError):\n            pass\n    return _gc_base_silkroad(opcode,data)\n\n\ndef event_loop():\n    if guard_call:\n        try:gc_tick()\n        except Exception as error:gc_cancel(\'loi: \'+str(error))\n        return  # No Trace, auto-follow, merchant, ferry or recovery movement competes.\n    return _gc_base_event()\n\n\ndef teleported():\n    if guard_call:gc_cancel(\'nhan vat vua dich chuyen; huy toa do cu\')\n    return _gc_base_teleported()\n\n\ndef disconnected():\n    global guard_call\n    guard_call=None;guard_call_seen.clear()\n    return _gc_base_disconnected()\n\n\npass  # Startup notice intentionally silenced; runtime logging is unchanged.\n\n\n# Wide route layout: native 740x300 canvas, no changes to movement/trade engines.\n_wide_base_refresh = refresh_optional_controls\n\n\ndef refresh_optional_controls():\n    _wide_base_refresh()\n    hunter=bool(QtBind.isChecked(gui,hunter_check))\n    follower=bool(QtBind.isChecked(gui,follower_check)) and not hunter\n    QtBind.move(gui,party_heading,-2000,27)  # Remove the redundant Party-management title.\n    if hunter:\n        for name,x,y in ((\'btn_invite_selected\',508,149),(\'btn_kick_selected\',508,174),\n                         (\'btn_refresh_party_list\',508,199)):\n            QtBind.move(gui,ui_registry[name][0],x,y)\n        return\n    if follower:\n        for name,x,y in ((\'party_list\',548,125),(\'btn_invite_selected\',654,149),\n                         (\'btn_kick_selected\',654,174),(\'btn_refresh_party_list\',654,199)):\n            QtBind.move(gui,ui_registry[name][0],x,y)\n        return\n    positions={\n        \'script_box\':(8,136),\'btn_choose_script\':(8,157),\n        \'purchase_label\':(100,160),\'buy_goods_box\':(145,157),\n        \'escort_20_check\':(8,182),\'escort_30_check\':(54,182),\'escort_50_check\':(100,182),\n        \'btn_save_settings\':(150,180),\'auto_party_check\':(8,205),\n        \'party_list\':(248,203),\'btn_invite_selected\':(358,202),\n        \'btn_kick_selected\':(440,202),\'btn_refresh_party_list\':(522,202),\n        \'btn_diagnose_follow\':(604,202),\n        \'transport_stop_check\':(338,177),\'transport_return_check\':(412,177),\n        \'transport_recover_check\':(494,177),\n        \'btn_local_go\':(8,242),\'btn_local_stop\':(88,242),\'new_start_check\':(181,242),\n        \'step_label\':(291,246),\'step_box\':(329,242),\n        \'loop_on_check\':(378,244),\'loop_off_check\':(464,244),\n        \'btn_sell_team\':(568,242),\'loop_label\':(651,246),\n        \'tracking_heading\':(8,267),\'btn_activate_follow\':(76,264),\n        \'btn_stop_following\':(199,264),\'btn_team_follow\':(310,264),\n        \'btn_team_unfollow\':(411,264),\'status_label\':(8,286),\n    }\n    for name,(x,y) in positions.items():\n        QtBind.move(gui,ui_registry[name][0],x,y)\n    QtBind.move(gui,transport_heading,248,179)\n    QtBind.move(gui,hh_controls_heading,8,224)\n\n\nrefresh_optional_controls()\n\n\ndef ap_observe_private_result(data):\n    global _ap_last_private\n    _ap_last_private = None  # No discovery PMs, so no rejection tracking.\n\n\n_ap_probe_base_silkroad=handle_silkroad\n\n\ndef handle_silkroad(opcode,data):\n    global _ap_last_private\n    if opcode==0x7025 and data and data[0]==2:\n        # Keep metadata only for our technical PMs; never record private-chat content.\n        try:\n            recipient,end=decode_control_chat_string(data,2)\n            message,end=decode_control_chat_string(data,end)\n            if (end==len(data) and _ap_last_private and norm(recipient)==norm(_ap_last_private[\'name\'])\n                    and message.startswith((\'!CRPT \',\'!CRPOS \'))):\n                _ap_last_private[\'sequence\']=data[1]\n            else:_ap_last_private=None\n        except (ValueError,UnicodeError,struct.error,TypeError):\n            _ap_last_private=None\n    return _ap_probe_base_silkroad(opcode,data)\n\n\n\n# Filter only the technical chat echo to the game client; still process every command.\n_quiet_base_chat = handle_chat\n_quiet_base_joymax = handle_joymax\n_quiet_seen = {}\n\n\ndef quiet_internal_message(message):\n    if not isinstance(message,str): return False\n    parts=message.split()\n    if len(parts)<3 or parts[0] not in (\'!CR1\',\'!CR2\',\'!CRB\',\'!CRW\',\'!CRF\',\'!CRSTOP\',\'!CRCALL\'):\n        return False\n    # Covers current token syntax and legacy team-name + token messages.\n    return any(len(token) in (12,16) and all(c in \'0123456789abcdef\' for c in token)\n               for token in parts[1:3])\n\n\ndef quiet_internal_sender(player):\n    return isinstance(player,str) and (norm(player) in own_names() or party_member(player))\n\n\ndef handle_chat(channel,player,message):\n    if channel==4 and quiet_internal_message(message) and quiet_internal_sender(player):\n        now=time.monotonic();key=(norm(player),message)\n        # Packet fallback and the ordinary chat callback may both report the same message.\n        for old,stamp in list(_quiet_seen.items()):\n            if now-stamp>2:_quiet_seen.pop(old,None)\n        if now-_quiet_seen.get(key,float(\'-inf\'))<0.5:return\n        if len(_quiet_seen)>=512:_quiet_seen.clear()\n        _quiet_seen[key]=now\n    return _quiet_base_chat(channel,player,message)\n\n\ndef handle_joymax(opcode,data):\n    result=_quiet_base_joymax(opcode,data)\n    if opcode==0xB025:\n        ap_observe_private_result(data)\n    if opcode!=0x3026 or not data or data[0]!=4:\n        return result\n    try:\n        player,end=decode_control_chat_string(data,1)\n        message,end=decode_control_chat_string(data,end)\n        if end!=len(data) or not quiet_internal_sender(player) or not quiet_internal_message(message):\n            return result\n        handle_chat(4,player,message)  # Process before optionally suppressing the client echo.\n        if QtBind.isChecked(gui,hide_internal_chat_check):\n            return False\n    except (ValueError,UnicodeError,struct.error,TypeError):\n        pass  # Unknown packet layout stays visible; never drop an undecoded message.\n    return result\n\n\ndef quiet_chat_changed(checked):\n    say(\'Chat noi bo: \'+(\'AN trong game, lenh van xu ly binh thuong.\' if checked else \'HIEN trong game.\'))\n\n\nhide_internal_chat_check=QtBind.createCheckBox(gui,\'quiet_chat_changed\',\'Ẩn chat nội bộ\',535,264)\nQtBind.setChecked(gui,hide_internal_chat_check,(config or {}).get(\'hide_internal_chat\',True) is True)\n\n\n# Manual NPC interaction has priority over coordinate/Trace movement.\n_npc_guard_base_event=event_loop\n\n\ndef manual_npc_guard():\n    global active,follow_mode\n    if npc_session.get(\'owner\')!=identity or npc_session.get(\'state\') not in (\'opening\',\'open\'):\n        return False\n    if follower_state or finish_context or recovery or return_request:\n        return False  # A native transaction/return already owns this NPC lifecycle.\n    if follow_mode or follow_request or (config and (config.get(\'hunter\') or config.get(\'follower\'))):\n        if follow_mode:\n            bot.stop_trace()\n            active=False;follow_mode=None\n        set_state(\'Dang mo NPC: tam ngung theo, dong NPC roi moi theo lai\')\n        return True\n    return False\n\n\ndef event_loop():\n    if manual_npc_guard():return\n    return _npc_guard_base_event()\n\n\n_npc_open_base_silkroad=handle_silkroad\n\n\ndef handle_silkroad(opcode,data):\n    result=_npc_open_base_silkroad(opcode,data)\n    if opcode==0x7046:\n        manual_npc_guard()\n    return result\n\n'

