def table_orders():
    queue = []
    configured = False
    bag = inventory()
    if not bag:
        raise ValueError('Chưa đọc được túi. Vào game và thử lại trước khi mua.')
    for model, name, amount_box in stone_rows:
        amount_text = QtBind.text(gui, amount_box).strip()
        if not amount_text:
            continue
        try:
            amount = int(amount_text)
            if amount < 0:
                raise ValueError
        except ValueError:
            raise ValueError('Đá {} ({}): nhập số viên nguyên từ 0 trở lên.'.format(name, model))
        if amount:
            configured = True
            stock = stone_count(model, bag)
            shortage = max(0, amount - stock)
            log('[SROMix] {} ({}): túi {}/{}, {}.'.format(
                name, model, stock, amount,
                'mua thêm {}'.format(shortage) if shortage else 'đủ, bỏ qua'))
            if shortage:
                queue.append((STONE_SHOP_SLOTS[model], shortage))
    return queue, configured


