def set_skill_rows(saved):
    stored = saved.get('skill_grid')
    rows = saved.get('skill_rows')
    if not isinstance(rows, list) or len(rows) != 2:
        rows = (saved.get('skills'), None)
    switches = saved.get('skill_switches')
    if not isinstance(switches, list) or len(switches) != 2:
        switches = (True, False)
    for group, switch in enumerate(skill_switches):
        defaults = default_skill_grid[group]
        if isinstance(stored, list) and len(stored) == 2 and isinstance(stored[group], list):
            grid[group] = [tuple(row) for row in stored[group] if isinstance(row, list) and len(row) == 4]
        elif isinstance(rows[group], str):
            try:
                grid[group] = [(uid, 0, False, False) for uid in parse_ids(rows[group])]
            except ValueError:
                grid[group] = []
        else:
            grid[group] = list(defaults)
        draw_skill_page(group)
        QtBind.setChecked(gui, switch, switches[group] is True)


def parse_ids(raw):
    ids = tuple(dict.fromkeys(int(part.strip()) for part in raw.replace(';', ',').replace('\n', ',').split(',') if part.strip()))
    if any(not 0 < uid <= 0xffffffff for uid in ids):
        raise ValueError('ID skill nằm ngoài phạm vi hợp lệ.')
    return ids


def draw_skill_page(group):
    start = 0
    for index, (id_box, ms_box, cut, off) in enumerate(skill_widgets[group], start):
        uid, delay, interrupt, disabled = grid[group][index] if index < len(grid[group]) else (0, 0, False, False)
        QtBind.setText(gui, id_box, str(uid) if uid else '')
        QtBind.setText(gui, ms_box, str(delay) if uid else '')
        QtBind.setChecked(gui, cut, interrupt is True)
        QtBind.setChecked(gui, off, disabled is True)
    # page_labels removed — no visible 1–10 spinner/column between ID and ms.


def capture_skill_page(group):
    start = 0
    rows = []
    for id_box, ms_box, cut, off in skill_widgets[group]:
        raw = str(QtBind.text(gui, id_box) or '').strip()
        uid = int(raw) if raw else 0
        delay = int(QtBind.text(gui, ms_box) or 0) if raw else 0
        if not 0 <= uid <= 0xffffffff or not 0 <= delay <= 10000:
            raise ValueError('Kiểm tra ID skill và ms (0–10000).')
        rows.append((uid, delay, bool(QtBind.isChecked(gui, cut)), bool(QtBind.isChecked(gui, off))))
    missing = start + SKILL_PAGE_SIZE - len(grid[group])
    grid[group].extend([(0, 0, False, False)] * missing)
    grid[group][start:start + SKILL_PAGE_SIZE] = rows


def move_skill_row(group, index, direction):
    """Swap one Bảo kê skill row with its neighbor; keep id/ms/Tắt/Ngắt together."""
    try:
        capture_skill_page(group)
    except ValueError as error:
        status(str(error))
        return
    rows = grid[group]
    destination = index + direction
    if destination < 0 or index < 0:
        return
    while len(rows) <= max(index, destination):
        rows.append((0, 0, False, False))
    if not rows[index][0]:
        return
    rows[index], rows[destination] = rows[destination], rows[index]
    while rows and not rows[-1][0]:
        rows.pop()
    draw_skill_page(group)
    skill_row_changed(False)


