    QtBind.append(gui, imbue_choice, current)
    for uid, data in (bot.get_skills() or {}).items():
        uid = uid_of(uid)
        if uid and is_imbue(data):
            label = '%s [%d]' % (data.get('name') or data.get('servername') or 'Tay phép', uid)
            QtBind.append(gui, imbue_choice, label)
            if uid == selected:
                current = label
    if selected and current == '(Không dùng)':
        current = 'Tay phép đã lưu [%d]' % selected
        QtBind.append(gui, imbue_choice, current)
    QtBind.setText(gui, imbue_choice, current)


