def skill_seconds(data, key):
    try:
        seconds = float(data.get(key) or 0) / 1000
        return seconds if math.isfinite(seconds) and seconds > 0 else 0.0
    except (TypeError, ValueError, OverflowError):
        return 0.0


def try_imbue(skills, now):
    global imbue_id, imbue_until, imbue_retry_at
    uid = selected_imbue() if QtBind.isChecked(gui, imbue_box) else 0
    if uid != imbue_id:
        imbue_id, imbue_until, imbue_retry_at = uid, 0.0, 0.0
    if not uid or now < max(imbue_until, imbue_retry_at):
        return False
    data = skills.get(uid) or skills.get(str(uid))
    if not is_imbue(data) or data.get('can_cast') is False:
        return False
    get_active = getattr(bot, 'get_active_skills', None)
    active = get_active() if callable(get_active) else None
    if data.get('active') is True or (isinstance(active, dict) and (uid in active or str(uid) in active)):
        return False
    imbue_retry_at = now + max(1.0, skill_seconds(data, 'cooldown'))
    if bot.inject_joymax(0x7074, struct.pack('<BBIB', 1, 4, uid, 0), False) is False:
        imbue_retry_at = now + 2.0
        return False
    session['ready'] = now + max(0.2, min(5.0, skill_seconds(data, 'cast_time') + 0.1))
    return True


