def inventory():
    return (bot.get_inventory() or {}).get('items') or []


def model_of(item):
    return uid_of(item.get('model')) if isinstance(item, dict) else 0


def is_shield(item):
    if not model_of(item):
        return False
    if '_SHIELD_' in str(item.get('servername') or '').upper():
        return True
    return (bot.get_item(model_of(item)) or {}).get('tid2') == 4


