def capture_shield_set():
    global shield_set
    if not owner or defense:
        status('Lấy bộ khiên khi đã vào game và đang ngoài chế độ phòng thủ.')
        return
    items = inventory()
    if len(items) < 8 or not model_of(items[6]) or not is_shield(items[7]):
        status('Trang bị vũ khí một tay và khiên rồi bấm Lấy bộ khiên.')
        return
    shield_set = (model_of(items[6]), model_of(items[7]))
    show_shield_set()
    status('Đã lấy bộ khiên. Bấm Lưu để dùng lần sau.')


def health_ratio(character):
    try:
        current, maximum = float(character['hp']), float(character['hp_max'])
        if math.isfinite(current) and math.isfinite(maximum) and 0 < current <= maximum:
            return current / maximum
    except (KeyError, TypeError, ValueError, OverflowError):
        pass
    return None


def equip_step(state, items, desired, now):
    pending = state.get('pending')
    if pending:
        destination, model, deadline = pending
        if model_of(items[destination]) != model and now < deadline:
            return False, 'chờ xác nhận đổi đồ'
        state['pending'] = None
    actual = (model_of(items[6]), model_of(items[7]))
    if actual == desired:
        return True, 'đã đổi đồ'
    if now < state.get('retry_at', 0.0):
        return False, 'chờ thử lại bộ đồ'
    state['retry_at'] = now + 1.0
    # Remove the shield before equipping a two-handed weapon or restoring arrows.
    if actual[1] and actual[1] != desired[1] and is_shield(items[7]) and (actual[0] != desired[0] or not desired[1]):
        destination = next((slot for slot in range(13, min(len(items), 256)) if not items[slot]), None)
        if destination is None:
            return False, 'túi đầy, chưa cất được khiên'
        source, expected = 7, actual[1]
    else:
        destination = 6 if actual[0] != desired[0] else 7
        expected = desired[destination - 6]
        if not expected:
            source = destination
            destination = next((slot for slot in range(13, min(len(items), 256)) if not items[slot]), None)
            if destination is None:
                return False, 'túi đầy, chưa cất được đồ'
            expected = actual[source - 6]
        else:
            matches = [slot for slot in range(13, min(len(items), 256)) if model_of(items[slot]) == expected]
            if len(matches) != 1:
                return False, 'thiếu hoặc trùng ID đồ %d' % expected
            source = matches[0]
    if bot.inject_joymax(0x7034, struct.pack('<BBBH', 0, source, destination, 0), False) is False:
        return False, 'phBot chưa gửi được lệnh đổi đồ'
    state['pending'] = (destination, expected, now + 3.0)
    return False, 'đang đổi đồ'


def defense_tick(character, now):
    global defense
    armed = QtBind.isChecked(gui, defense_box)
    ratio = health_ratio(character)
    if defense is None:
        if not armed or ratio is None or ratio >= 0.35:
            return False
        defense = dict(attack_set=None)
        release(True)
    if armed and ratio is not None:
        if ratio >= 0.60:
            defense['recovered'] = True
        elif ratio < 0.35:
            defense['recovered'] = False
    restoring = not armed or defense.get('recovered', False)
    if restoring and defense['attack_set'] is None:
        defense = None
        return False
    items = inventory()
    if len(items) < 8:
        status('Phòng thủ · bám Trade · đang chờ hành trang.')
        return True
    if defense['attack_set'] is None:
        if not shield_set or not model_of(items[6]):
            status('Phòng thủ · bám Trade · chưa có bộ khiên hoặc vũ khí đang mặc.')
            return True
        defense['attack_set'] = (model_of(items[6]), model_of(items[7]))
    desired = defense['attack_set'] if restoring else shield_set
    if not desired:
        status('Phòng thủ · bám Trade · chưa có bộ khiên.')
        return True
    ready, message = equip_step(defense, items, desired, now)
    if restoring and ready:
        defense = None
        status('Đã mặc lại bộ đánh · tiếp tục bám Trade.')
        return False
    status(('Hồi phục · mặc lại bộ đánh · ' if restoring else 'Phòng thủ · bám Trade · ') + message + '.')
    return True


def bow_changed(_checked):
    pass  # Read on each scan so either range can be selected while escorting.


def toggle(checked):
    global enabled, skill_ids, skill_options
    if not checked:
        enabled = False
        release(True)
        status('Bảo kê đang tắt.')
        return
    try:
        if not owner:
            raise ValueError('Vào game trước khi bật.')
        skill_options = {}
        for group, switch in enumerate(skill_switches):
            if QtBind.isChecked(gui, switch):
                capture_skill_page(group)
                for uid, delay, interrupt, off in grid[group]:
                    if uid and not off:
                        skill_options.setdefault(uid, (delay, interrupt))
        requested = tuple(skill_options)
        if not requested:
            raise ValueError('Tích F1 hoặc F2 và nhập ID skill cho nhóm đã chọn.')
        known = bot.get_skills() or {}
        skill_ids = tuple(skill for skill in requested if skill in known or str(skill) in known)
        if not skill_ids:
            raise ValueError('Acc này chưa có ID skill nào trong bảng Bảo kê.')
        enabled = True
        for skill in requested:
            if skill not in skill_ids:
                bot.log('[Bảo kê] Bỏ qua ID skill chưa có: %d.' % skill)
        status('Chờ Bảo tiêu Trace theo acc Trade.')
    except (TypeError, ValueError) as error:
        enabled = False
        QtBind.setChecked(gui, enabled_box, False)
        status('Chưa bật: ' + str(error))


def uid_of(value):
    try:
        uid = int(value or 0)
        return uid if 0 < uid <= 0xffffffff else 0
    except (TypeError, ValueError, OverflowError):
        return 0


def aliases(row):
    return {caravan.norm(row.get(key)) for key in ('name', 'job_name') if row.get(key)}


def hostile(player):
    if player.get('hostile') is True or player.get('is_enemy') is True:
        return True
    side = str(player.get('job_type') or player.get('job') or '').strip().casefold()
    if side in ('thief', 'đạo tặc', 'dao tac'):
        return True
    color = str(player.get('name_color') or player.get('color') or '').strip().casefold()
    return color in ('red', 'purple', 'đỏ', 'tím', 'do', 'tim')


def distance(a, b):
    try:
        if b.get('region') is not None and not caravan.trace_region_reachable(a, b):
            return None
        value = math.hypot(float(a['x']) - float(b['x']), float(a['y']) - float(b['y']))
        return value if math.isfinite(value) else None
    except (KeyError, TypeError, ValueError, OverflowError):
        return None


def candidates(character, trade, party, radius, now):
    ally_uids = {uid_of(member.get('player_id')) for member in party}
    ally_uids.add(uid_of(character.get('player_id')))
    ally_names = aliases(character) | aliases(trade)
    for member in party:
        ally_names.update(aliases(member))
    self_guild = str(character.get('guild') or '').strip().casefold()
    found = []
    for raw_uid, player in (bot.get_players() or {}).items():
        if not isinstance(player, dict) or player.get('dead') or player.get('hp_percent') == 0:
            continue
        uid = uid_of(raw_uid)
        if not uid or uid in ally_uids or aliases(player) & ally_names or now < retired.get(uid, 0):
            continue
        player_guild = str(player.get('guild') or '').strip().casefold()
        if self_guild and self_guild == player_guild:
            continue
        gap = distance(trade, dict(player, player_id=uid))
        if gap is None or gap > radius:
            continue
        attacked_trade = attackers.get(uid, 0) > now
        if attacked_trade or hostile(player):
            found.append((not attacked_trade, gap, uid, player))
    return sorted(found, key=lambda entry: entry[:3])


def same_follow(intent):
    return (caravan.active and caravan.follow_intent is intent
            and not caravan.follow_blocked and caravan.follow_mode == 'guard_pvp')


def release(resume):
    global session
    active, session = session, None
    if active is None or not same_follow(active['intent']):
        return
    if resume:
        try:
            bot.inject_joymax(0x7074, b'\x02', False)
        finally:
            caravan.start_follow_target(active['intent']['target'])


def handoff(intent, target, now):
    global session
    if bot.stop_trace() is False:
        status('phBot chưa dừng Trace. Sẽ thử lại.')
        return False
    caravan.follow_mode = 'guard_pvp'
    session = dict(intent=intent, uid=target, index=0, waiting=None, ready=now + 0.15, misses=0, idle_since=now)
    bot.inject_joymax(0x7074, b'\x02', False)
    return True


def event_loop():
    global next_scan
    character = bot.get_character_data() or {}
    key = current_owner(character)
    if key != owner:
        load(key)
    if not enabled and defense is None and not QtBind.isChecked(gui, defense_box):
        return
    now = time.monotonic()
    if now < next_scan:
        return
    next_scan = now + 0.15
    for cache in (attackers, retired):
        for uid, until in tuple(cache.items()):
            if until <= now:
                del cache[uid]
    intent = caravan.follow_intent
    radius = caravan.selected_escort_radius() if (caravan.config or {}).get('hunter') else 0
    if (not (caravan.config or {}).get('hunter') or not caravan.active or not intent
            or caravan.follow_blocked or character.get('dead')
            or caravan.follow_mode not in ('trace', 'guard_pvp')):
        release(not character.get('dead'))
        status('Chờ vai Bảo tiêu Trace và chọn bán kính bảo kê.')
        return
    if defense_tick(character, now) or not enabled or not caravan.active:
        return
    if not radius:
        release(True)
        status('Chọn bán kính bảo kê để bật PvP.')
        return
    trade = caravan.resolve_follow_target(intent['target'])
    if not trade or not caravan.follower_position_usable(trade, character):
        release(True)
        status('Chưa có vị trí Trade · ưu tiên bám lại.')
        return
    if not trade.get('player_id'):
        release(True)
        status('Trade ngoài tầm nhìn · tiếp tục Trace.')
        return
    if session and (distance(trade, character) or 0) > radius:
        release(True)
        status('Bảo tiêu ra ngoài bán kính · tiếp tục bám Trade.')
        return
    party = [member for member in (bot.get_party() or {}).values() if isinstance(member, dict)]
    enemies = candidates(character, trade, party, radius, now)
    if not enemies:
        release(True)
        status('Đang bám Trade · phBot xử lý NPC/quái.')
        return
    if session and not same_follow(session['intent']):
        release(False)
    current = next((row for row in enemies if session and row[2] == session['uid']), None)
    target = enemies[0] if current is None or (current[0] and not enemies[0][0]) else current
    uid, player = target[2:]
    if session is None and not handoff(intent, uid, now):
        next_scan = now + 0.75
        return
    if session['uid'] != uid:
        session.update(uid=uid, waiting=None, ready=now + 0.15, misses=0, idle_since=now, cut_due=False)
        bot.inject_joymax(0x7074, b'\x02', False)
    status('Đang bảo vệ Trade · UID %d · cách Trade %.1f m.' % (uid, target[1]))
    if now < session['ready']:
        return
    if session.pop('cut_due', False):
        bot.inject_joymax(0x7074, bytes((2,)), False)
        session['ready'] = now + 0.15
        return
    if session['waiting'] is not None:
        session['waiting'] = None
        session['misses'] += 1
        if session['misses'] >= len(skill_ids):
            retired[uid] = now + 2.0
            release(True)
            status('Chưa có xác nhận skill · trả Trace và tiếp tục quét.')
            return
    gap = distance(character, dict(player, player_id=uid))
    if gap is None:
        return
    cast_range = 15.0 if QtBind.isChecked(gui, bow_box) else 6.0
    if gap > cast_range:
        if now >= session.get('move_at', 0.0):
            session['move_at'] = now + 0.45
            fraction = (gap - cast_range + 0.5) / gap
            x, y = float(character['x']), float(character['y'])
            x += (float(player['x']) - x) * fraction
            y += (float(player['y']) - y) * fraction
            bot.move_to(x, y, float(character.get('z') or 0.0))
        if now - session['idle_since'] >= 3.0:
            retired[uid] = now + 1.0
            release(True)
            status('Chưa áp sát được · tiếp tục bám Trade.')
        return
    skills = bot.get_skills() or {}
    if try_imbue(skills, now):
        return
    for _ in skill_ids:
        skill = skill_ids[session['index']]
        session['index'] = (session['index'] + 1) % len(skill_ids)
        data = skills.get(skill) or skills.get(str(skill))
        if not isinstance(data, dict) or data.get('can_cast') is False:
            continue
        session.update(waiting=skill, ready=now + 0.65, idle_since=now)
        if bot.inject_joymax(0x7074, struct.pack('<BBIBI', 1, 4, skill, 1, uid), False) is False:
            session['ready'] = now + 0.15
        return
    if now - session['idle_since'] >= 2.0:
        retired[uid] = now + 1.0
        release(True)
        status('Các skill đang hồi · trả Trace và tiếp tục quét.')


def handle_joymax(opcode, data):
    global imbue_until
    if not enabled or opcode != 0xB070 or len(data or b'') < 11 or data[0] != 1:
        return
    skill, source = struct.unpack_from('<II', data, 3)
    if imbue_id and skill == imbue_id and source == uid_of((bot.get_character_data() or {}).get('player_id')):
        skills = bot.get_skills() or {}
        entry = skills.get(skill) or skills.get(str(skill)) or {}
        imbue_until = time.monotonic() + skill_seconds(entry, 'duration')
    if len(data) < 19:
        return
    target = struct.unpack_from('<I', data, 15)[0]
    intent = caravan.follow_intent
    trade = caravan.resolve_follow_target(intent['target']) if intent else None
    if trade and source and source != target and target == uid_of(trade.get('player_id')):
        attackers[source] = time.monotonic() + 4.0
    if (not session or source != uid_of((bot.get_character_data() or {}).get('player_id'))
            or target != session['uid'] or skill != session['waiting']):
        return
    skills = bot.get_skills() or {}
    data = skills.get(skill) or skills.get(str(skill)) or {}
    try:
        cast = max(0.2, float(data.get('cast_time', 0)) / 1000)
    except (TypeError, ValueError):
        cast = 0.5
    now = time.monotonic()
    delay, interrupt = skill_options.get(skill, (0, False))
    gap = delay / 1000 if interrupt else max(min(5., cast), delay / 1000)
    session.update(waiting=None, ready=now + gap, misses=0, idle_since=now, cut_due=interrupt)


def teleported():
    if session and same_follow(session['intent']):
        caravan.pause_trace_for_rejoin('Trade vừa đổi khu vực')
    release(False)
    attackers.clear()
    retired.clear()


def disconnected():
    load(None)
