def _hh_dispatch(hook, *args):
    allowed = True
    for page, module in _hh_modules.items():
        callback = getattr(module, hook, None)
        if not callable(callback):
            continue
        try:
            if callback(*args) is False:
                allowed = False
        except Exception as error:
            # One engine must not prevent the other from receiving game events.
            now = _time.monotonic()
            key = (page, hook, str(error))
            if now - _hh_hook_errors.get(key, float('-inf')) >= 15:
                _hh_hook_errors[key] = now
                _bot.log('[hoang hiep/%s] %s: %s' % (page, hook, error))
    return allowed


